    [
      "בִימֵי רַבָּן גַּמְלִיאֵל רַבּוּ הָאֶפִּיקוֹרוֹסִין בְּיִשְׂרָאֵל וְהָיוּ מְצֵרִים לְיִשְׂרָאֵל וּמְסִיתִין אוֹתָן לָשׁוּב מֵאַחֲרֵי הַשֵּׁם. וְכֵיוָן שֶׁרָאָה שֶׁזּוֹ גְּדוֹלָה מִכָּל צָרְכֵי בְּנֵי אָדָם עָמַד הוּא וּבֵית דִּינוֹ וְהִתְקִין בְּרָכָה אַחַת שֶׁתִּהְיֶה בָּהּ שְׁאֵלָה מִלִּפְנֵי הַשֵּׁם לְאַבֵּד הָאֶפִּיקוֹרוֹסִין וְקָבַע אוֹתָהּ בַּתְּפִלָּה כְּדֵי שֶׁתִּהְיֶה עֲרוּכָה בְּפִי הַכּל. נִמְצְאוּ כָּל הַבְּרָכוֹת שֶׁבַּתְּפִלָּה תְּשַׁע עֶשְׂרֵה בְּרָכוֹת:",
      "בְּכָל תְּפִלָּה שֶׁבְּכָל יוֹם מִתְפַּלֵּל אָדָם תְּשַׁע עֶשְׂרֵה בְּרָכוֹת אֵלּוּ עַל הַסֵּדֶר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁמָּצָא דַּעְתּוֹ מְכֻוֶּנֶת וּלְשׁוֹנוֹ תְּמַהֵר לִקְרוֹת. אֲבָל אִם הָיָה טָרוּד וְדָחוּק אוֹ שֶׁקָּצְרָה לְשׁוֹנוֹ מֵהִתְפַּלֵּל יִתְפַּלֵּל שָׁלֹשׁ רִאשׁוֹנוֹת וּבְרָכָה אַחַת מֵעֵין כָּל הָאֶמְצָעִיּוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וְיֵצֵא יְדֵי חוֹבָתוֹ:",
      "וְזוֹהִי הַבְּרָכָה שֶׁתִּקְּנוּ מֵעֵין כָּל הָאֶמְצָעִיּוֹת. הֲבִינֵנוּ יְיָ׳‎ אֱלֹהֵינוּ לָדַעַת אֶת דְּרָכֶיךָ וּמוֹל אֶת לְבָבֵנוּ לְיִרְאָתְךָ לְסוֹלֵחַ הֱיֵה לָנוּ לִהְיוֹת גְּאוּלִים רַחֲקֵנוּ מִמַּכְאוֹב וְדַשְׁנֵנוּ וְשַׁכְּנֵנוּ בִּנְאוֹת אַרְצְךָ וּנְפוֹצִים מֵאַרְבַּע תְּקַבֵּץ וְהַתּוֹעִים בְּדַעְתְּךָ יִשָּׁפְטוּ וְעַל הָרְשָׁעִים תָּנִיף יָדְךָ וְיִשְׂמְחוּ צַדִּיקִים בְּבִנְיַן עִירֶךָ וּבְתִקּוּן הֵיכָלֶךָ וּבִצְמִיחַת קֶרֶן לְדָוִד עַבְדֶּךָ וּבַעֲרִיכַת נֵר לְבֶן יִשַּׁי מְשִׁיחֶךָ טֶרֶם נִקְרָא אַתָּה תַּעֲנֶה כַּדָּבָר שֶׁנֶּאֱמַר <small>(ישעיה סה כד)</small> ״וְהָיָה טֶרֶם יִקְרָאוּ וַאֲנִי אֶעֱנֶה עוֹד הֵם מְדַבְּרִים וַאֲנִי אֶשְׁמָע״ כִּי אַתָּה הוּא עוֹנֶה בְּכָל עֵת פּוֹדֶה וּמַצִּיל מִכָּל צוּקָה בָּרוּךְ אַתָּה יְיָ׳‎ שׁוֹמֵעַ תְּפִלָּה:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים בִּימוֹת הַחַמָּה. אֲבָל בִּימוֹת הַגְּשָׁמִים אֵינוֹ מִתְפַּלֵּל הֲבִינֵנוּ מִפְּנֵי שֶׁצָּרִיךְ לוֹמַר שְׁאֵלָה בְּבִרְכַּת הַשָּׁנִים. וְכֵן בְּמוֹצָאֵי שַׁבָּתוֹת וְיָמִים טוֹבִים אֵינוֹ מִתְפַּלֵּל הֲבִינֵנוּ מִפְּנֵי שֶׁצָּרִיךְ לוֹמַר הַבְדָּלָה בְּחוֹנֵן הַדַּעַת:",
      "וּבְשַׁבָּתוֹת וּבְיָמִים טוֹבִים מִתְפַּלֵּל שֶׁבַע בְּרָכוֹת בְּכָל תְּפִלָּה וּתְפִלָּה מֵאַרְבַּע תְּפִלּוֹת שֶׁל אוֹתוֹ הַיּוֹם. שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וּבְרָכָה אֶמְצָעִית מֵעֵין אוֹתוֹ הַיּוֹם. בְּשַׁבָּתוֹת חוֹתְמִין בִּבְרָכָה אֶמְצָעִית מְקַדֵּשׁ הַשַּׁבָּת. וּבָרְגָלִים חוֹתֵם בָּהּ מְקַדֵּשׁ יִשְׂרָאֵל וְהַזְּמַנִּים. וְאִם הָיָה שַׁבָּת וְיוֹם טוֹב חוֹתְמִים בָּהּ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְהַזְּמַנִּים. בְּרֹאשׁ הַשָּׁנָה חוֹתְמִין בָּהּ מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ יִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן. וְאִם הָיָה שַׁבָּת חוֹתֵם בָּהּ מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְפִלַּת עַרְבִית וְשַׁחֲרִית וּמִנְחָה. אֲבָל תְּפִלַּת הַמּוּסָפִין שֶׁל רֹאשׁ הַשָּׁנָה מִתְפַּלֵּל תֵּשַׁע בְּרָכוֹת שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת שֶׁל כָּל יוֹם וְשָׁלֹשׁ אֶמְצָעִיּוֹת. רִאשׁוֹנָה מִן הָאֶמְצָעִיּוֹת עִנְיָנָהּ מַלְכֻיּוֹת. שְׁנִיָּה זִכְרוֹנוֹת. שְׁלִישִׁית שׁוֹפָרוֹת. וְחוֹתֵם בְּכָל אַחַת מֵהֶן מֵעִנְיָנָהּ:",
      "בְּיוֹם הַכִּפּוּרִים מִתְפַּלֵּל בְּכָל תְּפִלָּה מֵחָמֵשׁ תְּפִלּוֹת שֶׁבַע בְּרָכוֹת. שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וְאֶמְצָעִיּוֹת מֵעֵין הַיּוֹם. וְחוֹתֵם בְּכָל אַחַת מֵהֶן מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ יִשְׂרָאֵל וְיוֹם הַכִּפּוּרִים. וְאִם חָל לִהְיוֹת בְּשַׁבָּת חוֹתֵם בְּכָל תְּפִלָּה מֵהֶן מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְיוֹם הַכִּפּוּרִים:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים בְּיוֹם צוֹם שֶׁל כָּל שָׁנָה וְשָׁנָה אֲבָל בְּיוֹם צוֹם שֶׁל שְׁנַת הַיּוֹבֵל מִתְפַּלֵּל תְּפִלַּת הַמּוּסָפִים תֵּשַׁע בְּרָכוֹת כְּמוֹ שֶׁהִתְפַּלֵּל בְּמוּסַף רֹאשׁ הַשָּׁנָה וְהֵם אוֹתָן הַבְּרָכוֹת עַצְמָן לֹא פָּחוֹת וְלֹא יוֹתֵר וְאֵין מִתְפַּלְּלִין אוֹתָן אֶלָּא בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג:",
      "בְּכָל תְּפִלָּה מֵהַתְּפִלּוֹת פּוֹתֵחַ קֹדֶם לִבְרָכָה רִאשׁוֹנָה <small>(תהילים נא יז)</small> ״יְיָ׳‎ שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ״. וּכְשֶׁהוּא חוֹתֵם בְּסוֹף הַתְּפִלָּה אוֹמֵר <small>(תהילים יט טו)</small> ״יִהְיוּ לְרָצוֹן אִמְרֵי פִי״ וְגוֹ׳‎ וְאַחַר כָּךְ צוֹעֵד לַאֲחוֹרָיו:",
      "בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד מִתְפַּלֵּל עַרְבִית שַׁחֲרִית וּמִנְחָה תְּשַׁע עֶשְׂרֵה בְּרָכוֹת כִּשְׁאָר הַיָּמִים וְאוֹמֵר בָּעֲבוֹדָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ יַעֲלֶה וְיָבוֹא. בְּמוּסָף בְּחֻלּוֹ שֶׁל מוֹעֵד מִתְפַּלֵּל תְּפִלַּת הַמּוּסָף כְּמוֹ שֶׁמִּתְפַּלֵּל בְּיוֹם טוֹב. וּבְרָאשֵׁי חֳדָשִׁים מִתְפַּלֵּל שֶׁבַע בְּרָכוֹת שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וְאֶמְצָעִית מֵעֵין קָרְבַּן רֹאשׁ חֹדֶשׁ וְחוֹתֵם בָּהּ מְקַדֵּשׁ יִשְׂרָאֵל וְרָאשֵׁי חֳדָשִׁים:",
      "שַׁבָּת שֶׁחָלָה בְּחֻלּוֹ שֶׁל מוֹעֵד וְכֵן רֹאשׁ חֹדֶשׁ שֶׁחָל לִהְיוֹת בְּשַׁבָּת מִתְפַּלֵּל עַרְבִית וְשַׁחֲרִית וּמִנְחָה שֶׁבַע בְּרָכוֹת כִּשְׁאָר הַשַּׁבָּתוֹת וְאוֹמֵר יַעֲלֶה וְיָבוֹא בָּעֲבוֹדָה. בְּמוּסָף מַתְחִיל בִּבְרָכָה אֶמְצָעִית בְּעִנְיַן שַׁבָּת וּמַשְׁלִים בְּעִנְיַן שַׁבָּת וְאוֹמֵר קְדֻשַּׁת הַיּוֹם בְּאֶמְצַע בְּרָכָה וְחוֹתֵם בָּהּ בְּרָאשֵׁי חֳדָשִׁים מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְרָאשֵׁי חֳדָשִׁים. וּבְחֻלּוֹ שֶׁל מוֹעֵד חוֹתֵם בָּהּ כְּמוֹ שֶׁהוּא חוֹתֵם בְּיוֹם טוֹב שֶׁחָל לִהְיוֹת בְּשַׁבָּת:",
      "וְיוֹם טוֹב שֶׁחָל לִהְיוֹת בְּאֶחָד בְּשַׁבָּת מִתְפַּלֵּל בִּבְרָכָה רְבִיעִית בַּלַּיְלָה וַתּוֹדִיעֵנוּ מִשְׁפְּטֵי צִדְקֶךָ וַתְּלַמְּדֵנוּ לַעֲשׂוֹת חֻקֵּי רְצוֹנֶךָ וַתִּתֶּן לָנוּ יְיָ׳‎ אֱלֹהֵינוּ קְדֻשַּׁת שַׁבָּת וּכְבוֹד מוֹעֵד וַחֲגִיגַת הָרֶגֶל בֵּין קְדֻשַּׁת שַׁבָּת לִקְדֻשַּׁת יוֹם טוֹב הִבְדַּלְתָּ וְאֶת יוֹם הַשְּׁבִיעִי מִשֵּׁשֶׁת יְמֵי הַמַּעֲשֶׂה הִקְדַּשְׁתָּ (וְהִבְדַּלְתָּ וְהִקְדַּשְׁתָּ אֶת עַמְּךָ יִשְׂרָאֵל בִּקְדֻשָּׁתְךָ) וַתִּתֵּן לָנוּ ה׳‎ אֱלֹהֵינוּ מוֹעֲדִים לְשִׂמְחָה חַגִּים וּזְמַנִּים לְשָׂשוֹן וְכוּ׳‎. וּבְמוֹצָאֵי שַׁבָּת וּבְמוֹצָאֵי יוֹם טוֹב שֶׁל כָּל הַשָּׁנָה מַבְדִּיל בְּאַתָּה חוֹנֵן אַף עַל פִּי שֶׁהוּא מַבְדִּיל עַל הַכּוֹס:",
      "בַּחֲנֻכָּה וּבְפוּרִים מוֹסִיפִין בְּהוֹדָאָה עַל הַנִּסִּים. שַׁבָּת שֶׁחָלָה לִהְיוֹת בַּחֲנֻכָּה מַזְכִּיר עַל הַנִּסִּים בְּמוּסָף כְּמוֹ שֶׁמַּזְכִּיר בִּשְׁאָר תְּפִלּוֹת:",
      "בִּימֵי הַתַּעֲנִית אֲפִלּוּ יָחִיד שֶׁהִתְעַנָּה מוֹסִיף בְּשׁוֹמֵעַ תְּפִלָּה עֲנֵנוּ וְכוּ׳‎. וּשְׁלִיחַ צִבּוּר אוֹמְרָהּ בְּרָכָה בִּפְנֵי עַצְמָהּ בֵּין גּוֹאֵל לְרוֹפֵא וְחוֹתֵם בָּהּ הָעוֹנֶה בְּעֵת צָרָה (וּמוֹשִׁיעַ). וְנִמְצָא מִתְפַּלֵּל עֶשְׂרִים בְּרָכוֹת. בְּתִשְׁעָה בְּאָב מוֹסִיפִין בְּבוֹנֵה יְרוּשָׁלָיִם רַחֵם יְיָ׳‎ אֱלֹהֵינוּ עָלֵינוּ וְעַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל הָעִיר הָאֲבֵלָה כוּ׳‎:",
      "כָּל יְמוֹת הַגְּשָׁמִים אוֹמֵר בִּבְרָכָה שְׁנִיָּה מוֹרִיד הַגֶּשֶׁם וּבִימוֹת הַחַמָּה מוֹרִיד הַטָּל. מֵאֵימָתַי אוֹמֵר מוֹרִיד הַגֶּשֶׁם מִתְּפִלַּת הַמּוּסָפִין שֶׁל יוֹם טוֹב הָאַחֲרוֹן שֶׁל חַג עַד תְּפִלַּת שַׁחֲרִית שֶׁל יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח. וּמִתְּפִלַּת הַמּוּסָפִין שֶׁל יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח אוֹמֵר מוֹרִיד הַטָּל:",
      "מִשִּׁבְעָה יָמִים בְּמַרְחֶשְׁוָן שׁוֹאֲלִין אֶת הַגְּשָׁמִים בְּבִרְכַּת שָׁנִים כָּל זְמַן שֶׁמַּזְכִּיר הַגֶּשֶׁם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאֶרֶץ יִשְׂרָאֵל. אֲבָל בְּשִׁנְעָר וּבְסוּרְיָא וּבְמִצְרַיִם וּבַמְּקוֹמוֹת הַסְּמוּכוֹת לְאֵלּוּ וְהַדּוֹמִין לָהֶן שׁוֹאֲלִין אֶת הַגְּשָׁמִים בְּיוֹם שִׁשִּׁים אַחַר תְּקוּפַת תִּשְׁרֵי:",
      "מְקוֹמוֹת שֶׁהֵן צְרִיכִין לִגְשָׁמִים בִּימוֹת הַחַמָּה כְּגוֹן אִיֵּי הַיָּם הָרְחוֹקִים שׁוֹאֲלִין אֶת הַגְּשָׁמִים בְּעֵת שֶׁהֵן צְרִיכִין לָהֶן בְּשׁוֹמֵעַ תְּפִלָּה. וּמְקוֹמוֹת שֶׁהֵן עוֹשִׂין יוֹם טוֹב שְׁנֵי יָמִים אוֹמֵר מוֹרִיד הַגֶּשֶׁם בִּתְפִלַּת מוּסָף שֶׁל יוֹם רִאשׁוֹן שֶׁל שְׁמִינִי עֲצֶרֶת וּמִתְפַּלֵּל וְהוֹלֵךְ כָּל יְמוֹת הַגְּשָׁמִים:",
      "כָּל הַשָּׁנָה כֻּלָּהּ חוֹתֵם בִּבְרָכָה שְׁלִישִׁית הָאֵל הַקָּדוֹשׁ וּבְבִרְכַּת עַשְׁתֵּי עֶשְׂרֵה מֶלֶךְ אוֹהֵב צְדָקָה וּמִשְׁפָּט וּבַעֲשֶׂרֶת הַיָּמִים שֶׁמֵּרֹאשׁ הַשָּׁנָה עַד מוֹצָאֵי יוֹם הַכִּפּוּרִים חוֹתֵם בַּשְּׁלִישִׁית הַמֶּלֶךְ הַקָּדוֹשׁ וּבְעַשְׁתֵּי עֶשְׂרֵה הַמֶּלֶךְ הַמִּשְׁפָּט:",
      "יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לְהוֹסִיף בַּעֲשֶׂרֶת יָמִים אֵלּוּ בִּבְרָכָה רִאשׁוֹנָה זָכְרֵנוּ לְחַיִּים כוּ׳‎ וּבַשְּׁנִיָּה מִי כָמוֹךָ אַב הָרַחֲמִים וְכוּ׳‎ וּבְהוֹדָאָה זְכֹר רַחֲמֶיךָ וְכוּ׳‎ וּמוֹסִיפִין בִּבְרָכָה אַחֲרוֹנָה בְּסֵפֶר חַיִּים וְכוּ׳‎. וְכֵן יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לְהוֹסִיף בַּעֲשֶׂרֶת יָמִים אֵלּוּ בִּבְרָכָה שְׁלִישִׁית וּבְכֵן תֵּן פַּחְדְּךָ וּבְכֵן וְכוּ׳‎ אֲבָל בְּרֹאשׁ הַשָּׁנָה וּבְיוֹם הַכִּפּוּרִים מִנְהָג פָּשׁוּט הוּא לְהוֹסִיף בַּשְּׁלִישִׁית וּבְכֵן תֵּן פַּחְדְּךָ וְכוּ׳‎:"
    ],
    [
      "תְּפִלַת הַשַּׁחַר מִצְוָתָהּ שֶׁיַּתְחִיל לְהִתְפַּלֵּל עִם הָנֵץ הַחַמָּה וּזְמַנָּהּ עַד סוֹף שָׁעָה רְבִיעִית שֶׁהִיא שְׁלִישִׁית הַיּוֹם. וְאִם עָבַר אוֹ טָעָה וְהִתְפַּלֵּל אַחַר אַרְבַּע עַד חֲצוֹת הַיּוֹם יָצָא יְדֵי חוֹבַת תְּפִלָּה. אֲבָל לֹא יָצָא יְדֵי חוֹבַת תְּפִלָּה בִּזְמַנָּהּ. שֶׁכְּשֵׁם שֶׁתְּפִלָּה מִצְוָה מִן הַתּוֹרָה כָּךְ מִצְוָה מִדִּבְרֵיהֶם לְהִתְפַּלֵּל אוֹתָהּ בִּזְמַנָּהּ כְּמוֹ שֶׁתִּקְנוּ לָנוּ חֲכָמִים וּנְבִיאִים:",
      "כְּבָר אָמַרְנוּ שֶׁתְּפִלַּת הַמִּנְחָה כְּנֶגֶד תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם תִּקְּנוּ זְמַנָּהּ. וּלְפִי שֶׁהָיָה הַתָּמִיד קָרֵב בְּכָל יוֹם בְּתֵשַׁע שָׁעוֹת וּמֶחֱצָה תִּקְּנוּ זְמַנָּהּ מִתֵּשַׁע שָׁעוֹת וּמֶחֱצָה וְהִיא הַנִּקְרֵאת מִנְחָה קְטַנָּה. וּלְפִי שֶׁבְּעֶרֶב הַפֶּסַח שֶׁחָל לִהְיוֹת בְּעֶרֶב שַׁבָּת הָיוּ שׁוֹחֲטִין אֶת הַתָּמִיד בְּשֵׁשׁ שָׁעוֹת וּמֶחֱצָה, אָמְרוּ שֶׁהַמִּתְפַּלֵּל מֵאַחַר שֵׁשׁ שָׁעוֹת וּמֶחֱצָה יָצָא. וּמִשֶּׁהִגִּיעַ זְמַן זֶה הִגִּיעַ זְמַן חִיּוּבָהּ וְזוֹ הִיא הַנִּקְרֵאת מִנְחָה גְּדוֹלָה:",
      "נָהֲגוּ אֲנָשִׁים הַרְבֵּה לְהִתְפַּלֵּל גְּדוֹלָה וּקְטַנָּה וְהָאַחַת רְשׁוּת. וְהוֹרוּ מִקְצָת הַגְּאוֹנִים שֶׁאֵין רָאוּי לְהִתְפַּלֵּל רְשׁוּת אֶלָּא הַגְּדוֹלָה. וְכֵן הַדִּין נוֹתֵן מִפְּנֵי שֶׁהִיא כְּנֶגֶד דָּבָר שֶׁאֵינוֹ תָּדִיר בְּכָל יוֹם. וְאִם הִתְפַּלֵּל הַגְּדוֹלָה חוֹבָה לֹא יִתְפַּלֵּל קְטַנָּה אֶלָּא רְשׁוּת:",
      "הָא לָמַדְתָּ שֶׁזְּמַן מִנְחָה גְּדוֹלָה מִשֵּׁשׁ שָׁעוֹת וּמֶחֱצָה עַד תֵּשַׁע שָׁעוֹת וּמֶחֱצָה. וּזְמַן מִנְחָה קְטַנָּה מִתֵּשַׁע שָׁעוֹת וּמֶחֱצָה עַד שֶׁיִּשָּׁאֵר מִן הַיּוֹם שָׁעָה וּרְבִיעַ. וְיֵשׁ לוֹ לְהִתְפַּלֵּל אוֹתָהּ עַד שֶׁתִּשְׁקַע הַחַמָּה:",
      "תְּפִלַּת הַמּוּסָפִין זְמַנָּהּ אַחַר תְּפִלַּת הַשַּׁחַר עַד שֶׁבַע שָׁעוֹת בַּיּוֹם. וְהַמִּתְפַּלֵּל אוֹתָהּ אַחַר שֶׁבַע שָׁעוֹת אַף עַל פִּי שֶׁפָּשַׁע יָצָא יְדֵי חוֹבָתוֹ מִפְּנֵי שֶׁזְּמַנָּהּ כָּל הַיּוֹם:",
      "תְּפִלַּת הָעֶרֶב אַף עַל פִּי שֶׁאֵינָהּ חוֹבָה הַמִּתְפַּלֵּל אוֹתָהּ זְמַנָּהּ מִתְּחִלַּת הַלַּיְלָה עַד שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר. ותְּפִלַּת נְעִילָה זְמַנָּה כְּדֵי שֶׁיַּשְׁלִים אוֹתָהּ סָמוּךְ לִשְׁקִיעַת הַחַמָּה:",
      "הַמִּתְפַּלֵּל תְּפִלָּה קֹדֶם זְמַנָּהּ לֹא יָצָא יְדֵי חוֹבָתוֹ וְחוֹזֵר וּמִתְפַּלֵּל אוֹתָהּ בִּזְמַנָּהּ. וְאִם הִתְפַּלֵּל תְּפִלַּת שַׁחֲרִית בִּשְׁעַת הַדְּחָק אַחַר שֶׁעָלָה עַמּוּד הַשַּׁחַר יָצָא. וְיֵשׁ לוֹ לְהִתְפַּלֵּל תְּפִלַּת עַרְבִית שֶׁל לֵילֵי שַׁבָּת בְּעֶרֶב שַׁבָּת קֹדֶם שֶׁתִּשְׁקַע הַחַמָּה. וְכֵן יִתְפַּלֵּל עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת בְּשַׁבָּת לְפִי שֶׁתְּפִלַּת עַרְבִית רְשׁוּת אֵין מְדַקְדְּקִין בִּזְמַנָּהּ. וּבִלְבַד שֶׁיִּקְרָא קְרִיאַת שְׁמַע בִּזְמַנָּהּ אַחַר צֵאת הַכּוֹכָבִים:",
      "כָּל מִי שֶׁעָבַר עָלָיו זְמַן תְּפִלָּה וְלֹא הִתְפַּלֵּל בְּמֵזִיד אֵין לוֹ תַּקָּנָה וְאֵינוֹ מְשַׁלֵּם. בְּשׁוֹגֵג אוֹ שֶׁהָיָה אָנוּס אוֹ טָרוּד מְשַׁלֵּם אוֹתָהּ תְּפִלָּה בִּזְמַן תְּפִלָּה הַסְּמוּכָה לָהּ. וּמַקְדִּים תְּפִלָּה שֶׁבִּזְמַנָּהּ וְאַחֲרֶיהָ מִתְפַּלֵּל אֶת הַתַּשְׁלוּמִין:",
      "כֵּיצַד. טָעָה וְלֹא הִתְפַּלֵּל שַׁחֲרִית וְעָבַר חֲצִי הַיּוֹם יִתְפַּלֵּל מִנְחָה שְׁתַּיִם. רִאשׁוֹנָה תְּפִלַּת מִנְחָה וְהַשְּׁנִיָּה תַּשְׁלוּמֵי שַׁחֲרִית. טָעָה וְלֹא הִתְפַּלֵּל מִנְחָה עַד שֶׁשָּׁקְעָה הַחַמָּה יִתְפַּלֵּל עַרְבִית שְׁתַּיִם. רִאשׁוֹנָה עַרְבִית וּשְׁנִיָּה תַּשְׁלוּמֵי מִנְחָה. טָעָה וְלֹא הִתְפַּלֵּל עַרְבִית עַד שֶׁעָלָה עַמּוּד הַשַּׁחַר מִתְפַּלֵּל שַׁחֲרִית שְׁתַּיִם. רִאשׁוֹנָה שַׁחֲרִית וְהַשְּׁנִיָּה תַּשְׁלוּמֵי עַרְבִית:",
      "טָעָה וְלֹא הִתְפַּלֵּל לֹא תְּפִלָּה זוֹ וְלֹא תְּפִלָּה הַסְּמוּכָה לָהּ אֵינוֹ מְשַׁלֵּם אֶלָּא אַחֲרוֹנָה בִּלְבַד. כֵּיצַד. טָעָה וְלֹא הִתְפַּלֵּל לֹא שַׁחֲרִית וְלֹא מִנְחָה מִתְפַּלֵּל עַרְבִית שְׁתַּיִם רִאשׁוֹנָה עַרְבִית וְהָאַחֲרוֹנָה תַּשְׁלוּמֵי מִנְחָה. אֲבָל שַׁחֲרִית אֵין לָהּ תַּשְׁלוּמִין שֶׁכְּבָר עָבַר זְמַנָּהּ. וְכֵן בִּשְׁאָר תְּפִלּוֹת:",
      "הָיוּ לְפָנָיו שְׁתֵּי תְּפִלּוֹת שֶׁל מִנְחָה וְשֶׁל מוּסָפִין מִתְפַּלֵּל שֶׁל מִנְחָה וְאַחַר כָּךְ מִתְפַּלֵּל שֶׁל מוּסָפִין. וְיֵשׁ מִי שֶׁמּוֹרֶה שֶׁאֵין עוֹשִׂין בְּצִבּוּר כֵּן כְּדֵי שֶׁלֹּא יִטְעוּ:"
    ],
    [
      "חֲמִשָּׁה דְּבָרִים מְעַכְּבִין אֶת הַתְּפִלָּה אַף עַל פִּי שֶׁהִגִּיעַ זְמַנָּה. טָהֳרַת יָדַיִם. וְכִסּוּי הָעֶרְוָה. וְטָהֳרַת מְקוֹם תְּפִלָּה. וּדְבָרִים הַחוֹפְזִים אוֹתוֹ. וְכַוָּנַת הַלֵּב:",
      "טָהֳרַת יָדַיִם כֵּיצַד. רוֹחֵץ יָדָיו בְּמַיִם עַד הַפֶּרֶק וְאַחַר כָּךְ יִתְפַּלֵּל. הָיָה מְהַלֵּךְ בַּדֶּרֶךְ וְהִגִּיעַ זְמַן תְּפִלָּה וְלֹא הָיָה לוֹ מַיִם. אִם הָיָה בֵּינוֹ וּבֵין הַמַּיִם אַרְבָּעָה מִילִין שֶׁהֵם שְׁמוֹנַת אֲלָפִים אַמָּה הוֹלֵךְ עַד מְקוֹם הַמַּיִם וְרוֹחֵץ וְאַחַר כָּךְ יִתְפַּלֵּל. הָיָה בֵּינוֹ וּבֵין הַמַּיִם יוֹתֵר עַל כֵּן מְקַנֵּחַ יָדָיו בִּצְרוֹר אוֹ בְּעָפָר אוֹ בְּקוֹרָה וּמִתְפַּלֵּל:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים לְפָנָיו אֲבָל אִם הָיָה מְקוֹם הַמַּיִם לַאֲחוֹרָיו אֵין מְחַיְּבִין אוֹתוֹ לַחֲזֹר לַאֲחוֹרָיו אֶלָּא עַד מִיל. אֲבָל אִם עָבַר מִן הַמַּיִם יוֹתֵר אֵינוֹ חַיָּב לַחֲזֹר אֶלָּא מְקַנֵּחַ יָדָיו וּמִתְפַּלֵּל. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵינוֹ מְטַהֵר לִתְפִלָּה אֶלָּא יָדָיו בִּלְבַד, בִּשְׁאָר תְּפִלּוֹת חוּץ מִתְּפִלַּת שַׁחֲרִית. אֲבָל שַׁחֲרִית רוֹחֵץ פָּנָיו יָדָיו וְרַגְלָיו וְאַחַר כָּךְ יִתְפַּלֵּל. וְאִם הָיָה רָחוֹק מִן הַמַּיִם מְקַנֵּחַ יָדָיו בִּלְבַד וְאַחַר כָּךְ יִתְפַּלֵּל:",
      "כָּל הַטְּמֵאִין רוֹחֲצִין יְדֵיהֶן בִּלְבַד כִּטְהוֹרִין וּמִתְפַּלְּלִים. אַף עַל פִּי שֶׁאֶפְשָׁר לָהֶם לִטְבּל וְלַעֲלוֹת מִטֻּמְאָתָן אֵין הַטְּבִילָה מְעַכֶּבֶת. וּכְבָר בֵּאַרְנוּ שֶׁעֶזְרָא תִּקֵּן שֶׁלֹּא יִקְרָא בַּעַל קֶרִי בִּלְבַד בְּדִבְרֵי תּוֹרָה עַד שֶׁיִּטְבּל. וּבֵית דִּין שֶׁעָמְדוּ אַחַר כֵּן הִתְקִינוּ אַף לִתְפִלָּה שֶׁלֹּא יִתְפַּלֵּל בַּעַל קֶרִי בִּלְבַד עַד שֶׁיִּטְבּל. וְלֹא מִפְּנֵי טֻמְאָה וְטָהֳרָה נָגְעוּ בָּהּ אֶלָּא כְּדֵי שֶׁלֹּא יִהְיוּ תַּלְמִידֵי חֲכָמִים מְצוּיִים אֵצֶל נְשׁוֹתֵיהֶן כְּתַרְנְגוֹלִים. וּמִפְּנֵי זֶה תִּקְּנוּ טְבִילָה לְבַעַל קֶרִי לְבַדּוֹ וְהוֹצִיאוּהוּ מִכְּלַל הַטְּמֵאִין:",
      "לְפִיכָךְ הָיוּ אוֹמְרִין בִּזְמַן תַּקָּנָה זוֹ שֶׁאֲפִלּוּ זָב שֶׁרָאָה קֶרִי וְנִדָּה שֶׁפָּלְטָה שִׁכְבַת זֶרַע וּמְשַׁמֶּשֶׁת שֶׁרָאֲתָה דַּם נִדָּה צְרִיכִין טְבִילָה לִקְרִיאַת שְׁמַע וְכֵן לִתְפִלָּה מִפְּנֵי הַקֶּרִי אַף עַל פִּי שֶׁהֵם טְמֵאִין. וְכֵן הַדִּין נוֹתֵן שֶׁאֵין טְבִילָה זוֹ מִפְּנֵי טָהֳרָה אֶלָּא מִפְּנֵי הַגְּזֵרָה שֶׁלֹּא יִהְיוּ מְצוּיִין אֵצֶל נְשׁוֹתֵיהֶן תָּמִיד. וּכְבָר בָּטְלָה גַּם תַּקָּנָה זוֹ שֶׁל תְּפִלָּה לְפִי שֶׁלֹּא פָּשְׁטָה בְּכָל יִשְׂרָאֵל וְלֹא הָיָה כֹּחַ בַּצִּבּוּר לַעֲמֹד בָּהּ:",
      "מִנְהָג פָּשׁוּט בְּשִׁנְעָר וּבִסְפָרַד שֶׁאֵין בַּעַל קֶרִי מִתְפַּלֵּל עַד שֶׁרוֹחֵץ כָּל בְּשָׂרוֹ בְּמַיִם מִשּׁוּם <small>(עמוס ד יב)</small> ״הִכּוֹן לִקְרַאת אֱלֹהֶיךָ יִשְׂרָאֵל״. בַּמֶּה דְּבָרִים אֲמוּרִים בְּבָרִיא אוֹ בְּחוֹלֶה שֶׁבָּעַל. אֲבָל חוֹלֶה שֶׁרָאָה קֶרִי לְאָנְסוֹ פָּטוּר מִן הָרְחִיצָה וְאֵין בָּזֶה מִנְהָג. וְכֵן זָב שֶׁרָאָה קֶרִי וְנִדָּה שֶׁפָּלְטָה שִׁכְבַת זֶרַע אֵין בָּהֶן מִנְהָג אֶלָּא מְקַנְּחִין עַצְמָן וְרוֹחֲצִין יְדֵיהֶן וּמִתְפַּלְּלִין:",
      "כִּסּוּי הָעֶרְוָה כֵּיצַד. אַף עַל פִּי שֶׁכִּסָּה עֶרְוָתוֹ כְּדֶרֶךְ שֶׁמְּכַסִּין לִקְרִיאַת שְׁמַע לֹא יִתְפַּלֵּל עַד שֶׁיְּכַסֶּה אֶת לִבּוֹ. וְאִם לֹא כִּסָּה לִבּוֹ אוֹ שֶׁנֶּאֱנַס וְאֵין לוֹ בְּמָה יְכַסֶּה הוֹאִיל וְכִסָּה עֶרְוָתוֹ וְהִתְפַּלֵּל יָצָא. וּלְכַתְּחִלָּה לֹא יַעֲשֶׂה:",
      "טָהֳרַת מְקוֹם הַתְּפִלָּה כֵּיצַד. לֹא יִתְפַּלֵּל בִּמְקוֹם הַטִּנֹּפֶת וְלֹא בַּמֶּרְחָץ וְלֹא בְּבֵית הַכִּסֵּא וְלֹא בָּאַשְׁפָּה וְלֹא בְּמָקוֹם שֶׁאֵינוֹ בְּחֶזְקַת טָהֳרָה עַד שֶׁיִּבְדְּקֶנּוּ. כְּלָלוֹ שֶׁל דָּבָר כָּל מָקוֹם שֶׁאֵין קוֹרִין בּוֹ קְרִיאַת שְׁמַע אֵין מִתְפַּלְּלִין בּוֹ. וּכְשֵׁם שֶׁמַּרְחִיקִין מִצּוֹאָה וּמִמֵּי רַגְלַיִם וְרֵיחַ רַע וּמִן הַמֵּת וּמֵרְאִיַּת הָעֶרְוָה לִקְרִיאַת שְׁמַע כָּךְ מַרְחִיקִין לִתְפִלָּה:",
      "הַמִּתְפַּלֵּל וּמָצָא צוֹאָה בִּמְקוֹמוֹ הוֹאִיל וְחָטָא מִפְּנֵי שֶׁלֹּא בָּדַק עַד שֶׁלֹּא הִתְפַּלֵּל חוֹזֵר וּמִתְפַּלֵּל בְּמָקוֹם טָהוֹר. הָיָה עוֹמֵד בִּתְפִלָּה וּמָצָא צוֹאָה כְּנֶגְדּוֹ אִם יָכוֹל לְהַלֵּךְ לְפָנָיו כְּדֵי שֶׁיִּזְרְקֶנָּה לְאַחֲרָיו אַרְבַּע אַמּוֹת יְהַלֵּךְ וְאִם לָאו יְסַלְּקֶנָּה לַצְּדָדִין. וְאִם אֵינוֹ יָכוֹל יַפְסִיק. גְּדוֹלֵי הַחֲכָמִים לֹא הָיוּ מִתְפַּלְּלִים בְּבַיִת שֶׁיֵּשׁ בּוֹ שֵׁכָר וְלֹא בְּבַיִת שֶׁיֵּשׁ בּוֹ מוּרְיָיס בְּעֵת עִפּוּשׁוֹ מִפְּנֵי שֶׁרֵיחוֹ רַע אַף עַל פִּי שֶׁהַמָּקוֹם טָהוֹר:",
      "דְּבָרִים הַחוֹפְזִים אוֹתוֹ כֵּיצַד. אִם הָיָה צָרִיךְ לִנְקָבָיו לֹא יִתְפַּלֵּל. וְכָל הַצָּרִיךְ לִנְקָבָיו וְהִתְפַּלֵּל תְּפִלָּתוֹ תּוֹעֵבָה וְחוֹזֵר וּמִתְפַּלֵּל אַחַר שֶׁיַּעֲשֶׂה צְרָכָיו. וְאִם יָכוֹל לְהַעֲמִיד עַצְמוֹ כְּדֵי פַּרְסָה תְּפִלָּתוֹ תְּפִלָּה. וְאַף עַל פִּי כֵן לְכַתְּחִלָּה לֹא יִתְפַּלֵּל עַד שֶׁיִּבְדֹּק עַצְמוֹ יָפֶה יָפֶה וְיִבְדֹק נְקָבָיו וְיָסִיר כִּיחוֹ וְנִיעוֹ וְכָל הַדָּבָר הַטּוֹרְדוֹ וְאַחַר כָּךְ יִתְפַּלֵּל:",
      "מִי שֶׁגִּהֵק וּפִהֵק וְנִתְעַטֵּשׁ בִּתְפִלָּתוֹ אִם לִרְצוֹנוֹ הֲרֵי זֶה מְגֻנֶּה. וְאִם בָּדַק גּוּפוֹ קֹדֶם שֶׁיִּתְפַּלֵּל וּבָא לְאָנְסוֹ אֵין בְּכָךְ כְּלוּם. נִזְדַּמֵּן לוֹ רֹק בִּתְפִלָּתוֹ מַבְלִיעוֹ בְּטַלִּיתוֹ אוֹ בְּבִגְדוֹ. וְאִם הָיָה מִצְטַעֵר בְּכָךְ זוֹרְקוֹ בְּיָדוֹ לַאֲחוֹרָיו כְּדֵי שֶׁלֹּא יִצְטַעֵר בַּתְּפִלָּה וְנִמְצָא טָרוּד. יָצָא מִמֶּנּוּ רוּחַ מִלְּמַטָּה כְּשֶׁהוּא עוֹמֵד בִּתְפִלָּה שֶׁלֹּא לְדַעְתּוֹ שׁוֹהֶה עַד שֶׁתִּכְלֶה הָרוּחַ וְחוֹזֵר לִתְפִלָּתוֹ:",
      "בִּקֵּשׁ לְהוֹצִיא רוּחַ מִלְּמַטָּה וְנִצְטַעֵר הַרְבֵּה וְאֵינוֹ יָכוֹל לְהַעֲמִיד עַצְמוֹ מְהַלֵּךְ לְאַחֲרָיו אַרְבַּע אַמּוֹת וּמַמְתִּין עַד שֶׁתִּכְלֶה הָרוּחַ. וְאוֹמֵר רִבּוֹן כָּל הָעוֹלָמִים יְצַרְתָּנוּ נְקָבִים נְקָבִים חֲלוּלִים חֲלוּלִים גָּלוּי וְיָדוּעַ לְפָנֶיךָ חֶרְפָּתֵנוּ וּכְלִמָּתֵנוּ חֶרְפָּה וּכְלִמָּה בְּחַיֵּינוּ תּוֹלֵעָה וְרִמָּה בְּמִיתָתֵנוּ וְחוֹזֵר לִמְקוֹמוֹ וּמִתְפַּלֵּל:",
      "הָיָה עוֹמֵד בִּתְפִלָּה וְנָטְפוּ מֵי רַגְלָיו עַל בִּרְכָּיו מַמְתִּין עַד שֶׁיִּכְלוּ הַמַּיִם וְחוֹזֵר לַמָּקוֹם שֶׁפָּסַק. וְאִם שָׁהָה כְּדֵי לִגְמֹר אֶת הַתְּפִלָּה חוֹזֵר לָרֹאשׁ:",
      "וְכֵן הַמַּשְׁתִּין מַיִם שׁוֹהֶה כְּדֵי הִלּוּךְ ד׳‎ אַמּוֹת וְאַחַר כָּךְ יִתְפַּלֵּל. וּמִשֶּׁהִתְפַּלֵּל שׁוֹהֶה אַחַר תְּפִלָּתוֹ כְּדֵי הִלּוּךְ אַרְבַּע אַמּוֹת וְאַחַר כָּךְ מַשְׁתִּין כְּדֵי שֶׁיִּפְסֹק דִּבְרֵי הַתְּפִלָּה מִפִּיו:",
      "כַּוָּנַת הַלֵּב כֵּיצַד. כָּל תְּפִלָּה שֶׁאֵינָהּ בְּכַוָּנָה אֵינָהּ תְּפִלָּה. וְאִם הִתְפַּלֵּל בְּלֹא כַּוָּנָה חוֹזֵר וּמִתְפַּלֵּל בְּכַוָּנָה. מָצָא דַּעְתּוֹ מְשֻׁבֶּשֶׁת וְלִבּוֹ טָרוּד אָסוּר לוֹ לְהִתְפַּלֵּל עַד שֶׁתִּתְיַשֵּׁב דַּעְתּוֹ. לְפִיכָךְ הַבָּא מִן הַדֶּרֶךְ וְהוּא עָיֵף אוֹ מֵצֵר אָסוּר לוֹ לְהִתְפַּלֵּל עַד שֶׁתִּתְיַשֵּׁב דַּעְתּוֹ. אָמְרוּ חֲכָמִים יִשְׁהֶה שְׁלֹשָׁה יָמִים עַד שֶׁיָּנוּחַ וְתִתְקָרֵר דַּעְתּוֹ וְאַחַר כָּךְ יִתְפַּלֵּל:",
      "כֵּיצַד הִיא הַכַּוָּנָה. שֶׁיְּפַנֶּה אֶת לִבּוֹ מִכָּל הַמַּחֲשָׁבוֹת וְיִרְאֶה עַצְמוֹ כְּאִלּוּ הוּא עוֹמֵד לִפְנֵי הַשְּׁכִינָה. לְפִיכָךְ צָרִיךְ לֵישֵׁב מְעַט קֹדֶם הַתְּפִלָּה כְּדֵי לְכַוֵּן אֶת לִבּוֹ וְאַחַר כָּךְ יִתְפַּלֵּל בְּנַחַת וּבְתַחֲנוּנִים וְלֹא יַעֲשֶׂה תְּפִלָּתוֹ כְּמִי שֶׁהָיָה נוֹשֵׂא מַשּׂאוֹי וּמַשְׁלִיכוֹ וְהוֹלֵךְ לוֹ. לְפִיכָךְ צָרִיךְ לֵישֵׁב מְעַט אַחַר הַתְּפִלָּה וְאַחַר כָּךְ יִפָּטֵר. חֲסִידִים הָרִאשׁוֹנִים הָיוּ שׁוֹהִין שָׁעָה אַחַת קֹדֶם תְּפִלָּה וְשָׁעָה אַחַת לְאַחַר תְּפִלָּה וּמַאֲרִיכִין בִּתְפִלָּה שָׁעָה:",
      "שִׁכּוֹר אַל יִתְפַּלֵּל מִפְּנֵי שֶׁאֵין לוֹ כַּוָּנָה. וְאִם הִתְפַּלֵּל תְּפִלָּתוֹ תּוֹעֵבָה. לְפִיכָךְ חוֹזֵר וּמִתְפַּלֵּל כְּשֶׁיִּתְרוֹקֵן מִשִּׁכְרוּתוֹ. שָׁתוּי אַל יִתְפַּלֵּל וְאִם הִתְפַּלֵּל תְּפִלָּתוֹ תְּפִלָּה. אֵי זֶה שִׁכּוֹר זֶה שֶׁאֵינוֹ יָכוֹל לְדַבֵּר לִפְנֵי הַמֶּלֶךְ. שָׁתוּי יָכוֹל לְדַבֵּר בִּפְנֵי הַמֶּלֶךְ וְאֵינוֹ מִשְׁתַּבֵּשׁ. אַף עַל פִּי כֵן הוֹאִיל וְשָׁתָה רְבִיעִית יַיִן לֹא יִתְפַּלֵּל עַד שֶׁיָּסִיר יֵינוֹ מֵעָלָיו",
      "וְכֵן אֵין עוֹמְדִין לְהִתְפַּלֵּל לֹא מִתּוֹךְ שְׂחוֹק וְלֹא מִתּוֹךְ קַלּוּת רֹאשׁ וְלֹא מִתּוֹךְ שִׂיחָה וְלֹא מִתּוֹךְ מְרִיבָה וְלֹא מִתּוֹךְ כַּעַס אֶלָּא מִתּוֹךְ דִּבְרֵי תּוֹרָה. וְלֹא מִתּוֹךְ דִּין וַהֲלָכָה אַף עַל פִּי שֶׁהֵם דִּבְרֵי תּוֹרָה כְּדֵי שֶׁלֹּא יְהֵא לִבּוֹ טָרוּד בַּהֲלָכָה. אֶלָּא מִתּוֹךְ דִּבְרֵי תּוֹרָה שֶׁאֵין בָּהּ עִיּוּן כְּגוֹן הֲלָכוֹת פְּסוּקוֹת:",
      "תְּפִלּוֹת הַפְּרָקִים כְּגוֹן תְּפִלַּת מוּסָף רֹאשׁ חֹדֶשׁ וּתְפִלַּת מוֹעֲדוֹת צָרִיךְ לְהַסְדִּיר תְּפִלָּתוֹ וְאַחַר כָּךְ עוֹמֵד וּמִתְפַּלֵּל כְּדֵי שֶׁלֹּא יִכָּשֵׁל בָּהּ. הָיָה מְהַלֵּךְ בִּמְקוֹם סַכָּנָה כְּגוֹן מְקוֹם גְּדוּדֵי חַיּוֹת וְלִסְטִים וְהִגִּיעַ זְמַן תְּפִלָּה מִתְפַּלֵּל בְּרָכָה אַחַת. וְזוֹ הִיא. צָרְכֵי עַמְּךָ יִשְׂרָאֵל מְרֻבִּים וְדַעְתָּם קְצָרָה. יְהִי רָצוֹן מִלְּפָנֶיךָ ה׳‎ אֱלֹהֵינוּ שֶׁתִּתֵּן לְכָל אֶחָד וְאֶחָד כְּדֵי פַּרְנָסָתוֹ וּלְכָל גְּוִיָּה וּגְוִיָּה דֵּי מַחְסוֹרָהּ וְהַטּוֹב בְּעֵינֶיךָ עֲשֵׂה בָּרוּךְ אַתָּה יְיָ׳‎ שׁוֹמֵעַ תְּפִלָּה. וּמִתְפַּלֵּל אוֹתָהּ בַּדֶּרֶךְ כְּשֶׁהוּא מְהַלֵּךְ, וְאִם יָכוֹל לַעֲמֹד עוֹמֵד. וּכְשֶׁהוּא מַגִּיעַ לְיִשּׁוּב וְתִתְקָרֵר דַּעְתּוֹ חוֹזֵר וּמִתְפַּלֵּל תְּפִלָּה כְּתַקָּנָתָהּ תְּשַׁע עֶשְׂרֵה בְּרָכוֹת:"
    ],
    [
      "שְׁמוֹנָה דְּבָרִים צָרִיךְ הַמִּתְפַּלֵּל לְהִזָּהֵר בָּהֶן וְלַעֲשׂוֹתָן. וְאִם הָיָה דָּחוּק אוֹ נֶאֱנַס אוֹ שֶׁעָבַר וְלֹא עָשָׂה אוֹתָן אֵין מְעַכְּבִין. וְאֵלּוּ הֵן. עֲמִידָה. וְנֹכַח הַמִּקְדָּשׁ. וְתִקּוּן הַגּוּף. וְתִקּוּן הַמַּלְבּוּשִׁים. וְתִקּוּן הַמָּקוֹם. וְהַשְׁוָיַת הַקּוֹל. וְהַכְּרִיעָה. וְהִשְׁתַּחֲוָיָה:",
      "עֲמִידָה כֵּיצַד. אֵין מִתְפַּלֵּל אֶלָּא מְעֻמָּד. הָיָה יוֹשֵׁב בִּסְפִינָה אוֹ בַּעֲגָלָה אִם יָכוֹל לַעֲמֹד יַעֲמֹד. וְאִם לָאו יֵשֵׁב בִּמְקוֹמוֹ וְיִתְפַּלֵּל. חוֹלֶה מִתְפַּלֵּל אֲפִלּוּ שׁוֹכֵב עַל צִדּוֹ וְהוּא שֶׁיָּכוֹל לְכַוֵּן אֶת דַּעְתּוֹ. וְכֵן הַצָּמֵא וְהָרָעֵב הֲרֵי הֵן בִּכְלַל חוֹלִים אִם יֵשׁ בּוֹ יְכלֶת לְכַוֵּן אֶת דַּעְתּוֹ יִתְפַּלֵּל וְאִם לָאו אַל יִתְפַּלֵּל עַד שֶׁיֹּאכַל וְיִשְׁתֶּה. הָיָה רוֹכֵב עַל הַבְּהֵמָה אַף עַל פִּי שֶׁיֵּשׁ לוֹ מִי שֶׁיֹּאחַז בְּהֶמְתּוֹ לֹא יֵרֵד אֶלָּא יֵשֵׁב בִּמְקוֹמוֹ וְיִתְפַּלֵּל כְּדֵי שֶׁתְּהֵא דַּעְתּוֹ מְיֻשֶּׁבֶת עָלָיו:",
      "נֹכַח הַמִּקְדָּשׁ כֵּיצַד. הָיָה עוֹמֵד בְּחוּצָה לָאָרֶץ מַחֲזִיר פָּנָיו נֹכַח אֶרֶץ יִשְׂרָאֵל וּמִתְפַּלֵּל. הָיָה עוֹמֵד בָּאָרֶץ מְכַוֵּן אֶת פָּנָיו כְּנֶגֶד יְרוּשָׁלַיִם. הָיָה עוֹמֵד בִּירוּשָׁלַיִם מְכַוֵּן פָּנָיו כְּנֶגֶד הַמִּקְדָּשׁ. הָיָה עוֹמֵד בַּמִּקְדָּשׁ מְכַוֵּן פָּנָיו כְּנֶגֶד בֵּית קֹדֶשׁ הַקָּדָשִׁים. סוּמָא וּמִי שֶׁלֹּא יָכוֹל לְכַוֵּן אֶת הָרוּחוֹת וְהַמְהַלֵּךְ בִּסְפִינָה יְכַוֵּן אֶת לִבּוֹ כְּנֶגֶד הַשְּׁכִינָה וְיִתְפַּלֵּל:",
      "תִּקּוּן הַגּוּף כֵּיצַד. כְּשֶׁהוּא עוֹמֵד בִּתְפִלָּה צָרִיךְ לְכַוֵּן אֶת רַגְלָיו זוֹ בְּצַד זוֹ וְנוֹתֵן עֵינָיו לְמַטָּה כְּאִלּוּ הוּא מַבִּיט לָאָרֶץ. וְיִהְיֶה לִבּוֹ פָּנוּי לְמַעְלָה כְּאִלּוּ הוּא עוֹמֵד בַּשָּׁמַיִם וּמַנִּיחַ יָדָיו עַל לִבּוֹ כְּפוּתִין הַיְמָנִית עַל הַשְּׂמָאלִית וְעוֹמֵד כְּעֶבֶד לִפְנֵי רַבּוֹ בְּאֵימָה בְּיִרְאָה וָפַחַד. וְלֹא יַנִּיחַ יָדָיו עַל חֲלָצָיו:",
      "תִּקּוּן הַמַּלְבּוּשִׁים כֵּיצַד. מְתַקֵּן מַלְבּוּשָׁיו תְּחִלָּה וּמְצַיֵּן עַצְמוֹ וּמְהַדֵּר שֶׁנֶּאֱמַר הִשְׁתַּחֲווּ לַה׳‎ בְּהַדְרַת קֹדֶשׁ. וְלֹא יַעֲמֹד בִּתְפִלָּה בַּאֲפוּנְדָתוֹ, וְלֹא בְּרֹאשׁ מְגֻלֶּה, וְלֹא בְּרַגְלַיִם מְגֻלּוֹת אִם דֶּרֶךְ אַנְשֵׁי הַמָּקוֹם שֶׁלֹּא יַעַמְדוּ בִּפְנֵי הַגְּדוֹלִים אֶלָּא בְּבָתֵּי הָרַגְלַיִם. וּבְכָל מָקוֹם לֹא יֶאֱחֹז תְּפִלִּין בְּיָדוֹ וְסֵפֶר תּוֹרָה בִּזְרוֹעוֹ וְיִתְפַּלֵּל מִפְּנֵי שֶׁלִּבּוֹ טָרוּד בָּהֶן. וְלֹא יֶאֱחֹז כֵּלִים וּמָעוֹת בְּיָדוֹ. אֲבָל מִתְפַּלֵּל הוּא וְלוּלָב בְּיָדוֹ בִּימוֹת הֶחָג מִפְּנֵי שֶׁהוּא מִצְוַת הַיּוֹם. הָיָה מַשּׂוֹי עַל רֹאשׁוֹ וְהִגִּיעַ זְמַן תְּפִלָּה אִם הָיָה פָּחוֹת מֵאַרְבָּעָה קַבִּין מַפְשִׁילוֹ לַאֲחוֹרָיו וּמִתְפַּלֵּל בּוֹ. הָיָה אַרְבָּעָה קַבִּין מַנִּיחוֹ עַל גַּבֵּי קַרְקַע וְאַחַר כָּךְ יִתְפַּלֵּל. דֶּרֶךְ כָּל הַחֲכָמִים וְתַלְמִידֵיהֶם שֶׁלֹּא יִתְפַּלְּלוּ אֶלָּא כְּשֶׁהֵן עֲטוּפִים:",
      "תִּקּוּן הַמָּקוֹם כֵּיצַד. יַעֲמֹד בְּמָקוֹם נָמוּךְ וְיַחֲזִיר פָּנָיו לַכֹּתֶל. וְצָרִיךְ לִפְתֹּחַ חַלּוֹנוֹת אוֹ פְּתָחִים כְּנֶגֶד יְרוּשָׁלַיִם כְּדֵי לְהִתְפַּלֵּל כְּנֶגְדָּן שֶׁנֶּאֱמַר <small>(דניאל ו יא)</small> ״וְכַוִּין פְּתִיחָן לֵהּ בְּעִלִּיתֵהּ״ וְגוֹ׳‎. וְקוֹבֵעַ מָקוֹם לִתְפִלָּתוֹ תָּמִיד. וְאֵין מִתְפַּלֵּל בְּחֻרְבָּה וְלֹא אֲחוֹרֵי בֵּית הַכְּנֶסֶת אֶלָּא אִם כֵּן הֶחֱזִיר פָּנָיו לְבֵית הַכְּנֶסֶת. וְאָסוּר לֵישֵׁב בְּצַד הָעוֹמֵד בִּתְפִלָּה אוֹ לַעֲבֹר לְפָנָיו עַד שֶׁיַּרְחִיק מִמֶּנּוּ אַרְבַּע אַמּוֹת:",
      "לֹא יַעֲמֹד בְּמָקוֹם גָּבוֹהַּ שְׁלֹשָׁה טְפָחִים אוֹ יוֹתֵר וְיִתְפַּלֵּל. וְלֹא עַל גַּבֵּי מִטָּה וְלֹא עַל גַּבֵּי סַפְסָל וְלֹא עַל גַּבֵּי כִּסֵּא. הָיָה בִּנְיָן גָּבוֹהַּ אִם יֵשׁ בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת שֶׁהוּא שִׁעוּר הַבַּיִת הֲרֵי הוּא כַּעֲלִיָּה וּמֻתָּר לְהִתְפַּלֵּל בּוֹ. וְכֵן אִם הָיָה מֻקָּף מְחִצּוֹת מִכָּל רוּחוֹתָיו אַף עַל פִּי שֶׁאֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת מֻתָּר לְהִתְפַּלֵּל בּוֹ מִפְּנֵי שֶׁאֵין גָּבְהוֹ נִכָּר שֶׁהֲרֵי חָלַק רְשׁוּת לְעַצְמוֹ:",
      "הָאֻמָּנִין שֶׁהָיוּ עוֹשִׂין מְלָאכָה בְּרֹאשׁ הָאִילָן אוֹ בְּרֹאשׁ הַנִּדְבָּךְ אוֹ בְּרֹאשׁ הַכֹּתֶל וְהִגִּיעַ זְמַן תְּפִלָּה יוֹרְדִין לְמַטָּה וּמִתְפַּלְּלִין וְחוֹזְרִין לִמְלַאכְתָּן. וְאִם הָיוּ בְּרֹאשׁ הַזַּיִת אוֹ בְּרֹאשׁ הַתְּאֵנָה מִתְפַּלְּלִין בִּמְקוֹמָן מִפְּנֵי שֶׁטָּרְחָן מְרֻבֶּה. וּמַה הֵן מִתְפַּלְּלִין. אִם הָיוּ עוֹשִׂין בִּסְעֻדָּתָן בִּלְבַד מִתְפַּלְּלִין שָׁלֹשׁ תְּפִלּוֹת שֶׁל תִּשְׁעָה עָשָׂר בְּרָכוֹת. הָיוּ עוֹשִׂין בִּשְׂכָרָן מִתְפַּלְּלִין הֲבִינֵנוּ. וּבֵין כָּךְ וּבֵין כָּךְ אֵין יוֹרְדִין לִפְנֵי הַתֵּבָה וְאֵין נוֹשְׂאִין אֶת כַּפֵּיהֶן:",
      "הַשְׁוָיַת הַקּוֹל כֵּיצַד. לֹא יַגְבִּיהַּ קוֹלוֹ בִּתְפִלָּתוֹ וְלֹא יִתְפַּלֵּל בְּלִבּוֹ אֶלָּא מְחַתֵּךְ הַדְּבָרִים בִּשְׂפָתָיו וּמַשְׁמִיעַ לְאָזְנָיו בְּלַחַשׁ. וְלֹא יַשְׁמִיעַ קוֹלוֹ אֶלָּא אִם כֵּן הָיָה חוֹלֶה אוֹ שֶׁאֵינוֹ יָכוֹל לְכַוֵּן אֶת לִבּוֹ עַד שֶׁיַּשְׁמִיעַ קוֹלוֹ, הֲרֵי זֶה מֻתָּר. וּבִלְבַד שֶׁלֹּא יְהֵא בְּצִבּוּר כְּדֵי שֶׁלֹּא תִּטָּרֵף דַּעְתָּן מִקּוֹלוֹ:",
      "כְּרִיעָה כֵּיצַד. הַמִּתְפַּלֵּל כּוֹרֵעַ חָמֵשׁ כְּרִיעוֹת בְּכָל תְּפִלָּה וּתְפִלָּה. בִּבְרָכָה רִאשׁוֹנָה בַּתְּחִלָּה וּבַסּוֹף. וּבְהוֹדָיָה בַּתְּחִלָּה וּבַסּוֹף. וּכְשֶׁגּוֹמֵר הַתְּפִלָּה כּוֹרֵעַ וּפוֹסֵעַ שָׁלֹשׁ פְּסִיעוֹת לַאֲחוֹרָיו. וּכְשֶׁהוּא כּוֹרֵעַ נוֹתֵן שָׁלוֹם מִשְּׂמֹאל עַצְמוֹ וְאַחַר כָּךְ מִימִין עַצְמוֹ וְאַחַר כָּךְ מַגְבִּיהַּ רֹאשׁוֹ מִן הַכְּרִיעָה. וּכְשֶׁהוּא כּוֹרֵעַ בְּאַרְבַּע הַכְּרִיעוֹת כּוֹרֵעַ בְּבָרוּךְ וּכְשֶׁהוּא זוֹקֵף זוֹקֵף בַּשֵּׁם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּהֶדְיוֹט. אֲבָל כֹּהֵן גָּדוֹל כּוֹרֵעַ בִּתְחִלַּת כָּל בְּרָכָה וּבְסוֹף כָּל בְּרָכָה. וְהַמֶּלֶךְ כֵּיוָן שֶׁשָּׁחָה בָּרִאשׁוֹנָה אֵינוֹ מַגְבִּיהַּ רֹאשׁוֹ עַד שֶׁגּוֹמֵר כָּל תְּפִלָּתוֹ:",
      "וְלָמָּה נוֹתֵן שָׁלוֹם לִשְׂמֹאלוֹ תְּחִלָּה. מִפְּנֵי שֶׁשְּׂמֹאלוֹ הוּא יָמִין שֶׁכְּנֶגֶד פָּנָיו. כְּלוֹמַר כְּשֶׁהוּא עוֹמֵד לִפְנֵי הַמֶּלֶךְ נוֹתֵן שָׁלוֹם לִימִין הַמֶּלֶךְ וְאַחַר כָּךְ לִשְׂמֹאל הַמֶּלֶךְ. וְקָבְעוּ שֶׁיִּפָּטֵר מִן הַתְּפִלָּה כְּמוֹ שֶׁנִּפְטָרִין מִלִּפְנֵי הַמֶּלֶךְ:",
      "כָּל הַכְּרִיעוֹת הָאֵלּוּ צָרִיךְ שֶׁיִּכְרַע בָּהֶן עַד שֶׁיִּתְפַּקְּקוּ כָּל חֻלְיוֹת שֶׁבַּשִּׁדְרָה וְיַעֲשֶׂה עַצְמוֹ כְּקֶשֶׁת. וְאִם שָׁחָה מְעַט וְצִעֵר עַצְמוֹ וְנִרְאֶה כְּכוֹרֵעַ בְּכָל כֹּחוֹ אֵינוֹ חוֹשֵׁשׁ:",
      "הִשְׁתַּחֲוָיָה כֵּיצַד. אַחַר שֶׁמַּגְבִּיהַּ רֹאשׁוֹ מִכְּרִיעָה חֲמִישִׁית יֵשֵׁב לָאָרֶץ וְנוֹפֵל עַל פָּנָיו אַרְצָה וּמִתְחַנֵּן בְּכָל הַתַּחֲנוּנִים שֶׁיִּרְצֶה. כְּרִיעָה הָאֲמוּרָה בְּכָל מָקוֹם עַל בִּרְכַּיִם. קִידָה עַל אַפַּיִם. הִשְׁתַּחֲוָיָה זֶה פִּשּׁוּט יָדַיִם וְרַגְלַיִם עַד שֶׁנִּמְצָא מֻטָּל עַל פָּנָיו אַרְצָה:",
      "כְּשֶׁהוּא עוֹשֶׂה נְפִילַת פָּנִים אַחַר תְּפִלָּה יֵשׁ מִי שֶׁהוּא עוֹשֶׂה קִידָה וְיֵשׁ מִי שֶׁהוּא עוֹשֶׂה הִשְׁתַּחֲוָיָה. וְאָסוּר לַעֲשׂוֹת הִשְׁתַּחֲוָיָה עַל הָאֲבָנִים אֶלָּא בַּמִּקְדָּשׁ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת עֲבוֹדַת כּוֹכָבִים. וְאֵין אָדָם חָשׁוּב רַשַּׁאי לִפּל עַל פָּנָיו אֶלָּא אִם כֵּן הוּא יוֹדֵעַ בְּעַצְמוֹ שֶׁהוּא צַדִּיק כִּיהוֹשֻׁעַ. אֲבָל מַטֶּה פָּנָיו מְעַט וְאֵינוֹ כּוֹבֵשׁ אוֹתָן בַּקַּרְקַע. וּמֻתָּר לְאָדָם לְהִתְפַּלֵּל בְּמָקוֹם זֶה וְלִפּל עַל פָּנָיו בְּמָקוֹם אַחֵר:",
      "מִנְהָג פָּשׁוּט בְּכָל יִשְׂרָאֵל שֶׁאֵין נְפִילַת אַפַּיִם בְּשַׁבָּתוֹת וּבְמוֹעֲדִים וְלֹא בְּרֹאשׁ הַשָּׁנָה וְלֹא בְּרָאשֵׁי חֳדָשִׁים וּבַחֲנֻכָּה וּבְפוּרִים וְלֹא בְּמִנְחָה שֶׁל עַרְבֵי שַׁבָּתוֹת וְיָמִים טוֹבִים וְלֹא בְּעַרְבִית שֶׁבְּכָל יוֹם. וְיֵשׁ יְחִידִים שֶׁנּוֹפְלִים עַל פְּנֵיהֶם בְּעַרְבִית. וּבְיוֹם הַכִּפּוּרִים בִּלְבַד נוֹפְלִים עַל פְּנֵיהֶם בְּכָל תְּפִלָּה וּתְפִלָּה מִפְּנֵי שֶׁהוּא יוֹם תְּחִנָּה וּבַקָּשָׁה וְתַעֲנִית:"
    ],
    [
      "אָסוּר לוֹ לְאָדָם לַעֲבֹר אֲחוֹרֵי בֵּית הַכְּנֶסֶת בְּשָׁעָה שֶׁהַצִּבּוּר מִתְפַּלְּלִין אֶלָּא אִם כֵּן הָיָה נוֹשֵׂא מַשּׂאוֹי, אוֹ שֶׁהָיָה לְבֵית הַכְּנֶסֶת שְׁנֵי פְּתָחִים בִּשְׁנֵי רוּחוֹת, שֶׁהָרוֹאֶה אוֹמֵר שֶׁמָּא יֵלֵךְ וְיִכָּנֵס מִפֶּתַח הָאַחֵר. וְכֵן אִם הָיָה בָּעִיר שְׁנֵי בָּתֵּי כְּנֵסִיּוֹת יֹאמַר הָרוֹאֶה שֶׁמָּא יֵלֵךְ לְבֵית הַכְּנֶסֶת הָרָגִיל בּוֹ. וְאִם יֵשׁ לוֹ תְּפִלִּין בְּרֹאשׁוֹ מֻתָּר לוֹ לַעֲבֹר וְאַף עַל פִּי שֶׁאֵין שָׁם אֶחָד מִכָּל אֵלּוּ שֶׁהַתְּפִלִּין מוֹכִיחִין עָלָיו שֶׁהוּא רוֹדֵף אַחַר מִצְוֹת וְאֵינוֹ מִמְּבַטְּלֵי תְּפִלָּה:",
      "הַמִּתְפַּלֵּל עִם הַצִּבּוּר לֹא יַאֲרִיךְ אֶת תְּפִלָּתוֹ יוֹתֵר מִדַּאי אֲבָל בֵּינוֹ לְבֵין עַצְמוֹ הָרְשׁוּת בְּיָדוֹ. וְאִם בָּא לוֹמַר אַחַר תְּפִלָּתוֹ אֲפִלּוּ כְּסֵדֶר וִדּוּי יוֹם הַכִּפּוּרִים אוֹמֵר. וְכֵן אִם רָצָה לְהוֹסִיף בְּכָל בְּרָכָה וּבְרָכָה מִן הָאֶמְצָעִיּוֹת מֵעֵין הַבְּרָכָה מוֹסִיף:",
      "כֵּיצַד. הָיָה לוֹ חוֹלֶה מְבַקֵּשׁ עָלָיו רַחֲמִים בְּבִרְכַּת חוֹלִים כְּפִי צַחוּת לְשׁוֹנוֹ. הָיָה צָרִיךְ לְפַרְנָסָה מוֹסִיף תְּחִנָּה וּבַקָּשָׁה בְּבִרְכַּת הַשָּׁנִים. וְעַל דֶּרֶךְ זֶה בְּכָל אַחַת מֵהֶן. וְאִם רָצָה לִשְׁאֹל כָּל צְרָכָיו בְּשׁוֹמֵעַ תְּפִלָּה שׁוֹאֵל. אֲבָל לֹא יִשְׁאַל לֹא בְּשָׁלֹשׁ רִאשׁוֹנוֹת וְלֹא בְּשָׁלֹשׁ אַחֲרוֹנוֹת:",
      "אָסוּר לוֹ לְאָדָם שֶׁיִּטְעֹם כְּלוּם אוֹ שֶׁיַּעֲשֶׂה מְלָאכָה מֵאַחַר שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר עַד שֶׁיִּתְפַּלֵּל תְּפִלַּת שַׁחֲרִית. וְכֵן לֹא יַשְׁכִּים לְפֶתַח חֲבֵרוֹ לִשְׁאל בִּשְׁלוֹמוֹ קֹדֶם שֶׁיִּתְפַּלֵּל תְּפִלַּת שַׁחֲרִית. וְלֹא יֵצֵא בַּדֶּרֶךְ קֹדֶם שֶׁיִּתְפַּלֵּל. אֲבָל טוֹעֵם וְעוֹשֶׂה מְלָאכָה קֹדֶם שֶׁיִּתְפַּלֵּל מוּסָף וְקֹדֶם מִנְחָה. אֲבָל אֵינוֹ סוֹעֵד סָמוּךְ לַמִּנְחָה:",
      "כֵּיוָן שֶׁהִגִּיעַ זְמַן מִנְחָה גְּדוֹלָה לֹא יִכָּנֵס לַמֶּרְחָץ אֲפִלּוּ לְהַזִּיעַ עַד שֶׁיִּתְפַּלֵּל שֶׁמָּא יִתְעַלֵּף וְיִבָּטֵל מִן הַתְּפִלָּה. וְלֹא לֶאֱכל אֲפִלּוּ אֲכִילַת עַרְאַי שֶׁמָּא יִמָּשֵׁךְ בַּאֲכִילָה. וְלֹא לָדוּן אֲפִלּוּ בִּגְמַר דִּין שֶׁמָּא יִסָּתֵר הַדִּין וְיִמָּשֵׁךְ וְיִבָּטֵל מִן הַתְּפִלָּה. וְכֵן לֹא יֵשֵׁב לִפְנֵי הַסַּפָּר לִסַפֵּר אֲפִלּוּ תִּסְפֹּרֶת הֶדְיוֹט עַד שֶׁיִּתְפַּלֵּל שֶׁמָּא יִשָּׁבֵר הַזּוּג. וְלֹא יִכָּנֵס לְבֻרְסְקִי סָמוּךְ לַמִּנְחָה עַד שֶׁיִּתְפַּלֵּל שֶׁמָּא יִרְאֶה הֶפְסֵד בִּמְלַאכְתּוֹ וְיִתְעַסֵּק בָּהּ וְיִתְעַכֵּב מִן הַתְּפִלָּה. וְאִם הִתְחִיל בְּאַחַת מֵאֵלּוּ לֹא יַפְסִיק אֶלָּא גּוֹמֵר וְאַחַר כָּךְ מִתְפַּלֵּל תְּפִלַּת מִנְחָה:",
      "מֵאֵימָתַי הַתְחָלַת תִּסְפֹּרֶת מִשֶּׁיַּנִּיחַ מַעֲפֹרֶת שֶׁל סַפָּרִין עַל בִּרְכָּיו. וּמֵאֵימָתַי הַתְחָלַת מֶרְחָץ מִשֶּׁיִּפְשֹׁט הַבֶּגֶד הַסָּמוּךְ לִבְשָׂרוֹ. וּמֵאֵימָתַי הַתְחָלַת הַבֻּרְסְקִי מִשֶּׁיִּקְשֹׁר בֶּגֶד בֵּין כְּתֵפָיו כְּמוֹ שֶׁהָאֻמָּנִין עוֹשִׂין. וּמֵאֵימָתַי הַתְחָלַת אֲכִילָה, לִבְנֵי אֶרֶץ יִשְׂרָאֵל מִשֶּׁיִּטּל יָדָיו וְלִבְנֵי בָּבֶל מִשֶּׁיַּתִּיר חֲגוֹרוֹ. וּמֵאֵימָתַי הַתְחָלַת הַדִּין מִשֶּׁיִּתְעַטְּפוּ הַדַּיָּנִים וְיֵשְׁבוּ. וְאִם הָיוּ יוֹשְׁבִין מִשֶּׁיַּתְחִילוּ בַּעֲלֵי דִּינִין לִטְעֹן:",
      "אַף עַל פִּי שֶׁתְּפִלַּת עַרְבִית רְשׁוּת לֹא יָבוֹא אָדָם מִמְּלַאכְתּוֹ וְיֹאמַר אֹכַל מְעַט וְאִישַׁן קִמְעָא וְאַחַר כָּךְ אֶתְפַּלֵּל, שֶׁמָּא תֶּאֱנֹס אוֹתוֹ שֵׁנָה וְנִמְצָא יָשֵׁן כָּל הַלַּיְלָה, אֶלָּא מִתְפַּלֵּל עַרְבִית וְאַחַר כָּךְ אוֹכֵל וְשׁוֹתֶה אוֹ יָשֵׁן. וּמֻתָּר לְהִסְתַּפֵּר וְלִכָּנֵס לַמֶּרְחָץ סָמוּךְ לְשַׁחֲרִית מִפְּנֵי שֶׁלֹּא גָּזְרוּ אֶלָּא סָמוּךְ לַמִּנְחָה שֶׁהוּא דָּבָר הַמָּצוּי שֶׁרֹב הָעָם נִכְנָסִין שָׁם בַּיּוֹם. אֲבָל בַּשַּׁחַר דָּבָר שֶׁאֵינוֹ מָצוּי לֹא גָּזְרוּ בּוֹ:",
      "מִי שֶׁהָיָה עוֹסֵק בְּתַלְמוּד תּוֹרָה וְהִגִּיעַ זְמַן הַתְּפִלָּה פּוֹסֵק וּמִתְפַּלֵּל. וְאִם הָיְתָה תּוֹרָתוֹ אֻמָּנוּתוֹ וְאֵינוֹ עוֹשֶׂה מְלָאכָה כְּלָל וְהָיָה עוֹסֵק בַּתּוֹרָה בִּשְׁעַת תְּפִלָּתוֹ אֵינוֹ פּוֹסֵק, שֶׁמִּצְוַת תַּלְמוּד תּוֹרָה גְּדוֹלָה מִמִּצְוַת תְּפִלָּה. וְכָל הָעוֹסֵק בְּצָרְכֵי רַבִּים כְּעוֹסֵק בְּדִבְרֵי תּוֹרָה:",
      "אֵין הַמִּתְפַּלֵּל מַפְסִיק תְּפִלָּתוֹ אֶלָּא מִפְּנֵי סַכָּנַת נְפָשׁוֹת בִּלְבַד. וַאֲפִלּוּ מֶלֶךְ יִשְׂרָאֵל שׁוֹאֵל בִּשְׁלוֹמוֹ לֹא יְשִׁיבֶנּוּ. אֲבָל פּוֹסֵק הוּא לְמֶלֶךְ עוֹבֵד כּוֹכָבִים שֶׁמָּא יַהַרְגֶּנּוּ. הָיָה עוֹמֵד בַּתְּפִלָּה וְרָאָה מֶלֶךְ עוֹבְדֵי כּוֹכָבִים אוֹ אַנָּס בָּא כְּנֶגְדּוֹ יְקַצֵּר וְאִם אֵינוֹ יָכוֹל יַפְסִיק. וְכֵן אִם רָאָה נְחָשִׁים וְעַקְרַבִּים בָּאִים כְּנֶגְדּוֹ אִם הִגִּיעוּ אֵלָיו וְהָיָה דַּרְכָּן בְּאוֹתָן הַמְּקוֹמוֹת שֶׁהֵן מְמִיתִין פּוֹסֵק וּבוֹרֵחַ. וְאִם לֹא הָיָה דַּרְכָּן לְהָמִית אֵינוֹ פּוֹסֵק:",
      "נָשִׁים וַעֲבָדִים וּקְטַנִּים חַיָּבִים בִּתְפִלָּה. וְכָל אִישׁ שֶׁפָּטוּר מִקְּרִיאַת שְׁמַע פָּטוּר מִן הַתְּפִלָּה. וְכָל הַמְלַוִּין אֶת הַמֵּת אַף עַל פִּי שֶׁאֵין לַמִּטָּה צֹרֶךְ בָּהֶן פְּטוּרִין מִן הַתְּפִלָּה:"
    ],
    [
      "כְּשֶׁתִּקְּנּוּ חֲכָמִים דִּבְרֵי תְּפִלּוֹת אֵלּוּ תִּקְּנוּ בְּרָכוֹת אֲחֵרוֹת לְבָרֵךְ אוֹתָן בְּכָל יוֹם, אֵלּוּ הֵן. כְּשֶׁיִּכָּנֵס אָדָם לְמִטָּתוֹ לִישֹׁן בַּלַּיְלָה מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמַּפִּיל חֶבְלֵי שֵׁנָה עַל עֵינַי וְהַמַּשְׁקִיעַ שֵׁינַת תַּרְדֵּמָה וְהַמֵּאִיר לְאִישׁוֹן בַּת עַיִן. יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁתַּצִּילֵנִי מִיֵּצֶר רַע וּמִפֶּגַע רַע וְאַל יְבַהֲלוּנִי חֲלוֹמוֹת רָעִים וְלֹא הִרְהוּרִים רָעִים וּתְהֵא מִטָּתִי שְׁלֵמָה לְפָנֶיךָ וְתַעֲמִידֵנִי מִמֶּנָּה לְחַיִּים וּלְשָׁלוֹם וְהָאִירָה עֵינַי פֶּן אִישַׁן הַמָּוֶת. בָּרוּךְ אַתָּה יְיָ׳‎ הַמֵּאִיר לָעוֹלָם כֻּלּוֹ בִּכְבוֹדוֹ:",
      "וְקוֹרֵא פָּרָשָׁה רִאשׁוֹנָה מִקְּרִיאַת שְׁמַע וְיָשֵׁן. וַאֲפִלּוּ אִשְׁתּוֹ יְשֵׁנָה עִמּוֹ (קוֹרֵא פָּסוּק רִאשׁוֹן אוֹ פְּסוּקֵי רַחֲמִים וְאַחַר כָּךְ יִישַׁן). וְאִם אֲנָסַתּוּ שֵׁנָה קוֹרֵא אֲפִלּוּ פָּסוּק רִאשׁוֹן אוֹ פְּסוּקֵי רַחֲמִים וְאַחַר כָּךְ יִישַׁן:",
      "בְּשָׁעָה שֶׁיִּיקַץ בְּסוֹף שְׁנָתוֹ מְבָרֵךְ וְהוּא עַל מִטָּתוֹ כָּךְ. אֱלֹהַי נְשָׁמָה שֶׁנָּתַתָּ בִּי טְהוֹרָה אַתָּה בְּרָאתָהּ וְאַתָּה יְצַרְתָּהּ וְאַתָּה נְפַחְתָּהּ בִּי וְאַתָּה מְשַׁמְּרָהּ בְּקִרְבִּי וְאַתָּה עָתִיד לִטְּלָהּ מִמֶּנִּי וְאַתָּה עָתִיד לְהַחֲזִירָהּ בִּי לֶעָתִיד לָבוֹא. כָּל זְמַן שֶׁהַנְּשָׁמָה תְּלוּיָה בְּקִרְבִּי מוֹדֶה אֲנִי לְפָנֶיךָ יְיָ׳‎ אֱלֹהַי רִבּוֹן כָּל הַמַּעֲשִׂים בָּרוּךְ אַתָּה יְיָ׳‎ הַמַּחֲזִיר נְשָׁמוֹת לִפְגָרִים מֵתִים:",
      "כְּשֶׁשּׁוֹמֵעַ קוֹל הַתַּרְנְגוֹלִים מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַנּוֹתֵן לַשֶּׂכְוִי בִינָה לְהַבְחִין בֵּין יוֹם וּבֵין לָיְלָה. כְּשֶׁלּוֹבֵשׁ בְּגָדָיו מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם מַלְבִּישׁ עֲרוּמִים. כְּשֶׁמַּנִּיחַ סְדִינוֹ עַל רֹאשׁוֹ מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם עוֹטֵר יִשְׂרָאֵל בְּתִפְאָרָה. כְּשֶׁמַּעֲבִיר יָדָיו עַל עֵינָיו מְבָרֵךְ פּוֹקֵחַ עִוְרִים. כְּשֶׁיֵּשֵׁב עַל מִטָּתוֹ מְבָרֵךְ מַתִּיר אֲסוּרִים. כְּשֶׁמּוֹרִיד רַגְלָיו מִן הַמִּטָּה וּמַנִּיחָם עַל גַּבֵּי קַרְקַע מְבָרֵךְ רוֹקַע הָאָרֶץ עַל הַמָּיִם. כְּשֶׁעוֹמֵד מְבָרֵךְ זוֹקֵף כְּפוּפִים. כְּשֶׁנּוֹטֵל יָדָיו מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל נְטִילַת יָדָיִם. כְּשֶׁרוֹחֵץ פָּנָיו מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמַּעֲבִיר חֶבְלֵי שֵׁנָה מֵעֵינָי וּתְנוּמָה מֵעַפְעַפָּי, יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי שֶׁתַּרְגִּילֵנִי לִדְבַר מִצְוָה וְאַל תַּרְגִּילֵנִי לִדְבַר עֲבֵרָה וְעָוֹן וְתַשְׁלֵט בִּי יֵצֶר טוֹב וְאַל יִשְׁלֹט בִּי יֵצֶר רָע וּתְחַזְּקֵנִי בְּמִצְוֹתֶיךָ וְתֵן חֶלְקִי בְּתוֹרָתֶךָ וְתִתְּנֵנִי לְחֵן וּלְחֶסֶד וּלְרַחֲמִים בְּעֵינֶיךָ וּבְעֵינֵי כָל רוֹאַי וְתִגְמְלֵנִי חֲסָדִים טוֹבִים, בָּרוּךְ אַתָּה יְיָ׳‎ גּוֹמֵל חֲסָדִים טוֹבִים:",
      "וְכָל זְמַן שֶׁיִּכָּנֵס לְבֵית הַכִּסֵּא אוֹמֵר קֹדֶם שֶׁיִּכָּנֵס הִתְכַּבְּדוּ מְכֻבָּדִים קְדוֹשִׁים מְשָׁרְתֵי עֶלְיוֹן עִזְרוּנִי עִזְרוּנִי שִׁמְרוּנִי שִׁמְרוּנִי הַמְתִּינוּ לִי עַד שֶׁאֶכָּנֵס וְאֵצֵא שֶׁזֶּה דַּרְכָּן שֶׁל בְּנֵי אָדָם. וְאַחַר שֶׁיָּצָא מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר יָצַר אֶת הָאָדָם בְּחָכְמָה וּבָרָא בוֹ נְקָבִים נְקָבִים חֲלוּלִים חֲלוּלִים גָּלוּי וְיָדוּעַ לִפְנֵי כִסֵּא כְבוֹדֶךָ שֶׁאִם יִסָּתֵם אֶחָד מֵהֶם אוֹ אִם יִפָּתֵחַ אֶחָד מֵהֶם אִי אֶפְשָׁר לְהִתְקַיֵּם אֲפִלּוּ שָׁעָה אַחַת בָּרוּךְ אַתָּה יְיָ׳‎ רוֹפֵא כָל בָּשָׂר וּמַפְלִיא לַעֲשׂוֹת:",
      "כְּשְׁחוֹגֵר חֲגוֹרוֹ מְבָרֵךְ אוֹזֵר יִשְׂרָאֵל בִּגְבוּרָה. כְּשֶׁלּוֹבֵשׁ נְעָלָיו מְבָרֵךְ שֶׁעָשִׂיתָ לִי כָּל צָרְכִּי. כְּשֶׁמְּהַלֵּךְ לָצֵאת לַדֶּרֶךְ מְבָרֵךְ הַמֵּכִין מִצְעֲדֵי גָבֶר. וּמְבָרֵךְ אָדָם בְּכָל יוֹם בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁלֹּא עָשַׂנִי גּוֹי. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁלֹּא עָשַׂנִי אִשָּׁה. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁלֹּא עָשַׂנִי עָבֶד:",
      "שְׁמוֹנֶה עֶשְׂרֵה בְּרָכוֹת אֵלּוּ אֵין לָהֶם סֵדֶר אֶלָּא מְבָרֵךְ כָּל אַחַת מֵהֶן עַל דָּבָר שֶׁהַבְּרָכָה בִּשְׁבִילוֹ בִּשְׁעָתוֹ. כֵּיצַד. הֲרֵי שֶׁחָגַר חֲגוֹרוֹ וְהוּא עַל מִטָּתוֹ מְבָרֵךְ אוֹזֵר יִשְׂרָאֵל בִּגְבוּרָה. שָׁמַע קוֹל הַתַּרְנְגוֹל מְבָרֵךְ הַנּוֹתֵן לַשֶּׂכְוִי בִינָה. וְכָל בְּרָכָה מֵהֶן שֶׁלֹּא נִתְחַיֵּב בָּהּ אֵינוֹ מְבָרֵךְ אוֹתָהּ:",
      "כֵּיצַד. לָן בִּכְסוּתוֹ אֵינוֹ מְבָרֵךְ כְּשֶׁעוֹמֵד מַלְבִּישׁ עֲרוּמִים. הָלַךְ יָחֵף אֵינוֹ מְבָרֵךְ שֶׁעָשִׂיתָ לִי כָּל צָרְכִּי. בְּיוֹם הַכִּפּוּרִים וּבְתִשְׁעָה בְּאָב שֶׁאֵין שָׁם רְחִיצָה אֵינוֹ מְבָרֵךְ עַל נְטִילַת יָדַיִם וְלֹא הַמַּעֲבִיר חֶבְלֵי שֵׁנָה. אִם לֹא נִכְנַס לְבֵית הַכִּסֵּא אֵינוֹ מְבָרֵךְ אֲשֶׁר יָצַר אֶת הָאָדָם. וְכֵן שְׁאָר בְּרָכוֹת אֵלּוּ:",
      "נָהֲגוּ הָעָם בְּרֹב עָרֵינוּ לְבָרֵךְ בְּרָכוֹת אֵלּוּ זוֹ אַחַר זוֹ בְּבֵית הַכְּנֶסֶת בֵּין נִתְחַיְּבוּ בָּהֶן בֵּין לֹא נִתְחַיְּבוּ בָּהֶן. וְטָעוּת הוּא וְאֵין רָאוּי לַעֲשׂוֹת כֵּן וְלֹא יְבָרֵךְ בְּרָכָה אֶלָּא אִם כֵּן נִתְחַיֵּב בָּהּ:",
      "הַמַּשְׁכִּים לִקְרֹא בַּתּוֹרָה קֹדֶם שֶׁיִּקְרָא קְרִיאַת שְׁמַע בֵּין קָרָא בַּתּוֹרָה שֶׁבִּכְתָב בֵּין קָרָא בַּתּוֹרָה שֶׁבְּעַל פֶּה נוֹטֵל יָדָיו תְּחִלָּה וּמְבָרֵךְ שָׁלֹשׁ בְּרָכוֹת וְאַחַר כָּךְ קוֹרֵא. וְאֵלּוּ הֵן. אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל דִּבְרֵי תוֹרָה. וְהַעֲרֶב נָא יְיָ׳‎ אֱלֹהֵינוּ אֶת דִּבְרֵי תוֹרָתְךָ בְּפִינוּ וּבְפִיפִּיּוֹת עַמְּךָ כָּל בֵּית יִשְׂרָאֵל וְנִהְיֶה אֲנַחְנוּ וְצֶאֱצָאֵינוּ וְצֶאֱצָאֵי עַמְּךָ יוֹדְעֵי שְׁמֶךָ וְעוֹסְקֵי תוֹרָתֶךָ לִשְׁמָהּ בָּרוּךְ אַתָּה יְיָ׳‎ הַמְלַמֵּד תּוֹרָה לְעַמּוֹ יִשְׂרָאֵל. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּחַר בָּנוּ מִכָּל הָעַמִּים וְנָתַן לָנוּ אֶת תּוֹרָתוֹ בָּרוּךְ אַתָּה יְיָ׳‎ נוֹתֵן הַתּוֹרָה:",
      "בְּכָל יוֹם חַיָּב אָדָם לְבָרֵךְ שָׁלֹשׁ בְּרָכוֹת אֵלּוּ וְאַחַר כָּךְ קוֹרֵא מְעַט מִדִּבְרֵי תּוֹרָה. וְנָהֲגוּ הָעָם לִקְרֹא <small>(במדבר ו כב כז)</small> ״בִּרְכַּת כֹּהֲנִים״. וְיֵשׁ מְקוֹמוֹת שֶׁקּוֹרִין <small>(במדבר כח ב)</small> ״צַו אֶת בְּנֵי יִשְׂרָאֵל״. וְיֵשׁ מְקוֹמוֹת שֶׁקּוֹרִין שְׁתֵּיהֶן. וְקוֹרִין פְּרָקִים אוֹ הֲלָכוֹת מִן הַמִּשְׁנָה וּמִן הַבְּרַיְתּוֹת:",
      "וְשִׁבְּחוּ חֲכָמִים לְמִי שֶׁקּוֹרֵא זְמִירוֹת מִסֵּפֶר תְּהִלִּים בְּכָל יוֹם וָיוֹם מִ<small>(תהילים קמה א)</small> ״תְּהִלָּה לְדָוִד״ עַד סוֹף הַסֵּפֶר. וּכְבָר נָהֲגוּ לִקְרוֹת פְּסוּקִים לִפְנֵיהֶם וּלְאַחֲרֵיהֶם וְתִקְּנוּ בְּרָכָה לִפְנֵי הַזְּמִירוֹת וְהִיא בָּרוּךְ שֶׁאָמַר וּבְרָכָה לְאַחֲרֵיהֶם וְהִיא יִשְׁתַּבַּח. וְאַחַר כָּךְ מְבָרֵךְ עַל קְרִיאַת שְׁמַע וְקוֹרֵא קְרִיאַת שְׁמַע:",
      "יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ בָּהֶן לִקְרוֹת בְּכָל יוֹם אַחַר שֶׁמְּבָרְכִין יִשְׁתַּבַּח <small>(שמות טו א יט)</small> ״שִׁירַת הַיָּם״ וְאַחַר כָּךְ מְבָרְכִין עַל שְׁמַע. וְיֵשׁ מְקוֹמוֹת שֶׁקּוֹרִין <small>(דברים לב א מג)</small> ״שִׁירַת הַאֲזִינוּ״. וְיֵשׁ יְחִידִים שֶׁקּוֹרִין שְׁתֵּי הַשִּׁירוֹת הַכּל לְפִי הַמִּנְהָג:",
      "חַיָּב אָדָם לְבָרֵךְ מֵאָה בְּרָכוֹת בֵּין הַיּוֹם וְהַלַּיְלָה. וּמַה הֵן מֵאָה בְּרָכוֹת אֵלּוּ. כ״ג בְּרָכוֹת שֶׁמָּנִינוּ בְּפֶרֶק זֶה. וְשֶׁבַע בְּרָכוֹת שֶׁל קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית וְעַרְבִית לְפָנֶיהָ וּלְאַחֲרֶיהָ. וּכְשֶׁמִּתְעַטֵּף בַּצִּיצִית מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהִתְעַטֵּף בְּצִיצִית. וּכְשֶׁלּוֹבֵשׁ תְּפִלִּין מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהָנִיחַ תְּפִלִּין. וְשָׁלֹשׁ תְּפִלּוֹת שֶׁבְּכָל תְּפִלָּה מֵהֶן שְׁמוֹנֶה עֶשְׂרֵה בְּרָכוֹת הֲרֵי שְׁמוֹנִים וְשֵׁשׁ בְּרָכוֹת. וּכְשֶׁהוּא אוֹכֵל שְׁתֵּי סְעֻדּוֹת שֶׁל יוֹם וְהַלַּיְלָה מְבָרֵךְ אַרְבַּע עֶשְׂרֵה בְּרָכוֹת. שֶׁבַע בְּכָל סְעֻדָּה. אַחַת כְּשֶׁיִּטּל יָדָיו תְּחִלָּה. וְעַל הַמָּזוֹן אַחַת בַּתְּחִלָּה וְשָׁלֹשׁ בַּסּוֹף וְעַל הַיַּיִן לְפָנָיו וּלְאַחֲרָיו הֲרֵי שֶׁבַע בְּרָכוֹת הֲרֵי מֵאָה בְּרָכוֹת בֵּין הַכּל:",
      "בַּזְּמַן הַזֶּה שֶׁתִּקְּנוּ בִּרְכַּת הָאֶפִּיקוֹרוֹסִין בַּתְּפִלָּה וְהוֹסִיפוּ הַטּוֹב וְהַמֵּיטִיב בְּבִרְכַּת הַמָּזוֹן נִמְצְאוּ חָמֵשׁ בְּרָכוֹת יְתֵרוֹת. בְּשַׁבָּתוֹת וְיָמִים טוֹבִים שֶׁהַתְּפִלָּה שֶׁבַע בְּרָכוֹת, וְכֵן אִם לֹא נִתְחַיֵּב בִּשְׁאָר הַיָּמִים בְּכָל הַבְּרָכוֹת הָאֵלּוּ כְּגוֹן שֶׁלֹּא יָשַׁן כָּל הַלַּיְלָה וְלֹא הִתִּיר חֲגוֹרוֹ וְלֹא נִכְנַס לְבֵית הַכִּסֵּא וְכַיּוֹצֵא בְּאֵלּוּ, צָרִיךְ לְהַשְׁלִים מֵאָה בְּרָכוֹת מִן הַפֵּרוֹת:",
      "כֵּיצַד. אוֹכֵל מְעַט יָרָק וּמְבָרֵךְ לְפָנָיו וּלְאַחֲרָיו וְחוֹזֵר וְאוֹכֵל מְעַט מִפְּרִי זֶה וּמְבָרֵךְ לְפָנָיו וּלְאַחֲרָיו וּמוֹנֶה כָּל הַבְּרָכוֹת עַד שֶׁמַּשְׁלִים מֵאָה בְּכָל יוֹם:",
      "סֵדֶר תְּפִלּוֹת כָּךְ הוּא. בַּשַּׁחַר מַשְׁכִּים אָדָם וּמְבָרֵךְ בְּרָכוֹת אֵלּוּ. וְקוֹרֵא הַזְּמִירוֹת וּמְבָרֵךְ לִפְנֵיהֶם וּלְאַחֲרֵיהֶם. וְקוֹרֵא אַחַר כָּךְ שְׁמַע וּמְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ. וּמְדַלֵּג קְדֻשָּׁה מִן הַבְּרָכָה רִאשׁוֹנָה שֶׁלְּפָנֶיהָ שֶׁאֵין הַיָּחִיד אוֹמֵר קְדֻשָּׁה. וּכְשֶׁהוּא חוֹתֵם גָּאַל יִשְׂרָאֵל מִיָּד יַעֲמֹד כְּדֵי שֶׁיִּסְמֹךְ גְּאֻלָּה לִתְפִלָּה וּמִתְפַּלֵּל מְעֻמָּד כְּמוֹ שֶׁאָמַרְנוּ. וּכְשֶׁיַּשְׁלִים יֵשֵׁב וְיִפּל עַל פָּנָיו וּמִתְחַנֵּן וּמַגְבִּיהַּ רֹאשׁוֹ וּמִתְחַנֵּן מְעַט וְהוּא יוֹשֵׁב בְּדִבְרֵי תַּחֲנוּנִים. וְאַחַר כָּךְ יִקְרָא <small>(תהילים קמה א)</small> ״תְּהִלָּה לְדָוִד״ (מְיֻשָּׁב) וְיִתְחַנֵּן כְּפִי כֹּחוֹ וְיִפָּטֵר לְמַעֲשָׂיו:",
      "וּבִתְפִלַּת הַמִּנְחָה מַתְחִיל לִקְרֹא <small>(תהילים קמה א)</small> ״תְּהִלָּה לְדָוִד״ מְיֻשָּׁב וְאַחַר כָּךְ עוֹמֵד וּמִתְפַּלֵּל תְּפִלַּת הַמִּנְחָה וּכְשֶׁמַּשְׁלִים נוֹפֵל עַל פָּנָיו וּמִתְחַנֵּן וּמַגְבִּיהַּ רֹאשׁוֹ וְיִתְחַנֵּן כְּפִי כֹּחוֹ וְיִפָּטֵר לְמַעֲשָׂיו. וּבִתְפִלַּת הָעֶרֶב קוֹרֵא קְרִיאַת שְׁמַע וּמְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ וְסוֹמֵךְ גְּאֻלָּה לִתְפִלָּה וּמִתְפַּלֵּל מְעֻמָּד וּכְשֶׁיַּשְׁלִים יֵשֵׁב מְעַט וְיִפָּטֵר. וְהַמִּתְחַנֵּן אַחַר תְּפִלַּת עַרְבִית הֲרֵי זֶה מְשֻׁבָּח. וְאַף עַל פִּי שֶׁמְּבָרֵךְ הַשְׁכִּיבֵנוּ אַחַר גָּאַל יִשְׂרָאֵל אֵינָהּ הֶפְסֵק בֵּין גְּאֻלָּה לִתְפִלָּה וַהֲרֵי שְׁתֵּיהֶן כִּבְרָכָה אַחַת אֲרֻכָּה:"
    ],
    [
      "תְּפִלַּת הַצִּבּוּר נִשְׁמַעַת תָּמִיד וַאֲפִלּוּ הָיוּ בָּהֶן חוֹטְאִים אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹאֵס בִּתְפִלָּתָן שֶׁל רַבִּים. לְפִיכָךְ צָרִיךְ אָדָם לְשַׁתֵּף עַצְמוֹ עִם הַצִּבּוּר. וְלֹא יִתְפַּלֵּל בְּיָחִיד כָּל זְמַן שֶׁיָּכוֹל לְהִתְפַּלֵּל עִם הַצִּבּוּר. וּלְעוֹלָם יַשְׁכִּים אָדָם וְיַעֲרִיב לְבֵית הַכְּנֶסֶת שֶׁאֵין תְּפִלָּתוֹ נִשְׁמַעַת בְּכָל עֵת אֶלָּא בְּבֵית הַכְּנֶסֶת. וְכָל מִי שֶׁיֵּשׁ לוֹ בֵּית הַכְּנֶסֶת בְּעִירוֹ וְאֵינוֹ מִתְפַּלֵּל בּוֹ עִם הַצִּבּוּר נִקְרָא שָׁכֵן רַע:",
      "וּמִצְוָה לָרוּץ לְבֵית הַכְּנֶסֶת שֶׁנֶּאֱמַר <small>(הושע ו ג)</small> ״וְנֵדְעָה נִרְדְּפָה לָדַעַת אֶת יְיָ׳‎״. וּכְשֶׁיֵּצֵא מִבֵּית הַכְּנֶסֶת אַל יַפְסִיעַ פְּסִיעָה גַּסָּה אֶלָּא יֵלֵךְ מְעַט מְעַט. וּכְשֶׁיִּכָּנֵס בְּבֵית הַכְּנֶסֶת יִכָּנֵס שִׁעוּר שְׁנֵי פְּתָחִים וְאַחַר כָּךְ יִתְפַּלֵּל לְקַיֵּם מַה שֶּׁנֶּאֱמַר <small>(משלי ח לד)</small> ״לִשְׁמֹר מְזוּזֹת פְּתָחָי״:",
      "בֵּית הַמִּדְרָשׁ גָּדוֹל מִבֵּית הַכְּנֶסֶת. וַחֲכָמִים גְּדוֹלִים אַף עַל פִּי שֶׁהָיוּ לָהֶם בְּעִירָם בָּתֵּי כְּנֵסִיּוֹת הַרְבֵּה לֹא הָיוּ מִתְפַּלְּלִין אֶלָּא בְּמָקוֹם שֶׁהָיוּ עוֹסְקִין שָׁם בַּתּוֹרָה וְהוּא שֶׁיִּתְפַּלֵּל שָׁם תְּפִלַּת הַצִּבּוּר:",
      "וְכֵיצַד הִיא תְּפִלַּת הַצִּבּוּר. יִהְיֶה אֶחָד מִתְפַּלֵּל בְּקוֹל רָם וְהַכּל שׁוֹמְעִים. וְאֵין עוֹשִׂין כֵּן בְּפָחוֹת מֵעֲשָׂרָה גְּדוֹלִים וּבְנֵי חוֹרִין. וּשְׁלִיחַ צִבּוּר אֶחָד מֵהֶם. וַאֲפִלּוּ הָיוּ מִקְצָתָן שֶׁכְּבָר הִתְפַּלְּלוּ וְיָצְאוּ יְדֵי חוֹבָתָן מַשְׁלִימִין לָהֶם לַעֲשָׂרָה. וְהוּא שֶׁיִּהְיוּ רֹב הָעֲשָׂרָה שֶׁלֹּא הִתְפַּלְּלוּ. וְכֵן אֵין אוֹמְרִים קְדֻשָּׁה וְלֹא קוֹרְאִין בַּתּוֹרָה וּמְבָרְכִין לְפָנֶיהָ וּלְאַחֲרֶיהָ וְלֹא מַפְטִירִין בַּנְּבִיאִים אֶלָּא בַּעֲשָׂרָה:",
      "וְכֵן לֹא יִהְיֶה אֶחָד מְבָרֵךְ בִּרְכַּת שְׁמַע וְהַכּל שׁוֹמְעִים וְעוֹנִין אַחֲרָיו אָמֵן אֶלָּא בַּעֲשָׂרָה. וְזֶה הוּא הַנִּקְרָא פּוֹרֵס עַל שְׁמַע. וְאֵין אוֹמְרִים קַדִּישׁ אֶלָּא בַּעֲשָׂרָה. וְאֵין הַכֹּהֲנִים נוֹשְׂאִים יְדֵיהֶם אֶלָּא בַּעֲשָׂרָה וְהַכֹּהֲנִים מִן הַמִּנְיָן. שֶׁכָּל עֲשָׂרָה מִיִּשְׂרָאֵל הֵם הַנִּקְרָאִים עֵדָה שֶׁנֶּאֱמַר <small>(במדבר יד כז)</small> ״עַד מָתַי לָעֵדָה הָרָעָה הַזֹּאת״ וְגוֹ׳‎ וְהָיוּ עֲשָׂרָה שֶׁהֲרֵי יָצְאוּ יְהוֹשֻׁעַ וְכָלֵב:",
      "וְכָל דְּבַר קְדֻשָּׁה לֹא יְהֵא אֶלָּא בְּתוֹךְ הָעֵדָה מִיִּשְׂרָאֵל שֶׁנֶּאֱמַר <small>(ויקרא כב לב)</small> ״וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל״. וְכָל אֵלּוּ הַדְּבָרִים אִם הִתְחִילוּ בָּהֶם בַּעֲשָׂרָה וְהָלְכוּ מִקְצָתָם אַף עַל פִּי שֶׁאֵין רַשָּׁאִין יִגְמְרוּ הַשְּׁאָר:",
      "וְצָרִיךְ לִהְיוֹת כֻּלָּם בְּמָקוֹם אֶחָד וּשְׁלִיחַ צִבּוּר עִמָּהֶם בְּמָקוֹם אֶחָד. חָצֵר קְטַנָּה שֶׁנִּפְרְצָה בִּמְלוֹאָהּ לְחָצֵר גְּדוֹלָה וְהָיוּ תִּשְׁעָה בַּגְּדוֹלָה וְיָחִיד בַּקְּטַנָּה מִצְטָרְפִין. תִּשְׁעָה בַּקְּטַנָּה וְיָחִיד בַּגְּדוֹלָה אֵין מִצְטָרְפִין. צִבּוּר בַּגְּדוֹלָה וּשְׁלִיחַ צִבּוּר בַּקְּטַנָּה יוֹצְאִין יְדֵי חוֹבָתָן. צִבּוּר בַּקְּטַנָּה וּשְׁלִיחַ צִבּוּר בַּגְּדוֹלָה אֵין יוֹצְאִין יְדֵי חוֹבָתָן שֶׁהֲרֵי הוּא מֻפְלָג מֵהֶם וְאֵינוֹ עִמָּהֶם בְּמָקוֹם אֶחָד מִפְּנֵי שֶׁיֵּשׁ בַּגְּדוֹלָה פַּסִּין מִכָּאן וּמִכָּאן הֲרֵי הִיא כְּמוֹ מֻפְלֶגֶת מִן הַקְּטַנָּה וְאֵין הַקְּטַנָּה מֻפְלֶגֶת מִן הַגְּדוֹלָה אֶלָּא הֲרֵי הִיא כְּקֶרֶן זָוִית שֶׁלָּהּ:",
      "וְכֵן אִם הָיְתָה צוֹאָה בַּגְּדוֹלָה אָסוּר לְהִתְפַּלֵּל וְלִקְרוֹת קְרִיאַת שְׁמַע בַּקְּטַנָּה. הָיְתָה צוֹאָה בַּקְּטַנָּה מֻתָּר לְהִתְפַּלֵּל וְלִקְרוֹת קְרִיאַת שְׁמַע בַּגְּדוֹלָה אִם לֹא הָיָה שָׁם רֵיחַ רַע מִפְּנֵי שֶׁהִיא מֻפְלֶגֶת מִמֶּנָּה:",
      "שְׁלִיחַ צִבּוּר מוֹצִיא אֶת הָרַבִּים יְדֵי חוֹבָתָן. כֵּיצַד. בְּשָׁעָה שֶׁהוּא מִתְפַּלֵּל וְהֵם שׁוֹמְעִין וְעוֹנִין אָמֵן אַחַר כָּל בְּרָכָה וּבְרָכָה הֲרֵי הֵן כְּמִתְפַּלְּלִין. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל אֲבָל הַיּוֹדֵעַ אֵינוֹ יוֹצֵא יְדֵי חוֹבָתוֹ אֶלָּא בִּתְפִלַּת עַצְמוֹ:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר יְמוֹת הַשָּׁנָה חוּץ מֵרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שֶׁל שְׁנַת הַיּוֹבֵל. אֲבָל בִּשְׁנֵי יָמִים אֵלּוּ שְׁלִיחַ צִבּוּר מוֹצִיא אֶת הַיּוֹדֵעַ כְּשֵׁם שֶׁמּוֹצִיא מִי שֶׁאֵינוֹ יוֹדֵעַ מִפְּנֵי שֶׁהֵם בְּרָכוֹת אֲרֻכּוֹת וְאֵין רֹב הַיּוֹדְעִים אוֹתָן יְכוֹלִין לְכַוֵּן דַּעְתָּן כִּשְׁלִיחַ צִבּוּר. לְפִיכָךְ אִם רָצָה הַיּוֹדֵעַ לִסְמֹךְ בִּשְׁנֵי יָמִים אֵלּוּ עַל תְּפִלַּת שַׁ״ץ לְהוֹצִיאוֹ יְדֵי חוֹבָתוֹ הָרְשׁוּת בְּיָדוֹ:",
      "אֵין מְמַנִּין שְׁלִיחַ צִבּוּר אֶלָּא גָּדוֹל שֶׁבַּצִּבּוּר בְּחָכְמָתוֹ וּבְמַעֲשָׂיו. וְאִם הָיָה זָקֵן הֲרֵי זֶה מְשֻׁבָּח בְּיוֹתֵר. וּמִשְׁתַּדְּלִין לִהְיוֹת שְׁלִיחַ צִבּוּר אָדָם שֶׁקּוֹלוֹ עָרֵב וְרָגִיל לִקְרוֹת. וּמִי שֶׁלֹּא נִתְמַלֵּא זְקָנוֹ אַף עַל פִּי שֶׁהוּא חָכָם גָּדוֹל לֹא יְהֵא שַׁ״ץ מִפְּנֵי כְּבוֹד צִבּוּר. אֲבָל פּוֹרֵס הוּא עַל שְׁמַע מִשֶּׁיָּבִיא שְׁתֵּי שְׂעָרוֹת אַחַר שְׁלֹשׁ עֶשְׂרֵה שָׁנִים:",
      "וְכֵן הָעִלֵּג כְּגוֹן מִי שֶׁקּוֹרֵא לְאָלֶ״ף עַיִ״ן אוֹ לְעַיִ״ן אָלֶ״ף וְכָל מִי שֶׁאֵינוֹ יָכוֹל לְהוֹצִיא אֶת הָאוֹתִיּוֹת כְּתִקּוּנָן אֵין מְמַנִּין אוֹתוֹ שְׁלִיחַ צִבּוּר. וְהָרַב מְמַנֶּה אֶחָד מִתַּלְמִידָיו לְהִתְפַּלֵּל לְפָנָיו בְּצִבּוּר. הַסּוּמָא פּוֹרֵס עַל שְׁמַע וְנַעֲשֶׂה שְׁלִיחַ צִבּוּר. אֲבָל מִי שֶׁכְּתֵפָיו מְגֻלּוֹת אַף עַל פִּי שֶׁהוּא פּוֹרֵס עַל שְׁמַע אֵינוֹ נַעֲשֶׂה שְׁלִיחַ צִבּוּר לִתְפִלָּה עַד שֶׁיִּהְיֶה עָטוּף:"
    ],
    [
      "סֵדֶר תְּפִלּוֹת הַצִּבּוּר כָּךְ הוּא. בַּשַּׁחַר כָּל הָעָם יוֹשְׁבִים וּשְׁלִיחַ צִבּוּר יוֹרֵד לִפְנֵי הַתֵּבָה וְעוֹמֵד בְּאֶמְצַע הָעָם וּמַתְחִיל וְאוֹמֵר קַדִּישׁ וְכָל הָעָם עוֹנִים אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא בְּכָל כֹּחָן. וְעוֹנִין אָמֵן בְּסוֹף קַדִּישׁ. וְאַחַר כָּךְ אוֹמֵר בָּרְכוּ אֶת יְיָ׳‎ הַמְבֹרָךְ וְהֵם עוֹנִים בָּרוּךְ יְיָ׳‎ הַמְבֹרָךְ לְעוֹלָם וָעֶד. וּמַתְחִיל וּפוֹרֵס עַל שְׁמַע בְּקוֹל רָם וְהֵם עוֹנִים אָמֵן אַחַר כָּל בְּרָכָה וּבְרָכָה. וְהַיּוֹדֵעַ לְבָרֵךְ וְלִקְרוֹת עִמּוֹ קוֹרֵא עַד שֶׁמְּבָרֵךְ גָּאַל יִשְׂרָאֵל:",
      "וְהַכּל עוֹמְדִין מִיָּד וּמִתְפַּלְּלִים בְּלַחַשׁ. וּמִי שֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל עוֹמֵד וְשׁוֹתֵק עַד שֶׁיִּתְפַּלֵּל שְׁלִיחַ צִבּוּר בְּלַחַשׁ עִם שְׁאָר הָעָם. וְכָל מִי שֶׁיִּגְמֹר תְּפִלָּתוֹ עִם הַצִּבּוּר יַפְסִיעַ שָׁלֹשׁ פְּסִיעוֹת לַאֲחוֹרָיו וְיַעֲמֹד בַּמָּקוֹם שֶׁהִגִּיעַ אֵלָיו בְּעֵת שֶׁיַּפְסִיעַ:",
      "וְאַחַר שֶׁיַּפְסִיעַ שְׁלִיחַ צִבּוּר שָׁלֹשׁ פְּסִיעוֹת לַאֲחוֹרָיו וְיַעֲמֹד מַתְחִיל וּמִתְפַּלֵּל בְּקוֹל רָם מִתְּחִלַּת הַבְּרָכוֹת לְהוֹצִיא אֶת מִי שֶׁלֹּא הִתְפַּלֵּל. וְהַכּל עוֹמְדִים וְשׁוֹמְעִים וְעוֹנִין אָמֵן אַחַר כָּל בְּרָכָה וּבְרָכָה. בֵּין אֵלּוּ שֶׁלֹּא יָצְאוּ יְדֵי חוֹבָתָן בֵּין אֵלּוּ שֶׁכְּבָר יָצְאוּ יְדֵי חוֹבָתָן:",
      "וְאוֹמֵר קְדֻשָּׁה בִּבְרָכָה שְׁלִישִׁית. וְכֵיוָן שֶׁהִגִּיעַ שְׁלִיחַ צִבּוּר לִקְדֻשָּׁה יֵשׁ רְשׁוּת לְכָל אֶחָד וְאֶחָד לַחֲזֹר בַּמָּקוֹם שֶׁעָמַד בּוֹ בַּתְּפִלָּה. וּכְשֶׁיַּגִּיעַ שְׁלִיחַ צִבּוּר לְמוֹדִים וְכוֹרֵעַ כָּל הָעָם שׁוֹחִין מְעַט וְלֹא יִשְׁחוּ יוֹתֵר מִדַּאי. וְאוֹמְרִים מוֹדִים אֲנַחְנוּ לָךְ יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי כָל בָּשָׂר יוֹצְרֵנוּ יוֹצֵר בְּרֵאשִׁית בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ כֵּן תְּחַיֵּנוּ וּתְחָנֵנוּ וְתֶאֱסֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ לִשְׁמֹר חֻקֶּיךָ וּלְעָבְדְךָ בֶּאֱמֶת וְלַעֲשׂוֹת רְצוֹנְךָ בְּלֵבָב שָׁלֵם עַל שֶׁאָנוּ מוֹדִים לָךְ. וְכָל הָאוֹמֵר מוֹדִים מוֹדִים מְשַׁתְּקִין אוֹתוֹ:",
      "וְאַחַר שֶׁיַּשְׁלִים כָּל הַתְּפִלָּה יֵשֵׁב וְיִפּל עַל פָּנָיו וְיִטֶּה מְעַט הוּא וְכָל הַצִּבּוּר וְיִתְחַנֵּן וְהוּא נוֹפֵל. וְיֵשֵׁב וְיַגְבִּיהַּ רֹאשׁוֹ הוּא וּשְׁאָר הָעָם וּמִתְחַנֵּן מְעַט בְּקוֹל רָם מְיֻשָּׁב. וְאַחַר כָּךְ יַעֲמֹד שְׁלִיחַ צִבּוּר לְבַדּוֹ וְאוֹמֵר קַדִּישׁ פַּעַם שְׁנִיָּה וְהֵם עוֹנִים כְּדֶרֶךְ שֶׁעוֹנִין בַּתְּחִלָּה. וְאוֹמֵר <small>(תהילים עח לח)</small> ״וְהוּא רַחוּם״ וְכוּ׳‎ <small>(תהילים קמה א)</small> ״תְּהִלָּה״ וְכוּ׳‎. הוּא עוֹמֵד וְהֵם יוֹשְׁבִים וְהֵם קוֹרְאִים עִמּוֹ. וְאַחַר כָּךְ אוֹמֵר <small>(ישעיה נט כ)</small> ״וּבָא לְצִיּוֹן גּוֹאֵל״ וְכוּ׳‎ <small>(ישעיה נט כא)</small> ״וַאֲנִי זֹאת״ וְכוּ׳‎ <small>(תהילים כב ד)</small> ״וְאַתָּה קָדוֹשׁ״ <small>(ישעיה ו ג)</small> ״וְקָרָא זֶה אֶל זֶה וְאָמַר קָדוֹשׁ״ וְגוֹמֵר הַקְּדֻשָּׁה וְהֵם עוֹנִין <small>(ישעיה ו ג)</small> ״קָדוֹשׁ קָדוֹשׁ״ שָׁלֹשׁ פְּעָמִים. וְחוֹזֵר וְקוֹרֵא הַקְּדֻשָּׁה תַּרְגּוּם וְאוֹמֵר <small>(יחזקאל ג יב)</small> ״וַתִּשָּׂאֵנִי רוּחַ״ וְכוּ׳‎ וְקוֹרֵא אוֹתוֹ תַּרְגּוּם וְאוֹמֵר <small>(שמות טו יח)</small> ״יְיָ׳‎ יִמְלוֹךְ לְעוֹלָם וָעֶד״ וְקוֹרְאֵהוּ תַּרְגּוּם כְּדֵי לְהָבִין הָעָם:",
      "וְאֵלּוּ הַפְּסוּקִים שֶׁלִּפְנֵי הַקְּדֻשָּׁה וְשֶׁל אַחֲרֶיהָ עִם תַּרְגּוּמָן הֵם הַנִּקְרָאִין סֵדֶר קְדֻשָּׁה. וְאַחַר כָּךְ מִתְחַנֵּן בְּדִבְרֵי תַּחֲנוּנִים וּבִפְסוּקֵי רַחֲמִים וְאוֹמֵר קַדִּישׁ וְכָל הָעָם עוֹנִין כְּדַרְכָּן וְנִפְטָרִין:",
      "מִי שֶׁאָמַר בְּתַחֲנוּנִים מִי שֶׁרִחֵם עַל קַן צִפּוֹר שֶׁלֹּא לִקַּח הָאֵם עַל הַבָּנִים אוֹ שֶׁלֹּא לִשְׁחֹט אוֹתוֹ וְאֶת בְּנוֹ בְּיוֹם אֶחָד יְרַחֵם עָלֵינוּ וְכַיּוֹצֵא בְּעִנְיָן זֶה מְשַׁתְּקִין אוֹתוֹ. מִפְּנֵי שֶׁמִּצְוֹת אֵלּוּ גְּזֵרַת הַכָּתוּב הֵן וְאֵינָן רַחֲמִים. שֶׁאִלּוּ הָיוּ מִפְּנֵי רַחֲמִים לֹא הָיָה מַתִּיר לָנוּ שְׁחִיטָה כָּל עִקָּר. וְכֵן לֹא יַרְבֶּה בְּכִנּוּיִים שֶׁל שֵׁם וְיֹאמַר <small>(דברים י יז)</small> ״הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא״ וְהֶחָזָק וְהָאַמִּיץ וְהָעִזּוּז. שֶׁאֵין כֹּחַ בָּאָדָם לְהַגִּיעַ בְּסוֹף שְׁבָחָיו. אֶלָּא אוֹמֵר מַה שֶּׁאָמַר משֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם:",
      "בְּמִנְחָה אוֹמֵר שְׁלִיחַ צִבּוּר <small>(תהילים פד ה)</small> ״אַשְׁרֵי יוֹשְׁבֵי בֵּיתֶךָ״ וְכוּ׳‎ <small>(תהילים קמה א)</small> ״תְּהִלָּה לְדָוִד״ וְכוּ׳‎ קוֹרֵא הוּא וְהָעָם מְיֻשָּׁב וְעוֹמֵד שְׁלִיחַ צִבּוּר וְאוֹמֵר קַדִּישׁ וְהֵם עוֹמְדִים אַחֲרָיו וְעוֹנִין כְּדַרְכָּן וּמִתְפַּלְּלִין כֻּלָּם בְּלַחַשׁ. וְאַחַר כָּךְ חוֹזֵר שְׁלִיחַ צִבּוּר וּמִתְפַּלֵּל בְּקוֹל רָם כְּדֶרֶךְ שֶׁעָשָׂה בְּשַׁחֲרִית עַד שֶׁיַּשְׁלִים כָּל הַתְּפִלָּה. וְנוֹפְלִים עַל פְּנֵיהֶם וּמִתְחַנֵּן וּמַגְבִּיהַּ רֹאשׁוֹ הוּא וְהֵם. וּמִתְחַנֵּן מְעַט מְיֻשָּׁב כְּדֶרֶךְ שֶׁעָשָׂה בְּשַׁחֲרִית וְעוֹמֵד וְאוֹמֵר קַדִּישׁ וְכָל הָעָם עוֹנִין כְּדַרְכָּן וְנִפְטָרִין לְמַעֲשֵׂיהֶם:",
      "בָּעֶרֶב כָּל הָעָם יוֹשְׁבִין וְהוּא עוֹמֵד וְאוֹמֵר <small>(תהילים עח לח)</small> ״וְהוּא רַחוּם״ כוּ׳‎ בָּרְכוּ אֶת יְיָ׳‎ הַמְבֹרָךְ וְכוּ׳‎ וְהֵם עוֹנִין בָּרוּךְ יְיָ׳‎ הַמְבֹרָךְ לְעוֹלָם וָעֶד. וּמַתְחִיל לִפְרֹס עַל שְׁמַע וְאוֹמֵר קַדִּישׁ וְאַחַר כָּךְ הַכּל עוֹמְדִים וּמִתְפַּלְּלִין בְּלַחַשׁ. וּכְשֶׁמַּשְׁלִימִין אוֹמֵר קַדִּישׁ וְהֵם נִפְטָרִין. וְאֵינוֹ חוֹזֵר לְהִתְפַּלֵּל בְּקוֹל רָם עַרְבִית לְפִי שֶׁאֵין תְּפִלַּת עַרְבִית חוֹבָה לְפִיכָךְ לֹא יְבָרֵךְ בְּרָכוֹת לְבַטָּלָה שֶׁאֵין כָּאן אָדָם שֶׁנִּתְחַיֵּב בָּהֶם כְּדֵי לְהוֹצִיאוֹ יְדֵי חוֹבָתוֹ:",
      "בְּלֵילֵי שַׁבָּתוֹת חוֹזֵר שַׁ״ץ אַחַר שֶׁמִּתְפַּלֵּל בְּלַחַשׁ עִם הַצִּבּוּר וּמִתְפַּלֵּל בְּקוֹל רָם. אֲבָל אֵינוֹ מִתְפַּלֵּל שֶׁבַע אֶלָּא בְּרָכָה אַחַת מֵעֵין שֶׁבַע. וְכֵן הוּא אוֹמֵר בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ אֱלֹהֵי אַבְרָהָם אֱלֹהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא אֵל עֶלְיוֹן קוֹנֶה בְּרַחֲמָיו שָׁמַיִם וָאָרֶץ. מָגֵן אָבוֹת בִּדְבָרוֹ מְחַיֵּה מֵתִים בְּמַאֲמָרוֹ הָאֵל הַקָּדוֹשׁ שֶׁאֵין כָּמוֹהוּ הַמֵּנִיחַ לְעַמּוֹ בְּשַׁבַּת קָדְשׁוֹ כִּי בָם רָצָה לְהָנִיחַ לָהֶם לְפָנָיו נַעֲבֹד בְּיִרְאָה וָפַחַד וְנוֹדֶה לִשְׁמוֹ בְּכָל יוֹם תָּמִיד מֵעֵין הַבְּרָכוֹת אֵל הַהוֹדָאוֹת אֲדוֹן הַשָּׁלוֹם מְקַדֵּשׁ הַשַּׁבָּת וּמְבָרֵךְ הַשְּׁבִיעִי וּמֵנִיחַ בִּקְדֻשָּׁה לְעַם מְדֻשְּׁנֵי עֹנֶג זֵכֶר לְמַעֲשֵׂה בְרֵאשִׁית. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ רְצֵה נָא בִּמְנוּחָתֵנוּ וְכוּ׳‎ בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ הַשַּׁבָּת. וְאוֹמֵר קַדִּישׁ וְנִפְטָרִין כָּל הָעָם:",
      "וְלָמָּה תִּקְּנוּ חֲכָמִים זֶה. מִפְּנֵי שֶׁרֹב הָעָם בָּאִין לְהִתְפַּלֵּל עַרְבִית בְּלֵילֵי שַׁבָּתוֹת וְיִהְיֶה שָׁם מִי שֶׁנִּתְאַחֵר לָבוֹא וְלֹא הִשְׁלִים תְּפִלָּתוֹ וְיִשָּׁאֵר לְבַדּוֹ בְּבֵית הַכְּנֶסֶת וְיָבוֹא לִידֵי סַכָּנָה. לְפִיכָךְ חוֹזֵר שְׁלִיחַ צִבּוּר וּמִתְפַּלֵּל כְּדֵי שֶׁיִּתְעַכְּבוּ כָּל הָעָם עַד שֶׁיַּשְׁלִים הַמִּתְאַחֵר וְיֵצֵא עִמָּהֶם:",
      "לְפִיכָךְ יוֹם טוֹב שֶׁחָל לִהְיוֹת בְּשַׁבָּת אוֹ יוֹם הַכִּפּוּרִים אוֹ רֹאשׁ חֹדֶשׁ אֵין שְׁלִיחַ צִבּוּר הַיּוֹרֵד עַרְבִית לִפְנֵי הַתֵּבָה מַזְכִּיר עִנְיַן הַיּוֹם בִּבְרָכָה זוֹ אֲבָל חוֹתֵם בָּהּ מְקַדֵּשׁ הַשַּׁבָּת בִּלְבַד לְפִי שֶׁלֹּא נִתְחַיֵּב הַיּוֹם בִּבְרָכָה זוֹ:",
      "בְּשַׁבָּתוֹת וְיָמִים טוֹבִים כְּשֶׁגּוֹמֵר שְׁלִיחַ צִבּוּר תְּפִלַּת שַׁחֲרִית בְּקוֹל רָם אוֹמֵר קַדִּישׁ וְאַחַר כָּךְ <small>(תהילים קמה א)</small> ״תְּהִלָּה לְדָוִד״ וְכוּ׳‎ וְאוֹמֵר קַדִּישׁ. וּמִתְפַּלְּלִין מוּסָף בְּלַחַשׁ וְאַחַר כָּךְ מִתְפַּלֵּל מוּסָף בְּקוֹל רָם כְּדֶרֶךְ שֶׁעָשָׂה בְּשַׁחֲרִית. וְאוֹמֵר קַדִּישׁ אַחַר תְּפִלַּת מוּסָף וְהָעָם נִפְטָרִין. וְאֵין אוֹמְרִין קְדֻשָּׁה וְתַחֲנוּנִים אַחַר תְּפִלַּת שַׁחֲרִית כִּשְׁאָר הַיָּמִים אֶלָּא אוֹמֵר אוֹתָהּ קֹדֶם תְּפִלַּת הַמִּנְחָה. כֵּיצַד. קוֹרֵא תְּהִלָּה לְדָוִד וְאוֹמֵר סֵדֶר הַיּוֹם וְדִבְרֵי תַּחֲנוּנִים וְאוֹמֵר קַדִּישׁ וּמִתְפַּלְּלִין מִנְחָה וְחוֹזֵר וּמַשְׁמִיעַ תְּפִלַּת מִנְחָה בְּקוֹל רָם וְאוֹמֵר קַדִּישׁ: ",
      "בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד אוֹמֵר סֵדֶר קְדֻשָּׁה קֹדֶם תְּפִלַּת מוּסָף. בְּמוֹצָאֵי שַׁבָּת אוֹמֵר סֵדֶר הַיּוֹם גַּם אַחַר תְּפִלַּת הָעֶרֶב וְאוֹמְרִים קַדִּישׁ וְאַחַר כָּךְ מַבְדִּיל:"
    ],
    [
      "מִי שֶׁהִתְפַּלֵּל וְלֹא כִּוֵּן אֶת לִבּוֹ יַחֲזֹר וְיִתְפַּלֵּל בְּכַוָּנָה. וְאִם כִּוֵּן אֶת לִבּוֹ בִּבְרָכָה רִאשׁוֹנָה שׁוּב אֵינוֹ צָרִיךְ. מִי שֶׁטָּעָה בְּאַחַת מִשָּׁלֹשׁ בְּרָכוֹת הָרִאשׁוֹנוֹת חוֹזֵר לָרֹאשׁ. וְאִם טָעָה בְּאַחַת מִשָּׁלֹשׁ בְּרָכוֹת אַחֲרוֹנוֹת יַחֲזֹר לַעֲבוֹדָה. וְאִם טָעָה בְּאַחַת מִן הָאֶמְצָעִיּוֹת חוֹזֵר לִתְחִלַּת בְּרָכָה שֶׁטָּעָה בָּהּ וּמַשְׁלִים תְּפִלָּתוֹ עַל הַסֵּדֶר. וְכֵן שְׁלִיחַ צִבּוּר שֶׁטָּעָה כְּשֶׁהוּא מִתְפַּלֵּל בְּקוֹל רָם עַל דֶּרֶךְ זוֹ הוּא חוֹזֵר:",
      "אֲבָל אִם טָעָה שְׁלִיחַ צִבּוּר כְּשֶׁהוּא מִתְפַּלֵּל בְּלַחַשׁ אֲנִי אוֹמֵר שֶׁאֵינוֹ חוֹזֵר וּמִתְפַּלֵּל פַּעַם שְׁנִיָּה מִפְּנֵי טֹרַח צִבּוּר אֶלָּא סוֹמֵךְ עַל הַתְּפִלָּה שֶׁמִּתְפַּלֵּל בְּקוֹל רָם. וְהוּא שֶׁלֹּא טָעָה בְּשָׁלֹשׁ רִאשׁוֹנוֹת שֶׁאִם טָעָה בָּהֶם לְעוֹלָם חוֹזֵר כְּמוֹ שֶׁהַיָּחִיד חוֹזֵר:",
      "שְׁלִיחַ צִבּוּר שֶׁטָּעָה וְנִבְהַל וְלֹא יָדַע מֵהֵיכָן יַתְחִיל וְשָׁהָה שָׁעָה יַעֲמֹד אַחֵר תַּחְתָּיו. וְאִם טָעָה בְּבִרְכַּת הָאֶפִּקוֹרְסִין אֵין מַמְתִּינִין לוֹ אֶלָּא מִיָּד יַעֲמֹד אַחֵר תַּחְתָּיו שֶׁמָּא אֶפִּיקוֹרְסוּת נִזְרְקָה בּוֹ. וְהוּא שֶׁלֹּא הִתְחִיל בָּהּ אֲבָל אִם הִתְחִיל בָּהּ מַמְתִּינִין לוֹ שָׁעָה. וְלֹא יְהֵא הַשֵּׁנִי סַרְבָן בְּאוֹתָהּ שָׁעָה:",
      "וּמֵהֵיכָן הוּא מַתְחִיל, מִתְּחִלַּת בְּרָכָה שֶׁטָּעָה בָּהּ רִאשׁוֹן אִם טָעָה בְּאַחַת מִן הָאֶמְצָעִיּוֹת. אֲבָל אִם טָעָה בְּאַחַת מִן הַשָּׁלֹשׁ רִאשׁוֹנוֹת מַתְחִיל הַשֵּׁנִי מִן הָרֹאשׁ. וְאִם טָעָה בְּאַחַת מִן הָאַחֲרוֹנוֹת יַתְחִיל הַשֵּׁנִי מִן הָעֲבוֹדָה:",
      "הָאוֹמֵר אֵינִי יוֹרֵד לִפְנֵי הַתֵּבָה מִפְּנֵי שֶׁבְּגָדַי צְבוּעִים אַף בִּלְבָנִים לֹא יַעֲבֹר בְּאוֹתָהּ תְּפִלָּה. אָמַר אֵינִי עוֹבֵר מִפְּנֵי שֶׁיֵּשׁ בְּרַגְלִי סַנְדָּל אַף יָחֵף לֹא יַעֲבֹר:",
      "מִי שֶׁנִּסְתַּפֵּק לוֹ אִם הִתְפַּלֵּל אִם לֹא הִתְפַּלֵּל אֵינוֹ חוֹזֵר וּמִתְפַּלֵּל אֶלָּא אִם כֵּן מִתְפַּלֵּל תְּפִלָּה זוֹ עַל דַּעַת שֶׁהִיא נְדָבָה. שֶׁאִם רָצָה יָחִיד לְהִתְפַּלֵּל כָּל הַיּוֹם תְּפִלַּת נְדָבָה יִתְפַּלֵּל. מִי שֶׁהָיָה עוֹמֵד בִּתְפִלָּה וְנִזְכַּר שֶׁכְּבָר הִתְפַּלֵּל פּוֹסֵק וַאֲפִלּוּ בְּאֶמְצַע בְּרָכָה. וְאִם הָיְתָה תְּפִלַּת עַרְבִית אֵינוֹ פּוֹסֵק שֶׁלֹּא הִתְפַּלֵּל אוֹתָהּ מִתְּחִלָּה אֶלָּא עַל דַּעַת שֶׁאֵינָהּ חוֹבָה:",
      "מִי שֶׁטָּעָה וְהִתְפַּלֵּל שֶׁל חֹל בְּשַׁבָּת לֹא יָצָא. וְאִם נִזְכַּר וְהוּא בְּתוֹךְ הַתְּפִלָּה גּוֹמֵר בְּרָכָה שֶׁהִתְחִיל בָּהּ וְחוֹזֵר וּמִתְפַּלֵּל שֶׁל שַׁבָּת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּעַרְבִית אוֹ בְּשַׁחֲרִית אוֹ בְּמִנְחָה. אֲבָל בְּמוּסָף פּוֹסֵק אֲפִלּוּ בְּאֶמְצַע הַבְּרָכָה. וְכֵן אִם הִשְׁלִים תְּפִלָּה שֶׁל חֹל עַל דַּעַת שֶׁהוּא מוּסָף חוֹזֵר וּמִתְפַּלֵּל מוּסָף. אֶחָד שַׁבָּת וְאֶחָד יוֹם טוֹב וְאֶחָד רֹאשׁ חֹדֶשׁ:",
      "מִי שֶׁטָּעָה בִּימוֹת הַגְּשָׁמִים וְלֹא אָמַר מוֹרִיד הַגֶּשֶׁם וְלֹא מוֹרִיד הַטָּל חוֹזֵר לָרֹאשׁ. וְאִם הִזְכִּיר הַטַּל אֵינוֹ חוֹזֵר. וְאִם טָעָה בִּימוֹת הַחַמָּה וְאָמַר מוֹרִיד הַגֶּשֶׁם חוֹזֵר לָרֹאשׁ. וְאִם לֹא הִזְכִּיר טַל אֵין מַחְזִירִין אוֹתוֹ, שֶׁאֵין הַטַּל נֶעֱצָר וְאֵין צָרִיךְ בַּקָּשָׁה:",
      "מִי שֶׁשָּׁכַח שְׁאֵלָה בְּבִרְכַּת הַשָּׁנִים אִם נִזְכַּר קֹדֶם שׁוֹמֵעַ תְּפִלָּה שׁוֹאֵל אֶת הַגְּשָׁמִים בְּשׁוֹמֵעַ תְּפִלָּה. וְאִם אַחַר שֶׁבֵּרֵךְ שׁוֹמֵעַ תְּפִלָּה חוֹזֵר לְבִרְכַּת הַשָּׁנִים. וְאִם לֹא נִזְכַּר עַד שֶׁהִשְׁלִים כָּל תְּפִלָּתוֹ חוֹזֵר לָרֹאשׁ וּמִתְפַּלֵּל שְׁנִיָּה:",
      "טָעָה וְלֹא הִזְכִּיר יַעֲלֶה וְיָבוֹא אִם נִזְכַּר קֹדֶם שֶׁיַּשְׁלִים תְּפִלָּתוֹ חוֹזֵר לַעֲבוֹדָה וּמַזְכִּיר. וְאִם נִזְכַּר אַחַר שֶׁהִשְׁלִים תְּפִלָּתוֹ חוֹזֵר לָרֹאשׁ. וְאִם הָיָה רָגִיל לוֹמַר תַּחֲנוּנִים אַחַר תְּפִלָּתוֹ וְנִזְכַּר אַחַר שֶׁהִשְׁלִים תְּפִלָּתוֹ קֹדֶם שֶׁיַּעֲקֹר רַגְלָיו חוֹזֵר לַעֲבוֹדָה:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים בְּחֻלּוֹ שֶׁל מוֹעֵד אוֹ בְּשַׁחֲרִית וּבְמִנְחָה שֶׁל רָאשֵׁי חֳדָשִׁים. אֲבָל עַרְבִית שֶׁל רֹאשׁ חֹדֶשׁ אִם לֹא הִזְכִּיר אֵינוֹ חוֹזֵר:",
      "כָּל מָקוֹם שֶׁהַיָּחִיד חוֹזֵר וּמִתְפַּלֵּל שַׁ״ץ חוֹזֵר וּמִתְפַּלֵּל אִם טָעָה כְּמוֹתוֹ בְּעֵת שֶׁמִּתְפַּלֵּל בְּקוֹל רָם. חוּץ מִשַּׁחֲרִית שֶׁל רֹאשׁ חֹדֶשׁ שֶׁאִם שָׁכַח שַׁ״ץ וְלֹא הִזְכִּיר יַעֲלֶה וְיָבוֹא עַד שֶׁהִשְׁלִים תְּפִלָּתוֹ אֵין מַחְזִירִין אוֹתוֹ מִפְּנֵי טֹרַח צִבּוּר. שֶׁהֲרֵי תְּפִלַּת הַמּוּסָפִין לְפָנָיו שֶׁהוּא מַזְכִּיר בָּהּ רֹאשׁ חֹדֶשׁ:",
      "עֲשָׂרָה יָמִים שֶׁמֵּרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים טָעָה וְחָתַם בָּהֶם בִּבְרָכָה שְׁלִישִׁית הָאֵל הַקָּדוֹשׁ חוֹזֵר לָרֹאשׁ. טָעָה וְחָתַם בְּעַשְׁתֵּי עֶשְׂרֵה מֶלֶךְ אוֹהֵב צְדָקָה וּמִשְׁפָּט חוֹזֵר לִתְחִלַּת הַבְּרָכָה וְחוֹתֵם בָּהּ הַמֶּלֶךְ הַמִּשְׁפָּט וּמִתְפַּלֵּל וְהוֹלֵךְ עַל הַסֵּדֶר. וְאִם לֹא נִזְכַּר אֶלָּא עַד שֶׁהִשְׁלִים כָּל תְּפִלָּתוֹ חוֹזֵר לָרֹאשׁ. אֶחָד יָחִיד וְאֶחָד שְׁלִיחַ צִבּוּר:",
      "טָעָה וְלֹא הִזְכִּיר הַבְדָּלָה בְּחוֹנֵן הַדַּעַת מַשְׁלִים תְּפִלָּתוֹ וְאֵינוֹ צָרִיךְ לַחֲזֹר. וְכֵן מִי שֶׁלֹּא הִזְכִּיר עַל הַנִּסִּים בַּחֲנֻכָּה וּבְפוּרִים וַעֲנֵנוּ בִּתְפִלַּת תַּעֲנִית אֵינוֹ חוֹזֵר וּמִתְפַּלֵּל. אֶחָד יָחִיד וְאֶחָד שְׁלִיחַ צִבּוּר. וְאִם נִזְכַּר קֹדֶם שֶׁיַּעֲקֹר אֶת רַגְלָיו אוֹמֵר עֲנֵנוּ כִּי אַתָּה שׁוֹמֵעַ תְּפִלָּה פּוֹדֶה וּמַצִּיל בְּכָל עֵת צָרָה וְצוּקָה <small>(תהילים יט טו)</small> ״יִהְיוּ לְרָצוֹן אִמְרֵי פִי״ וְגוֹ׳‎:",
      "שָׁכַח וְלֹא הִתְפַּלֵּל מִנְחָה בְּעֶרֶב שַׁבָּת יִתְפַּלֵּל עַרְבִית שְׁתַּיִם שֶׁל שַׁבָּת. וְכֵן בְּיוֹם טוֹב. שָׁכַח וְלֹא הִתְפַּלֵּל מִנְחָה בְּשַׁבָּת אוֹ בְּיוֹם טוֹב מִתְפַּלֵּל בְּמוֹצָאֵיהֶן עַרְבִית שְׁתַּיִם שֶׁל חֹל. מַבְדִּיל בָּרִאשׁוֹנָה וְאֵינוֹ מַבְדִּיל בַּשְּׁנִיָּה. וְאִם הִבְדִּיל בִּשְׁתֵּיהֶן אוֹ לֹא הִבְדִּיל בְּאַחַת מֵהֶן יָצָא. אֲבָל אִם לֹא הִבְדִּיל בָּרִאשׁוֹנָה וְהִבְדִּיל בַּשְּׁנִיָּה חוֹזֵר וּמִתְפַּלֵּל תְּפִלָּה שְׁלִישִׁית מִפְּנֵי שֶׁהָרִאשׁוֹנָה לֹא עָלְתָה לוֹ מִפְּנֵי שֶׁהִקְדִּימָהּ לִתְפִלַּת עַרְבִית. וְכָל הַמִּתְפַּלֵּל שְׁתֵּי תְּפִלּוֹת אֲפִלּוּ שַׁחֲרִית וּמוּסָף לֹא יִתְפַּלֵּל זוֹ אַחַר זוֹ אֶלָּא יִשְׁהֶה בֵּין תְּפִלָּה לִתְפִלָּה כְּדֵי שֶׁתִּתְחוֹנֵן דַּעְתּוֹ עָלָיו:",
      "אָסוּר לוֹ לַמִּתְפַּלֵּל בְּצִבּוּר שֶׁיַּקְדִּים תְּפִלָּתוֹ לִתְפִלַּת הַצִּבּוּר. הַנִּכְנָס לְבֵית הַכְּנֶסֶת וּמָצָא צִבּוּר שֶׁמִּתְפַּלְּלִין בְּלַחַשׁ אִם יָכוֹל לְהַתְחִיל וְלִגְמֹר עַד שֶׁלֹּא יַגִּיעַ שְׁלִיחַ צִבּוּר לִקְדֻשָּׁה יִתְפַּלֵּל. וְאִם לָאו יַמְתִּין עַד שֶׁיַּתְחִיל שְׁלִיחַ צִבּוּר לְהִתְפַּלֵּל בְּקוֹל רָם וְיִתְפַּלֵּל עִמּוֹ בְּלַחַשׁ מִלָּה בְּמִלָּה עַד שֶׁיַּגִּיעַ שְׁלִיחַ צִבּוּר לִקְדֻשָּׁה וְעוֹנֶה קְדֻשָּׁה עִם הַצִּבּוּר וּמִתְפַּלֵּל שְׁאָר תְּפִלָּה לְעַצְמוֹ. וְאִם הִתְחִיל לְהִתְפַּלֵּל קֹדֶם שְׁלִיחַ צִבּוּר וְהִגִּיעַ שְׁלִיחַ צִבּוּר לִקְדֻשָּׁה לֹא יַפְסִיק וְלֹא יַעֲנֶה קְדֻשָּׁה עִמָּהֶן. וְכֵן לֹא יַעֲנֶה אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבֹרָךְ וְהוּא בְּאֶמְצַע הַתְּפִלָּה וְאֵין צָרִיךְ לוֹמַר בִּשְׁאָר הַבְּרָכוֹת:"
    ],
    [
      "כָּל מָקוֹם שֶׁיֵּשׁ בּוֹ עֲשָׂרָה מִיִּשְׂרָאֵל צָרִיךְ לְהָכִין לוֹ בַּיִת שֶׁיִּכָּנְסוּ בּוֹ לִתְפִלָּה בְּכָל עֵת תְּפִלָּה וּמָקוֹם זֶה נִקְרָא בֵּית הַכְּנֶסֶת. וְכוֹפִין בְּנֵי הָעִיר זֶה אֶת זֶה לִבְנוֹת לָהֶם בֵּית הַכְּנֶסֶת וְלִקְנוֹת לָהֶם סֵפֶר תּוֹרָה נְבִיאִים וּכְתוּבִים:",
      "כְּשֶׁבּוֹנִין בֵּית הַכְּנֶסֶת אֵין בּוֹנִין אוֹתָהּ אֶלָּא בְּגָבְהָהּ שֶׁל עִיר שֶׁנֶּאֱמַר <small>(משלי א כא)</small> ״בְּרֹאשׁ הֹמִיּוֹת תִּקְרָא״. וּמַגְבִּיהִין אוֹתָהּ עַד שֶׁתְּהֵא גְּבוֹהָה מִכָּל חַצְרוֹת הָעִיר שֶׁנֶּאֱמַר <small>(עזרא ט ט)</small> ״וּלְרוֹמֵם אֶת בֵּית אֱלֹהֵינוּ״. וְאֵין פּוֹתְחִין פִּתְחֵי בֵּית הַכְּנֶסֶת אֶלָּא בַּמִּזְרָח שֶׁנֶּאֱמַר <small>(במדבר ג לח)</small> ״וְהַחֹנִים לִפְנֵי הַמִּשְׁכָּן קֵדְמָה״. וּבוֹנִין בּוֹ הֵיכָל שֶׁמַּנִּיחִין בּוֹ סֵפֶר תּוֹרָה. וּבוֹנִין הֵיכָל זֶה בָּרוּחַ שֶׁמִּתְפַּלְּלִין כְּנֶגְדּוֹ בְּאוֹתָהּ הָעִיר. כְּדֵי שֶׁיִּהְיוּ פְּנֵיהֶם אֶל מוּל הַהֵיכָל כְּשֶׁיַּעַמְדוּ לִתְפִלָּה:",
      "וּמַעֲמִידִין בִּימָה בְּאֶמְצַע הַבַּיִת כְּדֵי שֶׁיַּעֲלֶה עָלֶיהָ הַקּוֹרֵא בַּתּוֹרָה אוֹ מִי אֲשֶׁר אוֹמֵר לָעָם דִּבְרֵי כִּבּוּשִׁין כְּדֵי שֶׁיִּשְׁמְעוּ כֻּלָּם. וּכְשֶׁמַּעֲמִידִין הַתֵּבָה שֶׁיֵּשׁ בָּהּ סֵפֶר תּוֹרָה מַעֲמִידִין אוֹתָהּ בָּאֶמְצַע וַאֲחוֹרֵי הַתֵּבָה כְּלַפֵּי הַהֵיכָל וּפָנֶיהָ כְּלַפֵּי הָעָם:",
      "כֵּיצַד הָעָם יוֹשְׁבִין בְּבָתֵּי כְּנֵסִיּוֹת. הַזְּקֵנִים יוֹשְׁבִין וּפְנֵיהֶן כְּלַפֵּי הָעָם וַאֲחוֹרֵיהֶם כְּלַפֵּי הַהֵיכָל. וְכָל הָעָם יוֹשְׁבִין שׁוּרָה לִפְנֵי שׁוּרָה וּפְנֵי הַשּׁוּרָה לַאֲחוֹרֵי הַשּׁוּרָה שֶׁלְּפָנֶיהָ עַד שֶׁיִּהְיוּ פְּנֵי כָּל הָעָם כְּלַפֵּי הַקֹּדֶשׁ וּכְלַפֵּי הַזְּקֵנִים וּכְלַפֵּי הַתֵּבָה. וּבְעֵת שֶׁשְּׁלִיחַ צִבּוּר עוֹמֵד לִתְפִלָּה עוֹמֵד בָּאָרֶץ לִפְנֵי הַתֵּבָה וּפָנָיו לִפְנֵי הַקֹּדֶשׁ כִּשְׁאָר הָעָם:",
      "בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת נוֹהֲגִין בָּהֶן כָּבוֹד וּמְכַבְּדִים אוֹתָן וּמַרְבִּיצִין אוֹתָן. וְנוֹהֲגִין כָּל יִשְׂרָאֵל בִּסְפָרַד וּבַמַּעֲרָב בְּשִׁנְעָר וּבְאֶרֶץ הַצְּבִי לְהַדְלִיק עֲשָׁשִׁיּוֹת בְּבָתֵּי כְּנֵסִיּוֹת וּלְהַצִּיעַ בְּקַרְקָעָן מַחְצְלָאוֹת כְּדֵי לֵישֵׁב עֲלֵיהֶם. וּבְעָרֵי אֱדוֹם יוֹשְׁבִין בָּהּ עַל הַכִּסְאוֹת:",
      "בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת אֵין נוֹהֲגִין בָּהֶן קַלּוּת רֹאשׁ כְּגוֹן שְׂחוֹק וְהִתּוּל וְשִׂיחָה בְּטֵלָה. וְאֵין אוֹכְלִין בָּהֶן וְאֵין שׁוֹתִין בָּהֶן וְאֵין נֵאוֹתִין בָּהֶן וְאֵין מְטַיְּלִין בָּהֶן וְאֵין נִכְנָסִין בָּהֶן בַּחַמָּה מִפְּנֵי הַחַמָּה וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים. וַחֲכָמִים וְתַלְמִידֵיהֶם מֻתָּרִין לֶאֱכל וְלִשְׁתּוֹת בָּהֶן מִדֹּחַק:",
      "וְאֵין מְחַשְּׁבִין בָּהֶן חֶשְׁבּוֹנוֹת אֶלָּא אִם כֵּן הָיוּ חֶשְׁבּוֹנוֹת שֶׁל מִצְוָה כְּגוֹן קֻפָּה שֶׁל צְדָקָה וּפִדְיוֹן שְׁבוּיִים וְכַיּוֹצֵא בָּהֶן. וְאֵין מַסְפִּידִין בָּהֶן אֶלָּא הֶסְפֵּד שֶׁל רַבִּים כְּגוֹן שֶׁיִּהְיֶה שָׁם הֶסְפֵּד גְּדוֹלֵי חַכְמֵי אוֹתָהּ הָעִיר שֶׁכָּל הָעָם מִתְקַבְּצִין וּבָאִין בִּגְלָלָן:",
      "הָיָה לְבֵית הַכְּנֶסֶת אוֹ לְבֵית הַמִּדְרָשׁ שְׁנֵי פְּתָחִין לֹא יַעֲשֶׂנּוּ קַפַּנְדַּרְיָא כְּדֵי שֶׁיִּכָּנֵס בְּפֶתַח זֶה וְיֵצֵא בַּפֶּתַח שֶׁכְּנֶגְדּוֹ לְקָרֵב הַדֶּרֶךְ. שֶׁאָסוּר לִכָּנֵס בָּהֶן אֶלָּא לִדְבַר מִצְוָה:",
      "מִי שֶׁצָּרִיךְ לִכָּנֵס לְבֵית הַכְּנֶסֶת לִקְרוֹת תִּינוֹק אוֹ חֲבֵרוֹ יִכָּנֵס וְיִקְרָא מְעַט אוֹ יֹאמַר שְׁמוּעָה וְאַחַר כָּךְ יִקְרָא חֲבֵרוֹ כְּדֵי שֶׁלֹּא יִכָּנֵס בִּשְׁבִיל חֲפָצָיו בִּלְבַד. וְאִם אֵינוֹ יוֹדֵעַ יֹאמַר לְתִינוֹק מִן הַתִּינוֹקוֹת קְרָא לִי הַפָּסוּק שֶׁאַתָּה קוֹרֵא בּוֹ. אוֹ יִשְׁהֶה מְעַט בְּבֵית הַכְּנֶסֶת וְאַחַר כָּךְ יֵצֵא. שֶׁהַיְשִׁיבָה שָׁם מֵעִסְקֵי הַמִּצְוֹת הִיא שֶׁנֶּאֱמַר <small>(תהילים פד ה)</small> ״אַשְׁרֵי יוֹשְׁבֵי בֵיתֶךָ״ וְגוֹ׳‎:",
      "מִי שֶׁנִּכְנַס לְהִתְפַּלֵּל אוֹ לִקְרוֹת מֻתָּר לוֹ לָצֵאת בַּפֶּתַח שֶׁכְּנֶגְדּוֹ כְּדֵי לְקָרֵב אֶת הַדֶּרֶךְ. וּמֻתָּר לָאָדָם לִכָּנֵס לְבֵית הַכְּנֶסֶת בְּמַקְלוֹ בְּמִנְעָלוֹ וּבַאֲפֻנְדָּתוֹ וּבָאָבָק שֶׁעַל רַגְלָיו. וְאִם הָיָה צָרִיךְ לָרֹק יָרֹק בְּבֵית הַכְּנֶסֶת:",
      "בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת שֶׁחָרְבוּ בִּקְדֻשָּׁתָן הֵן עוֹמְדוֹת שֶׁנֶּאֱמַר <small>(ויקרא כו לא)</small> ״וַהֲשִׁמּוֹתִי אֶת מִקְדְּשֵׁיכֶם״ אַף עַל פִּי שֶׁהֵן שׁוֹמְמִין בִּקְדֻשָּׁתָן הֵן עוֹמְדִין. וּכְשֵׁם שֶׁנּוֹהֲגִין בָּהֶן כָּבוֹד בְּיִשּׁוּבָן כָּךְ נוֹהֲגִין בָּהֶן בְּחֻרְבָּנָם חוּץ מִכִּבּוּד וְרִבּוּץ שֶׁאֵין מְכַבְּדִין אוֹתָן וְאֵין מַרְבִּיצִין אוֹתָן. עָלוּ בָּהֶן עֲשָׂבִים תּוֹלְשִׁין אוֹתָם וּמַנִּיחִין אוֹתָן בִּמְקוֹמָן כְּדֵי שֶׁיִּרְאוּ אוֹתָן הָעָם וְתֵעוֹר רוּחָם וְיִבְנוּם:",
      "אֵין סוֹתְרִין בֵּית הַכְּנֶסֶת כְּדֵי לִבְנוֹת אַחֵר בִּמְקוֹמוֹ אוֹ בְּמָקוֹם אַחֵר. אֲבָל בּוֹנִין אַחֵר וְאַחַר כָּךְ סוֹתְרִין זֶה. שֶׁמָּא יֶאֱרַע לָהֶם אֹנֶס וְלֹא יִבְנוּ. אֲפִלּוּ כֹּתֶל אֶחָד מִמֶּנּוּ בּוֹנֶה הֶחָדָשׁ בְּצַד הַיָּשָׁן וְאַחַר כָּךְ סוֹתֵר הַיָּשָׁן:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא חָרְבוּ יְסוֹדוֹתָיו אוֹ שֶׁלֹּא נָטוּ כְּתָלָיו לִפּל. אֲבָל אִם חָרְבוּ יְסוֹדוֹתָיו אוֹ שֶׁנָּטוּ כְּתָלָיו לִפּל סוֹתְרִין אוֹתוֹ מִיָּד וּמַתְחִילִין לִבְנוֹת בִּמְהֵרָה בַּיּוֹם וּבַלַּיְלָה שֶׁמָּא תִּדְחֹק הַשָּׁעָה וְיִשָּׁאֵר חָרֵב:",
      "מֻתָּר לַעֲשׂוֹת בֵּית הַכְּנֶסֶת בֵּית הַמִּדְרָשׁ. אֲבָל בֵּית הַמִּדְרָשׁ אָסוּר לַעֲשׂוֹתוֹ בֵּית הַכְּנֶסֶת. שֶׁקְּדֻשַּׁת בֵּית הַמִּדְרָשׁ יְתֵרָה עַל קְדֻשַּׁת בֵּית הַכְּנֶסֶת וּמַעֲלִין בַּקֹּדֶשׁ וְלֹא מוֹרִידִין. וְכֵן בְּנֵי הָעִיר שֶׁמָּכְרוּ בֵּית הַכְּנֶסֶת יֵשׁ לָהֶן לִקַּח בְּדָמָיו תֵּבָה. מָכְרוּ תֵּבָה יֵשׁ לָהֶן לִקַּח בְּדָמֶיהָ מִטְפָּחוֹת אוֹ תִּיק לְסֵפֶר תּוֹרָה. מָכְרוּ מִטְפָּחוֹת אוֹ תִּיק לוֹקְחִים בְּדָמָיו חֻמָּשִׁים. מָכְרוּ חֻמָּשִׁין לוֹקְחִין בְּדָמָיו סֵפֶר תּוֹרָה. אֲבָל אִם מָכְרוּ סֵפֶר תּוֹרָה אֵין לוֹקְחִין בְּדָמָיו אֶלָּא סֵפֶר תּוֹרָה אַחֵר שֶׁאֵין שָׁם קְדֻשָּׁה לְמַעְלָה מִקְּדֻשַּׁת סֵפֶר תּוֹרָה. וְכֵן בְּמוֹתָרֶיהָ:",
      "וְכֵן אִם גָּבוּ הָעָם מָעוֹת לִבְנוֹת בֵּית הַמִּדְרָשׁ אוֹ לְבֵית הַכְּנֶסֶת אוֹ לִקְנוֹת תֵּבָה אוֹ מִטְפָּחוֹת וְתִיק אוֹ סֵפֶר תּוֹרָה וְרָצוּ לְשַׁנּוֹת כָּל מַה שֶּׁגָּבוּ. אֵין מְשַׁנִּין אוֹתָן אֶלָּא מִקְּדֻשָּׁה קַלָּה לִקְדֻשָּׁה חֲמוּרָה מִמֶּנָּה. אֲבָל אִם עֲשׂוּ מַה שֶּׁגָּבוּ לַעֲשׂוֹת וְהוֹתִירוּ מְשַׁנִּין הַמּוֹתָר לְכָל מַה שֶּׁיִּרְצוּ. וְכָל כְּלֵי בֵּית הַכְּנֶסֶת כְּבֵית הַכְּנֶסֶת. פָּרֹכֶת שֶׁעַל הָאָרוֹן שֶׁמַּנִּיחִים בּוֹ הַסְּפָרִים כְּמִטְפְּחוֹת הַסְּפָרִים. וְאִם הִתְנוּ עֲלֵיהֶם הֲרֵי הֵן כְּפִי הַתְּנַאי:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמֻּתָּר לִמְכֹּר בֵּית הַכְּנֶסֶת, בְּבֵית הַכְּנֶסֶת שֶׁל כְּפָרִים שֶׁלֹּא עָשׂוּ אוֹתוֹ אֶלָּא עַל דַּעַת בְּנֵי הַכְּפָר לְבַדָּם שֶׁיִּהְיֶה לָהֶם לְהִתְפַּלֵּל בּוֹ שֶׁאִם רָצוּ כֻּלָּם לְמָכְרוֹ מֻתָּרִין. אֲבָל בֵּית הַכְּנֶסֶת שֶׁל כְּרַכִּין הוֹאִיל וְעַל דַּעַת כָּל אַנְשֵׁי הָעוֹלָם נַעֲשָׂה שֶׁיָּבוֹא וְיִתְפַּלֵּל בּוֹ כָּל הַבָּא אֶל הַמְּדִינָה נַעֲשָׂה שֶׁל כָּל יִשְׂרָאֵל וְאֵין מוֹכְרִין אוֹתוֹ לְעוֹלָם:",
      "בְּנֵי הַכְּפָר שֶׁרָצוּ לִמְכֹּר בֵּית הַכְּנֶסֶת שֶׁלָּהֶן אוֹ לִבְנוֹת בְּדָמָיו בֵּית הַכְּנֶסֶת אַחֵר אוֹ לִקְנוֹת בְּדָמָיו תֵּבָה אוֹ סֵפֶר תּוֹרָה צְרִיכִין לְהַתְנוֹת עַל הַלּוֹקֵחַ שֶׁלֹּא לַעֲשׂוֹת אוֹתוֹ לֹא מֶרְחָץ וְלֹא בֻּרְסְקִי. וְהוּא הַמָּקוֹם שֶׁמְּעַבְּדִין בּוֹ אֶת הָעוֹרוֹת. וְלֹא בֵּית הַטְּבִילָה וְלֹא בֵּית הַמַּיִם. וְאִם הִתְנוּ שִׁבְעָה טוֹבֵי הָעִיר בְּמַעֲמַד אַנְשֵׁי הָעִיר בִּשְׁעַת מְכִירָה שֶׁיְּהֵא הַלּוֹקֵחַ מֻתָּר לַעֲשׂוֹת בּוֹ כָּל אֵלּוּ מֻתָּר:",
      "וְכֵן אִם הִתְנוּ שִׁבְעָה טוֹבֵי הָעִיר בְּמַעֲמַד אַנְשֵׁי הָעִיר עַל מוֹתַר הַדָּמִים שֶׁיִּהְיוּ חֻלִּין הֲרֵי הֵן חֻלִּין. וּכְשֶׁלּוֹקְחִין הַדָּמִים וּבוֹנִין מֵהֶן בֵּית הַכְּנֶסֶת אַחֵר אוֹ שֶׁיִּקְנוּ מֵהֶם תֵּבָה אוֹ מִטְפָּחוֹת וְתִיק אוֹ חֻמָּשִׁין אוֹ סֵפֶר תּוֹרָה הַשְּׁאָר יְהֵא חֻלִּין כְּמוֹ שֶׁהִתְנוּ וְיַעֲשׂוּ בָּהֶן מַה שֶּׁיִּרְצוּ:",
      "וְכֵן אִם קִבְּלוּ עֲלֵיהֶן כָּל אַנְשֵׁי הָעִיר אוֹ רֻבָּם אָדָם אֶחָד. כָּל מַה שֶּׁעָשָׂה עָשׂוּי וְהוּא מוֹכֵר וְנוֹתֵן לְבַדּוֹ כְּפִי מַה שֶּׁיִּרְאֶה וְיַתְנֶה כְּפִי מַה שֶּׁיִּרְאֶה:",
      "כְּשֵׁם שֶׁמֻּתָּר לָהֶם לִמְכֹּר בֵּית הַכְּנֶסֶת כָּךְ נוֹתְנִין אוֹתוֹ בְּמַתָּנָה. שֶׁאִלּוּ לֹא הָיָה לָהֶם לַצִּבּוּר הֲנָיָה בְּמַתָּנָה זוֹ לֹא נְתָנוּהוּ. אֲבָל לֹא מַשְׂכִּירִין אוֹתוֹ וְלֹא מְמַשְׁכְּנִין אוֹתוֹ. וְכֵן כְּשֶׁסּוֹתְרִין בָּתֵּי כְּנֵסִיּוֹת לִבְנוֹתָן מֻתָּרִין לִמְכֹּר וּלְהַחֲלִיף וְלָתֵת בְּמַתָּנָה הַלְּבֵנִים וְהָעֵצִים וְהֶעָפָר שֶׁלָּהֶן. אֲבָל לְהַלְווֹתָן אָסוּר שֶׁאֵין הַקְּדֻשָּׁה עוֹלָה מֵהֶן אֶלָּא בְּדָמִים אוֹ בַּהֲנָיָה שֶׁהִיא כְּדָמִים:",
      "רְחוֹבָהּ שֶׁל עִיר אַף עַל פִּי שֶׁהָעָם מִתְפַּלְּלִין בּוֹ בְּתַעֲנִיּוֹת וּבְמַעֲמָדוֹת מִפְּנֵי שֶׁהַקִּבּוּץ רַב וְאֵין בָּתֵּי כְּנֵסִיּוֹת מְכִילִין אוֹתָן אֵין בּוֹ קְדֻשָּׁה מִפְּנֵי שֶׁהוּא עַרְאַי וְלֹא נִקְבַּע לִתְפִלָּה. וְכֵן בָּתִּים וַחֲצֵרוֹת שֶׁהָעָם מִתְקַבְּצִין בָּהֶם לִתְפִלָּה אֵין בָּהֶם קְדֻשָּׁה מִפְּנֵי שֶׁלֹּא קָבְעוּ אוֹתָם לִתְפִלָּה בִּלְבַד אֶלָּא עַרְאַי מִתְפַּלְּלִים בָּהֶן כְּאָדָם שֶׁמִּתְפַּלֵּל בְּתוֹךְ בֵּיתוֹ:"
    ],
    [
      "מֹשֶׁה רַבֵּנוּ תִּקֵּן לָהֶם לִישְׂרָאֵל שֶׁיְּהוּ קוֹרִין בַּתּוֹרָה בָּרַבִּים בְּשַׁבָּת וּבְשֵׁנִי וּבַחֲמִישִׁי בְּשַׁחֲרִית כְּדֵי שֶׁלֹּא יִשְׁהוּ שְׁלֹשָׁה יָמִים בְּלֹא שְׁמִיעַת תּוֹרָה. וְעֶזְרָא תִּקֵּן שֶׁיְּהוּ קוֹרִין כֵּן בְּמִנְחָה בְּכָל שַׁבָּת מִשּׁוּם יוֹשְׁבֵי קְרָנוֹת. וְגַם הוּא תִּקֵּן שֶׁיְּהוּ קוֹרִין בְּשֵׁנִי וּבַחֲמִישִׁי שְׁלֹשָׁה בְּנֵי אָדָם וְלֹא יִקְרְאוּ פָּחוֹת מֵעֲשָׂרָה פְּסוּקִים:",
      "וְאֵלּוּ הֵן הַיָּמִים שֶׁקּוֹרִין בָּהֶם בַּתּוֹרָה בְּצִבּוּר. בְּשַׁבָּתוֹת וּבְמוֹעֲדִים וּבְרָאשֵׁי חֳדָשִׁים וּבְתַעֲנִיּוֹת וּבַחֲנֻכָּה וּבְפוּרִים וּבְשֵׁנִי וַחֲמִישִׁי שֶׁבְּכָל שָׁבוּעַ וְשָׁבוּעַ. וְאֵין מַפְטִירִין בַּנְּבִיאִים אֶלָּא בְּשַׁבָּתוֹת וְיָמִים טוֹבִים וְתִשְׁעָה בְּאָב בִּלְבַד:",
      "אֵין קוֹרִין בַּתּוֹרָה בְּצִבּוּר בְּפָחוֹת מֵעֲשָׂרָה אֲנָשִׁים גְּדוֹלִים בְּנֵי חוֹרִין. וְאֵין קוֹרִין פָּחוֹת מֵעֲשָׂרָה פְּסוּקִים. וַיְדַבֵּר עוֹלֶה מִן הַמִּנְיָן. וְלֹא יִהְיוּ הַקּוֹרִין פָּחוֹת מִשְּׁלֹשָׁה אֲנָשִׁים. וְאֵין מַתְחִילִין בְּפָרָשָׁה פָּחוֹת מִשְּׁלֹשָׁה פְּסוּקִים. וְאֵין מְשַׁיְּרִין בְּפָרָשָׁה פָּחוֹת מִשְּׁלֹשָׁה פְּסוּקִים. וְלֹא יִקְרָא הַקּוֹרֵא פָּחוֹת מִשְּׁלֹשָׁה פְּסוּקִים:",
      "שְׁלֹשָׁה שֶׁקָּרְאוּ עֲשָׂרָה פְּסוּקִים שְׁנַיִם קוֹרְאִין שְׁלֹשָׁה שְׁלֹשָׁה וְאֶחָד אַרְבָּעָה. וּבֵין שֶׁהָיָה הַקּוֹרֵא אַרְבָּעָה רִאשׁוֹן אוֹ אַחֲרוֹן אוֹ אֶמְצָעִי הֲרֵי זֶה מְשֻׁבָּח:",
      "כָּל אֶחָד וְאֶחָד מִן הַקּוֹרִין פּוֹתֵחַ סֵפֶר תּוֹרָה וּמַבִּיט לַמָּקוֹם שֶׁהוּא קוֹרֵא בּוֹ. וְאַחַר כָּךְ אוֹמֵר בָּרְכוּ אֶת יְיָ׳‎ הַמְבֹרָךְ וְכָל הָעָם עוֹנִין בָּרוּךְ ה׳‎ הַמְבֹרָךְ לְעוֹלָם וָעֶד [ ]. וְחוֹזֵר וּמְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּחַר בָּנוּ מִכָּל הָעַמִּים וְנָתַן לָנוּ אֶת תּוֹרָתוֹ בָּרוּךְ אַתָּה יְיָ׳‎ נוֹתֵן הַתּוֹרָה. וְכָל הָעָם עוֹנִין אָמֵן. וְאַחַר כָּךְ קוֹרֵא עַד שֶׁיַּשְׁלִים לִקְרוֹת וְגוֹלֵל הַסֵּפֶר וּמְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר נָתַן לָנוּ תּוֹרָתוֹ תּוֹרַת אֱמֶת וְחַיֵּי עוֹלָם נָטַע בְּתוֹכֵנוּ בָּרוּךְ אַתָּה יְיָ׳‎ נוֹתֵן הַתּוֹרָה:",
      "אֵין הַקּוֹרֵא בַּתּוֹרָה רַשַּׁאי לִקְרוֹת בַּתּוֹרָה עַד שֶׁיִּכְלֶה אָמֵן מִפִּי הַצִּבּוּר. קָרָא וְטָעָה אֲפִלּוּ בְּדִקְדּוּק אוֹת אַחַת מַחְזִירִין אוֹתוֹ עַד שֶׁיִּקְרָאֶנָּה בְּדִקְדּוּק. וְלֹא יִקְרְאוּ שְׁנַיִם בַּתּוֹרָה אֶלָּא הָאֶחָד לְבַדּוֹ. קָרָא וְנִשְׁתַּתֵּק יַעֲמֹד אַחֵר תַּחְתָּיו וְיַתְחִיל מִמָּקוֹם שֶׁהִתְחִיל הָרִאשׁוֹן שֶׁנִּשְׁתַּתֵּק וּמְבָרֵךְ בַּסּוֹף:",
      "אֵין הַקּוֹרֵא רַשַּׁאי לִקְרוֹת עַד שֶׁיֹּאמַר לוֹ גָּדוֹל שֶׁבַּצִּבּוּר לִקְרוֹת. וַאֲפִלּוּ חַזַּן הַכְּנֶסֶת אוֹ רֹאשׁ הַכְּנֶסֶת אֵינוֹ קוֹרֵא מֵעַצְמוֹ עַד שֶׁיֹּאמְרוּ לוֹ הַצִּבּוּר אוֹ גָּדוֹל שֶׁבָּהֶם לִקְרוֹת. וְצָרִיךְ אֶחָד לַעֲמֹד עִמּוֹ בִּשְׁעַת קְרִיאָה כְּדֶרֶךְ חַזָּן הָעוֹמֵד עִם הַקּוֹרְאִין:",
      "הַקּוֹרֵא יֵשׁ לוֹ לְדַלֵּג מִמָּקוֹם לְמָקוֹם בְּעִנְיָן אֶחָד כְּגוֹן <small>(ויקרא טז א)</small> ״אַחֲרֵי מוֹת״ וְ<small>(ויקרא כג כז)</small> ״אַךְ בֶּעָשׂוֹר״ שֶׁבְּפָרָשַׁת <small>(ויקרא כא א)</small> ״אֱמֹר אֶל הַכֹּהֲנִים״. וְהוּא שֶׁלֹּא יִקְרָא עַל פֶּה שֶׁאָסוּר לִקְרוֹת שֶׁלֹּא מִן הַכְּתָב אֲפִלּוּ תֵּבָה אַחַת. וְלֹא יִשְׁהֶה בְּדִלּוּג אֶלָּא כְּדֵי שֶׁיַּשְׁלִים הַתֻּרְגְּמָן תַּרְגּוּם הַפָּסוּק:",
      "כֵּיוָן שֶׁהִתְחִיל הַקּוֹרֵא לִקְרוֹת בַּתּוֹרָה אָסוּר לְסַפֵּר אֲפִלּוּ בִּדְבַר הֲלָכָה אֶלָּא הַכּל שׁוֹמְעִין וְשׁוֹתְקִין וּמְשִׂימִין לִבָּם לְמַה שֶּׁהוּא קוֹרֵא שֶׁנֶּאֱמַר <small>(נחמיה ח ג)</small> ״וְאָזְנֵי כָל הָעָם אֶל סֵפֶר הַתּוֹרָה״. וְאָסוּר לָצֵאת מִן הַכְּנֶסֶת בְּשָׁעָה שֶׁהַקּוֹרֵא קוֹרֵא. וּמֻתָּר לָצֵאת בֵּין אִישׁ לְאִישׁ. וּמִי שֶׁהוּא עוֹסֵק בַּתּוֹרָה תָּמִיד וְתוֹרָתוֹ אֻמְנוּתוֹ מֻתָּר לוֹ לַעֲסֹק בְּתַלְמוּד תּוֹרָה בְּשָׁעָה שֶׁהַקּוֹרֵא קוֹרֵא בַּתּוֹרָה:",
      "מִימוֹת עֶזְרָא נָהֲגוּ שֶׁיְּהֵא שָׁם תֻּרְגְּמָן מְתַרְגֵּם לָעָם מַה שֶּׁהַקּוֹרֵא קוֹרֵא בַּתּוֹרָה כְּדֵי שֶׁיָּבִינוּ עִנְיַן הַדְּבָרִים. וְהַקּוֹרֵא קוֹרֵא פָּסוּק אֶחָד בִּלְבַד וְשׁוֹתֵק עַד שֶׁיְּתַרְגֵּם אוֹתוֹ הַתֻּרְגְּמָן וְחוֹזֵר וְקוֹרֵא פָּסוּק שֵׁנִי. וְאֵין הַקּוֹרֵא רַשַּׁאי לִקְרוֹת לַמְתֻרְגְּמָן יוֹתֵר מִפָּסוּק אֶחָד:",
      "אֵין הַקּוֹרֵא רַשַּׁאי לְהַגְבִּיהַּ קוֹלוֹ יוֹתֵר מִן הַמְתַרְגֵּם. וְהַמְתַרְגֵּם לֹא יַגְבִּיהַּ קוֹלוֹ יוֹתֵר מִן הַקּוֹרֵא. וְאֵין הַמְתַרְגֵּם רַשַּׁאי לְתַרְגֵּם עַד שֶׁיִּכְלֶה הַפָּסוּק מִפִּי הַקּוֹרֵא. וְאֵין הַקּוֹרֵא רַשַּׁאי לִקְרוֹת פָּסוּק אַחֵר עַד שֶׁיִּכְלֶה הַתַּרְגּוּם מִפִּי הַתֻּרְגְּמָן. וְאֵין הַתֻּרְגְּמָן נִשְׁעָן לֹא לְעַמּוּד וְלֹא לְקוֹרָה אֶלָּא עוֹמֵד בְּאֵימָה וּבְיִרְאָה. וְלֹא יְתַרְגֵּם מִתּוֹךְ הַכְּתָב אֶלָּא עַל פֶּה. וְאֵין הַקּוֹרֵא רַשַּׁאי לְסַיֵּעַ לַתֻּרְגְּמָן שֶׁלֹּא יֹאמְרוּ תַּרְגּוּם כָּתוּב בַּתּוֹרָה. וְהַקָּטָן מְתַרְגֵּם עַל יְדֵי גָּדוֹל וְאֵין כָּבוֹד לַגָּדוֹל שֶׁיְּתַרְגֵּם עַל יְדֵי קָטָן. וְלֹא יִהְיוּ הַמְתַרְגְּמִין שְׁנַיִם כְּאֶחָד אֶלָּא אֶחָד קוֹרֵא וְאֶחָד מְתַרְגֵּם:",
      "וְלֹא כָּל הַמִּקְרָאוֹת מְתַרְגְּמִינַן בְּצִבּוּר. <small>(בראשית לה כב)</small> ״מַעֲשֵׂה רְאוּבֵן״ וּ<small>(במדבר ו כב כז)</small> ״בִרְכַּת כֹּהֲנִים״ וּמַעֲשֵׂה הָעֵגֶל מִן <small>(שמות לב כא)</small> ״וַיֹּאמֶר משֶׁה אֶל אַהֲרֹן״ עַד <small>(שמות לב כה)</small> ״וַיַּרְא משֶׁה אֶת הָעָם״ וְגוֹ׳‎ וְעוֹד פָּסוּק אֶחָד <small>(שמות לב לה)</small> ״וַיִּגֹּף ה׳‎ אֶת הָעָם״ כֻּלָּם נִקְרָאִין וְלֹא מִתַּרְגְּמִין. וּבְמַעֲשֵׂה אַמְנוֹן בַּמָּקוֹם שֶׁנֶּאֱמַר <small>(שמואל ב יג א)</small> ״אַמְנוֹן בֶּן דָּוִד״ נִקְרָא וְלֹא מִתַּרְגֵּם:",
      "הַמַּפְטִיר בַּנָּבִיא צָרִיךְ לִקְרוֹת בַּתּוֹרָה תְּחִלָּה אֲפִלּוּ שְׁלֹשָׁה פְּסוּקִים. חוֹזֵר וְקוֹרֵא מַה שֶּׁקָּרָא לְפָנָיו. וְלֹא יַפְטִיר בַּנָּבִיא עַד שֶׁיִּגְלל סֵפֶר תּוֹרָה. וְלֹא יִפְחֹת מֵעֶשְׂרִים וְאֶחָד פְּסוּקִים. וְאִם שָׁלֵם הָעִנְיָן בְּפָחוֹת מֵאֵלּוּ אֵינוֹ צָרִיךְ לְהוֹסִיף. וְאִם קָרָא עֲשָׂרָה פְּסוּקִים וְתִרְגְּמָן הַמְתַרְגֵּם דַּיּוֹ וַאֲפִלּוּ לֹא שָׁלֵם הָעִנְיָן. וּבַנָּבִיא אֶחָד קוֹרֵא וַאֲפִלּוּ שְׁנַיִם מְתַרְגְּמִין. וּמְדַלֵּג מֵעִנְיָן לְעִנְיָן אַחֵר. וְאֵינוֹ מְדַלֵּג מִנָּבִיא לְנָבִיא אֶלָּא בִּנְבִיאִים שֶׁל שְׁנֵים עָשָׂר בִּלְבַד. וּבִלְבַד שֶׁלֹּא יְדַלֵּג מִסּוֹף הַסֵּפֶר לִתְחִלָּתוֹ. וְכָל הַמְדַלֵּג לֹא יִשְׁהֶה בְּדִלּוּג אֶלָּא כְּדֵי שֶׁיַּשְׁלִים הַמְתַרְגֵּם תַּרְגּוּמוֹ:",
      "הַקּוֹרֵא בַּנָּבִיא יֵשׁ לוֹ לִקְרוֹת לַתֻּרְגְּמָן שְׁלֹשָׁה פְּסוּקִים וְהַמְתַרְגֵּם מְתַרְגֵּם שְׁלָשְׁתָּן זֶה אַחַר זֶה. וְאִם הָיוּ שְׁלֹשָׁה הַפְּסוּקִים שָׁלֹשׁ פָּרָשִׁיּוֹת לֹא יִקְרָא לַתֻּרְגְּמָן אֶלָּא אֶחָד אֶחָד בִּלְבַד:",
      "הַמַּפְטִיר בַּנָּבִיא מְבָרֵךְ לְפָנָיו בְּרָכָה אַחַת. בָּרוּךְ אַתָּה ה׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּחַר בִּנְבִיאִים וְכוּ׳‎. וּמְבָרֵךְ לְאַחֲרָיו אַרְבַּע בְּרָכוֹת. בְּרָכָה רִאשׁוֹנָה חוֹתֵם בָּהּ הָאֵל הַנֶּאֱמָן בְּכָל דְּבָרָיו. שְׁנִיָּה חוֹתֵם בָּהּ בּוֹנֶה יְרוּשָׁלַיִם. שְׁלִישִׁית חוֹתֵם בָּהּ מָגֵן דָּוִד. רְבִיעִית חוֹתֵם בָּהּ עִנְיַן קְדֻשַּׁת הַיּוֹם כְּמוֹ שֶׁחוֹתֵם בַּתְּפִלָּה. וְכֵן אִם חָל רֹאשׁ חֹדֶשׁ לִהְיוֹת בְּשַׁבָּת הַמַּפְטִיר בַּנָּבִיא מַזְכִּיר רֹאשׁ חֹדֶשׁ בִּבְרָכָה זוֹ כְּמוֹ שֶׁמַּזְכִּיר בַּתְּפִלָּה:",
      "כַּמָּה הֵן הַקּוֹרְאִין. בְּשַׁבָּת בְּשַׁחֲרִית קוֹרְאִין שִׁבְעָה. וּבְיוֹם הַכִּפּוּרִים שִׁשָּׁה. וּבְיָמִים טוֹבִים חֲמִשָּׁה. אֵין פּוֹחֲתִין מֵהֶן אֲבָל מוֹסִיפִין עֲלֵיהֶם. בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד קוֹרִין אַרְבָּעָה. בְּשַׁבָּת וּבְיוֹם הַכִּפּוּרִים בְּמִנְחָה וּבְשֵׁנִי וּבַחֲמִישִׁי שֶׁל כָּל הַשָּׁנָה וּבַחֲנֻכָּה וּבְפוּרִים בְּשַׁחֲרִית וּבִימֵי הַתַּעֲנִית בְּשַׁחֲרִית וּבְמִנְחָה קוֹרִין שְׁלֹשָׁה. אֵין פּוֹחֲתִין מִמִּנְיַן זֶה וְאֵין מוֹסִיפִין עֲלֵיהֶן:",
      "אִשָּׁה לֹא תִּקְרָא בְּצִבּוּר מִפְּנֵי כְּבוֹד הַצִּבּוּר. קָטָן הַיּוֹדֵעַ לִקְרוֹת וְיוֹדֵעַ לְמִי מְבָרְכִין עוֹלֶה מִמִּנְיַן הַקּוֹרְאִים. וְכֵן מַפְטִיר עוֹלֶה מֵהַמִּנְיָן שֶׁהֲרֵי הוּא קוֹרֵא בַּתּוֹרָה. וְאִם הִפְסִיק שְׁלִיחַ צִבּוּר בְּקַדִּישׁ בֵּין מַשְׁלִים וּבֵין הַמַּפְטִיר אֵינוֹ עוֹלֶה מִן הַמִּנְיָן. צִבּוּר שֶׁלֹּא הָיָה בָּהֶם יוֹדֵעַ לִקְרוֹת אֶלָּא אֶחָד עוֹלֶה וְקוֹרֵא וְיוֹרֵד וְחוֹזֵר וְקוֹרֵא שְׁנִיָּה וּשְׁלִישִׁית עַד שֶׁיִּגְמֹר מִנְיַן הַקּוֹרְאִים שֶׁל אוֹתוֹ הַיּוֹם:",
      "בְּכָל קְרִיאָה וּקְרִיאָה מֵאֵלּוּ כֹּהֵן קוֹרֵא רִאשׁוֹן וְאַחֲרָיו לֵוִי וְאַחֲרָיו מִיִּשְׂרָאֵל. וּמִנְהָג פָּשׁוּט הוּא הַיּוֹם שֶׁאֲפִלּוּ כֹּהֵן עַם הָאָרֶץ קוֹדֵם לִקְרוֹת לִפְנֵי חָכָם גָּדוֹל יִשְׂרָאֵל. וְכָל מִי שֶׁהוּא גָּדוֹל מֵחֲבֵרוֹ בְּחָכְמָה קֹדֶם לִקְרוֹת. וְהָאַחֲרוֹן שֶׁגּוֹלֵל סֵפֶר תּוֹרָה נוֹטֵל שָׂכָר כְּנֶגֶד הַכּל. לְפִיכָךְ עוֹלֶה וּמַשְׁלִים אֲפִלּוּ גָּדוֹל שֶׁבַּצִּבּוּר:",
      "אֵין שָׁם כֹּהֵן עוֹלֶה יִשְׂרָאֵל. וְלֹא יַעֲלֶה אַחֲרָיו לֵוִי כְּלָל. אֵין שָׁם לֵוִי כֹּהֵן שֶׁקָּרָא רִאשׁוֹן חוֹזֵר וְקוֹרֵא הוּא עַצְמוֹ פַּעַם שְׁנִיָּה בִּמְקוֹם לֵוִי. אֲבָל לֹא יִקְרָא אַחֲרָיו כֹּהֵן אַחֵר שֶׁמָּא יֹאמְרוּ הָרִאשׁוֹן פָּסוּל וּלְפִיכָךְ עוֹלֶה כֹּהֵן אַחֵר. וְכֵן לֹא יִקְרָא לֵוִי אַחַר לֵוִי שֶׁמָּא יֹאמְרוּ אֶחָד מִשְּׁנֵיהֶם פָּסוּל:",
      "כֵּיצַד סֵדֶר הַקְּרִיאָה בַּתּוֹרָה. אַחַר הַתְּפִלָּה כָּל יוֹם שֶׁיֵּשׁ בּוֹ תְּפִלַּת מוּסָף אַחַר שֶׁיִּגְמֹר שְׁלִיחַ צִבּוּר תְּפִלַּת שַׁחֲרִית אוֹמֵר קַדִּישׁ וּמוֹצִיא סֵפֶר תּוֹרָה וְקוֹרֵא לְאֶחָד אֶחָד מִן הַצִּבּוּר וְעוֹלִין וְקוֹרִין בַּתּוֹרָה. וּכְשֶׁגּוֹמְרִין מַחֲזִיר סֵפֶר תּוֹרָה לִמְקוֹמָהּ וְאוֹמֵר קַדִּישׁ וּמִתְפַּלְּלִין תְּפִלַּת מוּסָף. וְיָמִים שֶׁיֵּשׁ בָּהֶן מַפְטִיר וּמוּסָף נָהֲגוּ לוֹמַר קַדִּישׁ קֹדֶם שֶׁיַּעֲלֶה הַמַּפְטִיר. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לוֹמַר קַדִּישׁ אַחַר הַמַּפְטִיר:",
      "וּבְמִנְחָה שֶׁל שַׁבָּת וְשֶׁל יוֹם הַכִּפּוּרִים אַחַר שֶׁיִּגְמֹר שְׁלִיחַ צִבּוּר <small>(תהילים קמה א)</small> ״תְּהִלָּה לְדָוִד״ וְסֵדֶר הַיּוֹם אוֹמֵר קַדִּישׁ וּמוֹצִיא סֵפֶר תּוֹרָה וְעוֹלִין וְקוֹרִין בּוֹ וּמַחֲזִירוֹ וְאוֹמֵר קַדִּישׁ וּמִתְפַּלְּלִין מִנְחָה. וְכֵן בְּתַעֲנִית קוֹרְאִין בְּמִנְחָה וְאַחַר כָּךְ אוֹמֵר קַדִּישׁ וּמִתְפַּלְּלִין תְּפִלַּת מִנְחָה. אֲבָל בְּיוֹם טוֹב לֹא נָהֲגוּ לִקְרוֹת בְּמִנְחָה:",
      "וְיוֹם שֶׁאֵין בּוֹ מוּסָף כְּשֶׁגּוֹמֵר תְּפִלַּת שַׁחֲרִית אוֹמֵר קַדִּישׁ וּמוֹצִיא סֵפֶר תּוֹרָה וְקוֹרְאִין בּוֹ וּמַחֲזִירוֹ וְאוֹמֵר קַדִּישׁ וְאַחַר כָּךְ אוֹמֵר <small>(תהילים קמה א)</small> ״תְּהִלָּה לְדָוִד״ וְסֵדֶר הַיּוֹם כְּדֶרֶךְ שֶׁאוֹמְרִים בְּכָל יוֹם וְאוֹמֵר קַדִּישׁ וְכָל הָעָם נִפְטָרִין:",
      "אֵין קוֹרְאִין בְּחֻמָּשִׁין בְּבָתֵּי כְּנֵסִיּוֹת מִשּׁוּם כְּבוֹד צִבּוּר. וְאֵין גּוֹלְלִין סֵפֶר תּוֹרָה בְּצִבּוּר מִפְּנֵי טֹרַח הַצִּבּוּר שֶׁלֹּא יַטְרִיחַ עֲלֵיהֶם לִהְיוֹתָן עוֹמְדִין עַד שֶׁיִּגְלל סֵפֶר תּוֹרָה. לְפִיכָךְ אִם יִצְטָרְכוּ לִקְרוֹת שְׁנֵי עִנְיָנִים מוֹצִיאִין שְׁנֵי סִפְרֵי תּוֹרָה. וְלֹא יִקְרָא אִישׁ אֶחָד עִנְיָן אֶחָד בִּשְׁתֵּי תּוֹרוֹת שֶׁמָּא יֹאמְרוּ סֵפֶר רִאשׁוֹן פָּגוּם הָיָה וּלְפִיכָךְ קוֹרֵא בַּשֵּׁנִי:",
      "כָּל הַגּוֹלֵל סֵפֶר תּוֹרָה גּוֹלְלוּ מִבַּחוּץ וּכְשֶׁהוּא מְהַדְּקוֹ מְהַדְּקוֹ מִבִּפְנִים. וְצָרִיךְ לְהַעֲמִידוֹ עַל הַתֶּפֶר כְּדֵי שֶׁלֹּא יִקָּרַע. מָקוֹם שֶׁמּוֹצִיאִין סֵפֶר תּוֹרָה אַחַר שֶׁקּוֹרְאִין בּוֹ וּמוֹלִיכִין אוֹתוֹ לְבֵית אַחֵר לְהַצְנִיעוֹ אֵין הַצִּבּוּר רַשָּׁאִין לָצֵאת עַד שֶׁיֵּצֵא סֵפֶר תּוֹרָה וִילַוּוּ אוֹתוֹ וְהֵם אַחֲרָיו עַד הַמָּקוֹם שֶׁמַּצְנִיעִין אוֹתוֹ בּוֹ:"
    ],
    [
      "הַמִּנְהָג הַפָּשׁוּט בְּכָל יִשְׂרָאל שֶׁמַּשְׁלִימִין אֶת הַתּוֹרָה בְּשָׁנָה אַחַת. מַתְחִילִין בְּשַׁבָּת שֶׁאַחַר חַג הַסֻּכּוֹת וְקוֹרִין בְּסֵדֶר <small>(בראשית א א)</small> ״בְּרֵאשִׁית״. בַּשְּׁנִיָּה <small>(בראשית ו ט)</small> ״אֵלֶּה תּוֹלְדֹת״. בַּשְּׁלִישִׁית <small>(בראשית יב א)</small> ״וַיֹּאמֶר יְיָ׳‎ אֶל אַבְרָם״. וְקוֹרְאִין וְהוֹלְכִין עַל הַסֵּדֶר הַזֶּה עַד שֶׁגּוֹמְרִין אֶת הַתּוֹרָה בְּחַג הַסֻּכּוֹת. וְיֵשׁ מִי שֶׁמַּשְׁלִים אֶת הַתּוֹרָה בְּשָׁלֹשׁ שָׁנִים וְאֵינוֹ מִנְהָג פָּשׁוּט:",
      "עֶזְרָא תִּקֵּן לָהֶם לְיִשְׂרָאֵל שֶׁיְּהוּ קוֹרִין קְלָלוֹת שֶׁבְּסֵפֶר וַיִּקְרָא קֹדֶם עֲצֶרֶת וְשֶׁבְּמִשְׁנֵה תּוֹרָה קֹדֶם רֹאשׁ הַשָּׁנָה. וְהַמִּנְהָג הַפָּשׁוּט שֶׁיְּהוּ קוֹרְאִין <small>(במדבר א א)</small> ״בְּמִדְבַּר סִינַי״ קֹדֶם עֲצֶרֶת. <small>(דברים ג כג)</small> ״וָאֶתְחַנַּן״ אַחַר תִּשְׁעָה בְּאָב. <small>(דברים כט ט)</small> ״אַתֶּם נִצָּבִים״ קֹדֶם רֹאשׁ הַשָּׁנָה. <small>(ויקרא ו ב)</small> ״צַו אֶת אַהֲרֹן״ קֹדֶם הַפֶּסַח בְּשָׁנָה פְּשׁוּטָה. לְפִיכָךְ יֵשׁ שַׁבָּתוֹת שֶׁקּוֹרִין שַׁחֲרִית שְׁנֵי סְדָרִין כְּגוֹן <small>(ויקרא יב ב)</small> ״אִשָּׁה כִּי תַזְרִיעַ״ וְ<small>(ויקרא יד ב)</small> ״זֹאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע״. <small>(ויקרא כו ג)</small> ״אִם בְּחֻקֹּתַי״ עִם <small>(ויקרא כה א)</small> ״בְּהַר סִינַי״ וְכַיּוֹצֵא בָּהֶן כְּדֵי שֶׁיַּשְׁלִימוּ בְּשָׁנָה וְיִקְרְאוּ אוֹתָן הַסְּדָרִים בְּעוֹנָתָן:",
      "מָקוֹם שֶׁמַּפְסִיקִין בְּשַׁבָּת בְּשַׁחֲרִית שָׁם קוֹרְאִין בְּמִנְחָה וּבְשֵׁנִי וּבַחֲמִישִׁי וּלְשַׁבָּת הַבָּאָה. כֵּיצַד. שַׁבָּת רִאשׁוֹנָה קוֹרִין בְּשַׁחֲרִית בְּסֵדֶר <small>(בראשית א א)</small> ״בְּרֵאשִׁית״. בְּמִנְחָה קוֹרִין <small>(בראשית ו ט)</small> ״אֵלֶּה תּוֹלְדֹת נֹחַ״ עֲשָׂרָה פְּסוּקִים אוֹ יוֹתֵר. וְכֵן בְּשֵׁנִי וּבַחֲמִישִׁי. וְכֵן לְשַׁבָּת הַבָּאָה בְּשַׁחֲרִית מַתְחִילִין מֵאֵלֶּה תּוֹלְדֹת נֹחַ וְקוֹרֵא עַד סוֹף הַסֵּדֶר. וְעַל דֶּרֶךְ זוֹ קוֹרִין כָּל הַשָּׁנָה. וּמַפְטִירִין בְּכָל שַׁבָּת וְשַׁבָּת בַּנָּבִיא מֵעֵין שֶׁקָּרָא בַּתּוֹרָה: ",
      "וּבְרָאשֵׁי חֳדָשִׁים. הָרִאשׁוֹן קוֹרֵא שְׁלֹשָׁה פְּסוּקִים מִפָּרָשַׁת <small>(במדבר כח ב)</small> ״צַו״. וְהַשֵּׁנִי חוֹזֵר וְקוֹרֵא פָּסוּק ג׳‎ שֶׁקָּרָא הָרִאשׁוֹן וּשְׁנֵי פְּסוּקִים שֶׁאַחֲרָיו כְּדֵי שֶׁיְּשַׁיֵּר בַּפָּרָשָׁה שְׁלֹשָׁה פְּסוּקִים. וְהַשְּׁלִישִׁי קוֹרֵא שְׁלֹשָׁה פְּסוּקִים שֶׁשִּׁיֵּר הַשֵּׁנִי עִם <small>(במדבר כח ט)</small> ״וּבְיוֹם הַשַּׁבָּת״. וְהָרְבִיעִי קוֹרֵא <small>(במדבר כח יא)</small> ״וּבְרָאשֵׁי חָדְשֵׁיכֶם״. וְאִם חָל רֹאשׁ חֹדֶשׁ לִהְיוֹת בְּשַׁבָּת מוֹצִיאִין שְׁנֵי סְפָרִים בְּשַׁחֲרִית. בְּאֶחָד קוֹרִין בּוֹ סֵדֶר אוֹתָהּ שַׁבָּת וּבַשֵּׁנִי קוֹרֵא בּוֹ הַמַּשְׁלִים וּבְרָאשֵׁי חָדְשֵׁיכֶם. וְהַמַּפְטִיר קוֹרֵא עִנְיַן רֹאשׁ חֹדֶשׁ. וּמַפְטִירִין <small>(ישעיה סו כג)</small> ״וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ״. וְרֹאשׁ חֹדֶשׁ אָב שֶׁחָל לִהְיוֹת בְּשַׁבָּת מַפְטִירִין <small>(ישעיה א יד)</small> ״חָדְשֵׁיכֶם וּמוֹעֲדֵיכֶם שָׂנְאָה נַפְשִׁי״. וְרֹאשׁ חֹדֶשׁ שֶׁחָל לִהְיוֹת בְּאֶחָד בְּשַׁבָּת מַפְטִירִין בַּשַּׁבָּת שֶׁלְּפָנָיו <small>(שמואל א כ יח)</small> ״וַיֹּאמֶר לוֹ יְהוֹנָתָן מָחָר חֹדֶשׁ״: ",
      "כָּל הָעוֹלֶה לִקְרוֹת בַּתּוֹרָה פּוֹתֵחַ בְּדָבָר טוֹב וּמְסַיֵּם בְּדָבָר טוֹב. אֲבָל פָּרָשַׁת <small>(דברים לב א)</small> ״הַאֲזִינוּ״ קוֹרֵא הָרִאשׁוֹן עַד <small>(דברים לב ז)</small> ״זְכֹר יְמוֹת עוֹלָם״. וְהַשֵּׁנִי מַתְחִיל מִזְּכֹר יְמוֹת עוֹלָם עַד <small>(דברים לב יג)</small> ״יַרְכִּבֵהוּ״. וְהַשְּׁלִישִׁי מִיַּרְכִּבֵהוּ עַד וַיַּרְא ה׳‎ וַיִּנְאָץ. וְהָרְבִיעִי מִן וַיַּרְא ה׳‎ וַיִּנְאָץ עַד <small>(דברים לב כט)</small> ״לוּ חָכְמוּ״. וְהַחֲמִישִׁי מִן לוּ חָכְמוּ עַד <small>(דברים לב מ)</small> ״כִּי אֶשָּׂא אֶל שָׁמַיִם יָדִי״. וְהַשִּׁשִּׁי מִכִּי אֶשָּׂא אֶל שָׁמַיִם יָדִי עַד סוֹף הַשִּׁירָה. וְלָמָּה פּוֹסְקִין בָּהּ בְּעִנְיָנוֹת אֵלּוּ מִפְּנֵי שֶׁהֵן תּוֹכָחָה כְּדֵי שֶׁיַּחְזְרוּ הָעָם בִּתְשׁוּבָה: ",
      "שְׁמוֹנָה פְּסוּקִים שֶׁבְּסוֹף הַתּוֹרָה מֻתָּר לִקְרוֹת אוֹתָם בְּבֵית הַכְּנֶסֶת בְּפָחוֹת מֵעֲשָׂרָה. אַף עַל פִּי שֶׁהַכּל תּוֹרָה הִיא וּמשֶׁה מִפִּי הַגְּבוּרָה אֲמָרָם הוֹאִיל וּמַשְׁמָעָן שֶׁהֵם אַחַר מִיתַת משֶׁה הֲרֵי נִשְׁתַּנּוּ וּלְפִיכָךְ מֻתָּר לְיָחִיד לִקְרוֹת אוֹתָן:",
      "קְלָלוֹת שֶׁבְּתוֹרַת כֹּהֲנִים אֵין מַפְסִיקִין בָּהֶן אֶלָּא אֶחָד קוֹרֵא אוֹתָן מַתְחִיל בַּפָּסוּק שֶׁלִּפְנֵיהֶם וּמְסַיֵּם בַּפָּסוּק שֶׁל אַחֲרֵיהֶם. וּקְלָלוֹת שֶׁבְּמִשְׁנֵה תּוֹרָה אִם רָצָה לִפְסֹק בָּהֶן פּוֹסֵק וּכְבָר נָהֲגוּ הָעָם שֶׁלֹּא לִפְסֹק בָּהֶן אֶלָּא אֶחָד קוֹרֵא אוֹתָן:",
      "מַפְסִיקִין לְמוֹעֲדוֹת וּלְיוֹם הַכִּפּוּרִים וְקוֹרְאִין בְּעִנְיַן הַמּוֹעֵד, לֹא בְּסֵדֶר שַׁבָּת. וּמשֶׁה תִּקֵּן לָהֶם לְיִשְׂרָאֵל שֶׁיְּהוּ קוֹרְאִין בְּכָל מוֹעֵד עִנְיָנוֹ. וְשׁוֹאֲלִין וְדוֹרְשִׁין בְּעִנְיָנוֹ שֶׁל יוֹם בְּכָל מוֹעֵד וּמוֹעֵד. וּמַה הֵן קוֹרִין. בְּפֶסַח בְּפָרָשַׁת מוֹעֲדוֹת שֶׁבְּתוֹרַת כֹּהֲנִים. וּכְבָר נָהֲגוּ הָעָם לִקְרוֹת בְּיוֹם רִאשׁוֹן <small>(שמות יב כא)</small> ״מִשְׁכוּ וּקְחוּ לָכֶם״ וּמַפְטִירִין בְּ<small>(גמרא מגילה לא א)</small> ״פֶסַח גִּלְגָּל״. וּבְיוֹם טוֹב שֵׁנִי <small>(ויקרא כב כז)</small> ״שׁוֹר אוֹ כֶשֶׂב״ וּמַפְטִירִין בְּפֶסַח יֹאשִׁיָּהוּ. בַּשְּׁלִישִׁי <small>(שמות יג ב)</small> ״קַדֶּשׁ לִי כָל בְּכוֹר״. בָּרְבִיעִי <small>(שמות כב כד)</small> ״אִם כֶּסֶף תַּלְוֶה״. בַּחֲמִישִׁי <small>(שמות לד א)</small> ״פְּסָל לְךָ״. בְּשִׁשִּׁי <small>(במדבר ט ב)</small> ״וְיַעֲשׂוּ בְנֵי יִשְׂרָאֵל אֶת הַפָּסַח בְּמוֹעֲדוֹ״. בְּיוֹם טוֹב אַחֲרוֹן <small>(שמות יג יז)</small> ״וַיְהִי בְּשַׁלַּח״ עַד סוֹף הַשִּׁירָה עַד <small>(שמות טו כו)</small> ״כִּי אֲנִי ה׳‎ רֹפְאֶךָ״ וּמַפְטִירִין <small>(שמואל ב כב א)</small> ״וַיְדַבֵּר דָּוִד״. וּבַשְּׁמִינִי <small>(דברים טו יט)</small> ״כָּל הַבְּכוֹר״ וּמַפְטִירִין <small>(ישעיה י לב)</small> ״עוֹד הַיּוֹם״:",
      "בַּעֲצֶרֶת קוֹרִין בְּ<small>(דברים טז ט)</small> ״שִׁבְעָה שָׁבוּעוֹת״. וּמִנְהָג פָּשׁוּט שֶׁקּוֹרִים בְּיוֹם טוֹב הָרִאשׁוֹן <small>(שמות יט א)</small> ״בַּחֹדֶשׁ הַשְּׁלִישִׁי״ וּמַפְטִירִין בְּמֶרְכָּבָה. וּבְשֵׁנִי קוֹרִין בְּפָרָשַׁת מוֹעֲדוֹת <small>(דברים טו יט)</small> ״כָּל הַבְּכוֹר״ וּמַפְטִירִין בַּחֲבַקּוּק:",
      "בְּרֹאשׁ הַשָּׁנָה קוֹרִין <small>(במדבר כט א)</small> ״בַּחֹדֶשׁ הַשְּׁבִיעִי בְּאֶחָד לַחֹדֶשׁ״. וּמִנְהָג פָּשׁוּט שֶׁקּוֹרִין בְּיוֹם רִאשׁוֹן <small>(בראשית כא א)</small> ״וַיְיָ׳‎ פָּקַד אֶת שָׂרָה״ וּמַפְטִירִין <small>(שמואל א א א)</small> ״וַיְהִי אִישׁ אֶחָד מִן הָרָמָתַיִם״. וּבְשֵׁנִי קוֹרִין <small>(בראשית כב א)</small> ״וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם״ וּמַפְטִירִין <small>(ירמיה לא יט)</small> ״הֲבֵן יַקִּיר לִי אֶפְרַיִם״:",
      "בְּיוֹם הַכִּפּוּרִים בְּשַׁחֲרִית קוֹרִין <small>(ויקרא טז א)</small> ״אַחֲרֵי מוֹת״ וּמַפְטִירִין <small>(ישעיה נז טו)</small> ״כֹּה אָמַר רָם וְנִשָּׂא״. בְּמִנְחָה קוֹרִין בַּעֲרָיוֹת שֶׁבְּאַחֲרֵי מוֹת כְּדֵי שֶׁיִּזְכֹּר וְיִכָּלֵם כָּל מִי שֶׁנִּכְשַׁל בְּאַחַת מֵהֶן וְיַחֲזֹר בִּתְשׁוּבָה. וְהַשְּׁלִישִׁי קוֹרֵא בַּתּוֹרָה וּמַפְטִיר בְּיוֹנָה: ",
      "בְּסֻכּוֹת בִּשְׁנֵי יָמִים טוֹבִים הָרִאשׁוֹנִים קוֹרִין בְּפָרָשַׁת הַמּוֹעֲדוֹת שֶׁהִיא <small>(ויקרא כב כז)</small> ״שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז״ וְגוֹ׳‎ וּמַפְטִירִין בְּיוֹם רִאשׁוֹן <small>(זכריה יד א)</small> ״הִנֵּה יוֹם בָּא לַיְיָ׳‎״. וּבְיוֹם שֵׁנִי <small>(מלכים א ח ב)</small> ״וַיִּקָּהֲלוּ אֶל הַמֶּלֶךְ שְׁלֹמֹה״. וּבְיוֹם טוֹב אַחֲרוֹן קוֹרִין <small>(דברים טו יט)</small> ״כָּל הַבְּכוֹר״ וּמַפְטִירִין <small>(מלכים א ח נד)</small> ״וַיְהִי כְּכַלּוֹת שְׁלֹמֹה״. וּלְמָחָר קוֹרִין <small>(דברים לג א)</small> ״וְזֹאת הַבְּרָכָה״ וּמַפְטִירִין <small>(מלכים א ח כב)</small> ״וַיַּעֲמֹד שְׁלֹמֹה״. וְיֵשׁ מִי שֶׁמַּפְטִירִין <small>(יהושע א א)</small> ״וַיְהִי אַחֲרֵי מוֹת משֶׁה״. וּבִשְׁאָר יְמוֹת הֶחָג קוֹרִין בְּקָרְבְּנוֹת הֶחָג:",
      "כֵּיצַד. בְּכָל יוֹם וָיוֹם מֵחֻלּוֹ שֶׁל מוֹעֵד קוֹרֵא שְׁתֵּי פָּרָשִׁיּוֹת. <small>(במדבר כט כ)</small> ״בַּיּוֹם הַשְּׁלִישִׁי״ שֶׁהוּא חֻלּוֹ שֶׁל מוֹעֵד קוֹרֵא הַכֹּהֵן <small>(במדבר כט יז)</small> ״וּבַיּוֹם הַשֵּׁנִי״. וְלֵוִי קוֹרֵא וּבַיּוֹם הַשְּׁלִישִׁי. וְיִשְׂרָאֵל קוֹרֵא בַּיּוֹם הַשְּׁלִישִׁי. וְהָרְבִיעִי חוֹזֵר וְקוֹרֵא בַּיּוֹם הַשֵּׁנִי וּבַיּוֹם הַשְּׁלִישִׁי. וְכֵן בַּיּוֹם הָרְבִיעִי שֶׁהוּא שֵׁנִי שֶׁל חֻלּוֹ שֶׁל מוֹעֵד קוֹרִין וּבַיּוֹם הַשְּׁלִישִׁי <small>(במדבר כט כג)</small> ״וּבַיּוֹם הָרְבִיעִי״. וְעַל דֶּרֶךְ זוֹ בְּכָל יוֹם וָיוֹם: ",
      "בְּכָל יוֹם וְיוֹם מִיָּמִים טוֹבִים וְכֵן בְּיוֹם הַכִּפּוּרִים וּבְשִׁבְעַת יְמֵי הַפֶּסַח מוֹצִיאִין שְׁנֵי סְפָרִים בְּשַׁחֲרִית. הָרִאשׁוֹן קוֹרֵא בּוֹ אֵלּוּ הָעִנְיָנוֹת שֶׁאָמַרְנוּ. וְהַשֵּׁנִי קוֹרֵא בּוֹ קָרְבַּן אוֹתוֹ הַיּוֹם הָאָמוּר בְּחֻמַּשׁ הַפְּקֻדִּים בַּתּוֹרָה. וְהַקּוֹרֵא עִנְיַן הַקָּרְבָּן הוּא מַפְטִיר בַּנָּבִיא:",
      "וּבְכָל יוֹם שֶׁמּוֹצִיאִין שְׁנֵי סְפָרִים אוֹ שְׁלֹשָׁה אִם הוֹצִיאוּ זֶה אַחַר זֶה כְּשֶׁמַּחֲזִיר אֶת הָרִאשׁוֹן אוֹמֵר קַדִּישׁ וּמוֹצִיא הַשֵּׁנִי. וּכְשֶׁמַּחֲזִיר אֶת הָאַחֲרוֹן אוֹמֵר קַדִּישׁ. וּכְבָר אָמַרְנוּ שֶׁהַמִּנְהָג הַפָּשׁוּט לוֹמַר קַדִּישׁ אַחַר שֶׁקּוֹרֵא הַמַּשְׁלִים לְעוֹלָם וְאַחַר כָּךְ מַפְטִירִין בַּנָּבִיא:",
      "שַׁבָּת שֶׁחָלָה לִהְיוֹת בְּחֻלּוֹ שֶׁל מוֹעֵד בֵּין בְּפֶסַח בֵּין בְּסֻכּוֹת קוֹרִין בְּאוֹתָהּ שַׁבָּת <small>(שמות לג יב)</small> ״רְאֵה אַתָּה אֹמֵר אֵלַי״ וּמַפְטִירִין בְּפֶסַח <small>(יחזקאל לז ד)</small> ״הָעֲצָמוֹת הַיְבֵשׁוֹת״. וְאִם חָלָה בְּתוֹךְ הֶחָג <small>(יחזקאל לח יח)</small> ״בְּיוֹם בּוֹא גוֹג״:",
      "בַּחֲנֻכָּה בְּיוֹם רִאשׁוֹן קוֹרִין מִ<small>(במדבר ו כב)</small> ״בִּרְכַּת כֹּהֲנִים״ עַד סוֹף קָרְבַּן <small>(במדבר ז יב)</small> ״הַמַּקְרִיב בַּיּוֹם הָרִאשׁוֹן״. וּבְיוֹם שֵׁנִי קוֹרִין קָרְבַּן נָשִׂיא שֶׁהִקְרִיב בְּשֵׁנִי. וְכֵן עַד יוֹם הַשְּׁמִינִי. בְּיוֹם שְׁמִינִי קוֹרִין עַד סוֹף הַקָּרְבָּנוֹת עַד סוֹף הַסֵּדֶר. וּמַפְטִירִין בְּשַׁבָּת שֶׁל חֲנֻכָּה בְּנֵרוֹת זְכַרְיָה. וְאִם הָיוּ שְׁתֵּי שַׁבָּתוֹת בַּחֲנֻכָּה מַפְטִירִין בְּשַׁבָּת רִאשׁוֹנָה בְּנֵרוֹת זְכַרְיָה. וּבַשְּׁנִיָּה בְּנֵרוֹת שְׁלֹמֹה. וְהַקּוֹרֵא בְּעִנְיַן חֲנֻכָּה הוּא שֶׁמַּפְטִיר בַּנָּבִיא. בְּפוּרִים קוֹרִין בְּשַׁחֲרִית <small>(שמות יז ח)</small> ״וַיָּבֹא עֲמָלֵק״: ",
      "בְּתִשְׁעָה בְּאָב קוֹרִין בְּשַׁחֲרִית <small>(דברים ד כה)</small> ״כִּי תוֹלִיד בָּנִים״ וּמַפְטִירִין <small>(ירמיה ח יג)</small> ״אָסֹף אֲסִיפֵם נְאֻם יְיָ׳‎״. וּבְמִנְחָה קוֹרִין <small>(שמות לב יא)</small> ״וַיְחַל משֶׁה״ כִּשְׁאָר יְמֵי הַתַּעֲנִיּוֹת. וּבִשְׁאָר הַתַּעֲנִיּוֹת שֶׁאָנוּ מִתְעֲנִין עַל מַה שֶּׁאֵרַע לַאֲבוֹתֵינוּ קוֹרִין בְּשַׁחֲרִית וּמִנְחָה. הָרִאשׁוֹן קוֹרֵא וַיְחַל משֶׁה אַרְבַּע פְּסוּקִים. וְקוֹרֵא הַשֵּׁנִי וְהַשְּׁלִישִׁי מִ<small>(שמות לד א)</small> ״פְּסָל לְךָ״ עַד <small>(שמות לד י)</small> ״אֲשֶׁר אֲנִי עשֶֹׁה עִמָּךְ״. וּבְתַעֲנִיּוֹת שֶׁגּוֹזְרִין אוֹתָן הַצִּבּוּר מִפְּנֵי הַצָּרוֹת כְּגוֹן בַּצֹּרֶת וְדֶבֶר וְכַיּוֹצֵא בָּהֶן קוֹרִין בְּרָכוֹת וּקְלָלוֹת כְּדֵי שֶׁיָּשׁוּבוּ הָעָם וְיִכָּנַע לְבָבָם כְּשֶׁיִּשְׁמְעוּ אוֹתָם: ",
      "נָהֲגוּ הָעָם לִהְיוֹת מַפְטִירִין קֹדֶם תִּשְׁעָה בְּאָב בְּשָׁלֹשׁ שַׁבָּתוֹת בְּדִבְרֵי תּוֹכָחוֹת. שַׁבָּת רִאשׁוֹנָה מַפְטִירִין בְּ<small>(ירמיה א א)</small> ״דִבְרֵי יִרְמְיָהוּ״. שְׁנִיָּה <small>(ישעיה א א)</small> ״חֲזוֹן יְשַׁעְיָהוּ״. שְׁלִישִׁית <small>(ישעיה א כא)</small> ״אֵיכָה הָיְתָה לְזוֹנָה״. וְכֵן שַׁבָּת שֶׁאַחַר תִּשְׁעָה בְּאָב מַפְטִירִין <small>(ישעיה מ א)</small> ״נַחֲמוּ נַחֲמוּ עַמִּי״. וּמִנְהָג פָּשׁוּט בְּעִירֵנוּ לִהְיוֹת מַפְטִירִין בְּנֶחָמוֹת יְשַׁעְיָהוּ מֵאַחַר תִּשְׁעָה בְּאָב עַד רֹאשׁ הַשָּׁנָה. וְשַׁבָּת שֶׁבֵּין רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים מַפְטִירִין <small>(הושע יד ב)</small> ״שׁוּבָה יִשְׂרָאֵל״:",
      "רֹאשׁ חֹדֶשׁ אֲדָר שֶׁחָל לִהְיוֹת בְּשַׁבָּת קוֹרִין בְּפָרָשַׁת <small>(שמות ל יא טז)</small> ״שְׁקָלִים״ וּמַפְטִירִין בִּ<small>(מלכים ב יב ג)</small> ״יהוֹיָדָע הַכֹּהֵן״. וְכֵן אִם חָל רֹאשׁ חֹדֶשׁ אֲדָר לִהְיוֹת בְּתוֹךְ הַשַּׁבָּת וַאֲפִלּוּ בְּעֶרֶב שַׁבָּת מַקְדִּימִין וְקוֹרִין בַּשַּׁבָּת שֶׁלְּפָנָיו בְּפָרָשַׁת שְׁקָלִים. בַּשְּׁנִיָּה קוֹרִין <small>(דברים כה יז)</small> ״זָכוֹר״ וּמַפְטִירִין <small>(שמואל א טו ב)</small> ״פָּקַדְתִּי אֵת אֲשֶׁר עָשָׂה עֲמָלֵק״. אֵי זוֹ הִיא שַׁבָּת שְׁנִיָּה כָּל שֶׁחָל פּוּרִים לִהְיוֹת בְּתוֹכָהּ וַאֲפִלּוּ בְּעֶרֶב שַׁבָּת. בַּשְּׁלִישִׁית קוֹרִין <small>(במדבר יט א)</small> ״פָּרָה אֲדֻמָּה״ וּמַפְטִירִין <small>(יחזקאל לו כה)</small> ״וְזָרַקְתִּי עֲלֵיכֶם״. וְאֵי זוֹ הִיא שַׁבָּת שְׁלִישִׁית הַסְּמוּכָה לָרְבִיעִית. בָּרְבִיעִית קוֹרִין <small>(שמות יב ב)</small> ״הַחֹדֶשׁ הַזֶּה״ וּמַפְטִירִין <small>(יחזקאל מה יח)</small> ״בְּרִאשׁוֹן בְּאֶחָד לַחֹדֶשׁ״. וְאֵי זוֹ הִיא רְבִיעִית כָּל שֶׁחָל רֹאשׁ חֹדֶשׁ נִיסָן לִהְיוֹת בְּתוֹכָהּ וַאֲפִלּוּ בְּעֶרֶב שַׁבָּת: ",
      "נִמְצֵאתָ אוֹמֵר שֶׁפְּעָמִים תִּהְיֶה הַפְסָקָה בֵּין שַׁבָּת רִאשׁוֹנָה וּשְׁנִיָּה אוֹ בֵּין שְׁנִיָּה וּשְׁלִישִׁית. וּפְעָמִים יִהְיוּ שְׁתֵּי הַפְסָקוֹת בֵּין רִאשׁוֹנָה לִשְׁנִיָּה וּבֵין שְׁנִיָּה וּשְׁלִישִׁית. אֲבָל בֵּין שְׁלִישִׁית לִרְבִיעִית אֵין מַפְסִיקִין:",
      "כָּל פָּרָשָׁה מֵאַרְבַּע פָּרָשִׁיּוֹת הָאֵלּוּ אֶחָד קוֹרֵא אוֹתָהּ בְּסֵפֶר שֵׁנִי אַחַר שֶׁקּוֹרִין סֵדֶר אוֹתָהּ שַׁבָּת בַּסֵּפֶר שֶׁהוֹצִיאוּ רִאשׁוֹן. חָל רֹאשׁ חֹדֶשׁ אֲדָר לִהְיוֹת בְּשַׁבָּת וְהָיָה סֵדֶר אוֹתָהּ שַׁבָּת בִּ <small>(שמות כז כ)</small> ״וְאַתָּה תְּצַוֶּה״ קוֹרִין שִׁשָּׁה מִוְּאַתָּה תְּצַוֶּה עַד <small>(שמות ל יח)</small> ״וְעָשִׂיתָ כִּיּוֹר נְחשֶׁת״ וְהַשְּׁבִיעִי חוֹזֵר וְקוֹרֵא מִכִּי תִשָּׂא עַד וְעָשִׂיתָ כִּיּוֹר. וְאִם הָיָה סֵדֶר אוֹתָהּ שַׁבָּת כִּי תִשָּׂא עַצְמוֹ קוֹרִין שִׁשָּׁה מִכִּי תִשָּׂא עַד <small>(שמות לה א)</small> ״וַיַּקְהֵל״ וְהַשְּׁבִיעִי חוֹזֵר וְקוֹרֵא בְּסֵפֶר שֵׁנִי מִכִּי תִשָּׂא עַד וְעָשִׂיתָ כִּיּוֹר נְחשֶׁת: ",
      "רֹאשׁ חֹדֶשׁ אֲדָר שֶׁחָל לִהְיוֹת בְּשַׁבָּת מוֹצִיאִין שְׁלֹשָׁה סְפָרִים. הָרִאשׁוֹן קוֹרֵא בּוֹ סֵדֶר הַיּוֹם. וְהַשֵּׁנִי קוֹרֵא בּוֹ עִנְיַן רֹאשׁ חֹדֶשׁ. וְהַשְּׁלִישִׁי קוֹרִין בּוֹ <small>(שמות ל יב)</small> ״כִּי תִשָּׂא״. וְכֵן רֹאשׁ חֹדֶשׁ נִיסָן שֶׁחָל לִהְיוֹת בְּשַׁבָּת מוֹצִיאִין שְׁלֹשָׁה סְפָרִים. קוֹרִין סֵדֶר הַיּוֹם בָּרִאשׁוֹן. וְעִנְיַן רֹאשׁ חֹדֶשׁ בַּשֵּׁנִי. וְ<small>(שמות יב ב)</small> ״הַחֹדֶשׁ הַזֶּה״ בַּשְּׁלִישִׁי:",
      "רֹאשׁ חֹדֶשׁ טֵבֵת שֶׁחָל לִהְיוֹת בְּשַׁבָּת מוֹצִיאִין שְׁלֹשָׁה סְפָרִים. הָרִאשׁוֹן קוֹרֵא בּוֹ סֵדֶר הַיּוֹם. וְהַשֵּׁנִי קוֹרֵא בּוֹ עִנְיַן רֹאשׁ חֹדֶשׁ. וְהַשְּׁלִישִׁי קוֹרֵא בּוֹ עִנְיַן חֲנֻכָּה. חָל לִהְיוֹת בְּאֶמְצַע הַשַּׁבָּת שְׁלֹשָׁה קוֹרִין בְּעִנְיַן רֹאשׁ חֹדֶשׁ וְהָרְבִיעִי קוֹרֵא בְּעִנְיַן חֲנֻכָּה:",
      "אַף עַל פִּי שֶׁאָדָם שׁוֹמֵעַ כָּל הַתּוֹרָה כֻּלָּהּ בְּכָל שַׁבָּת בַּצִּבּוּר חַיָּב לִקְרוֹת לְעַצְמוֹ בְּכָל שָׁבוּעַ וְשָׁבוּעַ סֵדֶר שֶׁל אוֹתָהּ שַׁבָּת שְׁנַיִם מִקְרָא וְאֶחָד תַּרְגּוּם. וּפָסוּק שֶׁאֵין בּוֹ תַּרְגּוּם קוֹרְאֵהוּ שָׁלֹשׁ פְּעָמִים עַד שֶׁיַּשְׁלִים פָּרָשִׁיּוֹתָיו עִם הַצִּבּוּר:"
    ],
    [
      "בְּשַׁחֲרִית בְּמוּסָף וּבִנְעִילה הַכֹּהֲנִים נוֹשְׂאִים אֶת כַּפֵּיהֶם. אֲבָל בְּמִנְחָה אֵין נְשִׂיאַת כַּפַּיִם. מִפְּנֵי שֶׁבְּמִנְחָה כְּבָר סָעֲדוּ כָּל הָעָם וְשֶׁמָּא שָׁתוּ הַכֹּהֲנִים יַיִן וְשִׁכּוֹר אָסוּר בִּנְשִׂיאַת כַּפַּיִם. וַאֲפִלּוּ בְּיוֹם תַּעֲנִית אֵין נוֹשְׂאִין כַּפֵּיהֶן בְּמִנְחָה גְּזֵרָה מִנְחַת תַּעֲנִית מִפְּנֵי מִנְחַת כָּל יוֹם:",
      "בַּמֶּה דְּבָרִים אֲמוּרִים בְּתַעֲנִיּוֹת שֶׁמִּתְפַּלְּלִין בּוֹ מִנְחָה וּנְעִילָה כְּגוֹן צוֹם כִּפּוּר וְתַעֲנִית צִבּוּר. אֲבָל תַּעֲנִית שֶׁאֵין בּוֹ נְעִילָה כְּגוֹן תִּשְׁעָה בְּאָב וְשִׁבְעָה עָשָׂר בְּתַמּוּז הוֹאִיל וּתְפִלַּת מִנְחָה שֶׁלָּהֶם סָמוּךְ לִשְׁקִיעַת הַחַמָּה הֲרֵי נִרְאֵית כִּנְעִילָה וְאֵינָהּ מִתְחַלֶּפֶת בְּמִנְחָה שֶׁל כָּל יוֹם. וּלְפִיכָךְ יֵשׁ בָּהּ נְשִׂיאַת כַּפַּיִם. וְכֹהֵן שֶׁעָבַר וְעָלָה לַדּוּכָן בְּמִנְחָה שֶׁל יוֹם הַכִּפּוּרִים הוֹאִיל וְהַדָּבָר יָדוּעַ שֶׁאֵין שָׁם שִׁכְרוּת הֲרֵי זֶה נוֹשֵׂא כַּפָּיו וְאֵין מוֹרִידִין אוֹתוֹ מִפְּנֵי הַחֲשָׁד שֶׁלֹּא יֹאמְרוּ פָּסוּל הָיָה לְפִיכָךְ הוֹרִידוּהוּ:",
      "כֵּיצַד הִיא נְשִׂיאַת כַּפַּיִם בַּגְּבוּלִין. בְּעֵת שֶׁיַּגִּיעַ שְׁלִיחַ צִבּוּר לַעֲבוֹדָה כְּשֶׁיֹּאמַר רְצֵה כָּל הַכֹּהֲנִים הָעוֹמְדִים בְּבֵית הַכְּנֶסֶת נֶעֱקָרִין מִמְּקוֹמָן וְהוֹלְכִין וְעוֹלִין לַדּוּכָן וְעוֹמְדִים שָׁם פְּנֵיהֶם לַהֵיכָל וַאֲחוֹרֵיהֶם כְּלַפֵּי הָעָם וְאֶצְבְּעוֹתֵיהֶם כְּפוּפוֹת לְתוֹךְ כַּפֵּיהֶם עַד שֶׁיַּשְׁלִים שְׁלִיחַ צִבּוּר הַהוֹדָאָה וּמַחְזִירִין פְּנֵיהֶם כְּלַפֵּי הָעָם וּפוֹשְׁטִין אֶצְבְּעוֹתֵיהֶן וּמַגְבִּיהִין יְדֵיהֶם כְּנֶגֶד כִּתְפֵיהֶם וּמַתְחִילִין <small>(במדבר ו כד)</small> ״יְבָרֶכְךָ״. וּשְׁלִיחַ צִבּוּר מַקְרֵא אוֹתָם מִלָּה מִלָּה וְהֵם עוֹנִין שֶׁנֶּאֱמַר <small>(במדבר ו כג)</small> ״אָמוֹר לָהֶם״ עַד שֶׁיֹּאמַר. כְּשֶׁמַּשְׁלִימִין פָּסוּק רִאשׁוֹן כָּל הָעָם עוֹנִין אָמֵן. וְחוֹזֵר שְׁלִיחַ צִבּוּר וּמַקְרֵא אוֹתָן פָּסוּק שֵׁנִי מִלָּה מִלָּה וְהֵם עוֹנִים עַד שֶׁמַּשְׁלִימִין פָּסוּק שֵׁנִי וְכָל הָעָם עוֹנִין אָמֵן. וְכֵן בְּפָסוּק שְׁלִישִׁי:",
      "כְּשֶׁיַּשְׁלִימוּ הַכֹּהֲנִים שְׁלֹשָׁה פְּסוּקִים מַתְחִיל שְׁלִיחַ צִבּוּר בְּרָכָה אַחֲרוֹנָה שֶׁל תְּפִלָּה שֶׁהִיא שִׂים שָׁלוֹם וְהַכֹּהֲנִים מַחְזִירִין פְּנֵיהֶם כְּלַפֵּי הַקֹּדֶשׁ וְקוֹפְצִין אֶצְבְּעוֹתֵיהֶן וְעוֹמְדִין שָׁם בַּדּוּכָן עַד שֶׁיִּגְמֹר הַבְּרָכָה וְחוֹזְרִין לִמְקוֹמָן:",
      "אֵין הַמַּקְרֵא רַשַּׁאי (לְהַקְרוֹת לַכֹּהֲנִים) עַד שֶׁיִּכְלֶה אָמֵן מִפִּי הַצִּבּוּר. וְאֵין הַכֹּהֲנִים רַשָּׁאִין לְהַתְחִיל בַּבְּרָכָה עַד שֶׁיִּכְלֶה הַדִּבּוּר מִפִּי הַמַּקְרֵא. וְאֵין הַצִּבּוּר עוֹנִין אָמֵן עַד שֶׁתִּכְלֶה הַבְּרָכָה מִפִּי הַכֹּהֲנִים. וְאֵין הַכֹּהֲנִים מַתְחִילִין בִּבְרָכָה אַחֶרֶת עַד שֶׁיִּכְלֶה אָמֵן מִפִּי הַצִּבּוּר. וְאֵין שְׁלִיחַ צִבּוּר רַשַּׁאי לַעֲנוֹת אָמֵן אַחַר הַכֹּהֲנִים כִּשְׁאָר הָעָם שֶׁמָּא תִּטָּרֵף דַּעְתּוֹ וְלֹא יֵדַע אֵיזוֹ בְּרָכָה מַקְרֵא אוֹתָן, אִם פָּסוּק שֵׁנִי אוֹ פָּסוּק שְׁלִישִׁי:",
      "אֵין הַכֹּהֲנִים רַשָּׁאִין לְהַחֲזִיר פְּנֵיהֶם מִן הַצִּבּוּר עַד שֶׁיַּתְחִיל שְׁלִיחַ צִבּוּר שִׂים שָׁלוֹם. וְאֵין הַכֹּהֲנִים רַשָּׁאִין לֵעָקֵר מִמְּקוֹמָן עַד שֶׁיִּגְמֹר שְׁלִיחַ צִבּוּר שִׂים שָׁלוֹם. וְאֵין רַשָּׁאִין לָכֹף קִשְׁרֵי אֶצְבְּעוֹתֵיהֶם עַד שֶׁיַּחֲזִירוּ פְּנֵיהֶם מִן הַצִּבּוּר. וּמִתַּקָּנוֹת [ עֶזְרָא] שֶׁלֹּא יַעֲלוּ הַכֹּהֲנִים לַדּוּכָן בְּסַנְדְּלֵיהֶן אֶלָּא עוֹמְדִין יְחֵפִין:",
      "כְּשֶׁיִּהְיוּ הַכֹּהֲנִים מְבָרְכִין אֶת הָעָם לֹא יַבִּיטוּ בָּעָם וְלֹא יַסִּיחוּ דַּעְתָּן אֶלָּא יִהְיוּ עֵינֵיהֶם כְּנֶגֶד הָאָרֶץ כְּעוֹמֵד בִּתְפִלָּה. וְאֵין אָדָם רַשַּׁאי לְהִסְתַּכֵּל בִּפְנֵי הַכֹּהֲנִים בְּשָׁעָה שֶׁהֵן מְבָרְכִין אֶת הָעָם כְּדֵי שֶׁלֹּא יַסִּיחוּ דַּעְתָּם. אֶלָּא כָּל הָעָם מִתְכַּוְּנִין לִשְׁמֹעַ הַבְּרָכָה וּמְכַוְּנִים פְּנֵיהֶם כְּנֶגֶד פְּנֵי הַכֹּהֲנִים וְאֵינָם מַבִּיטִים בִּפְנֵיהֶם:",
      "אִם הָיָה הַכֹּהֵן הַמְבָרֵךְ אֶחָד מַתְחִיל לְבָרֵךְ מֵעַצְמוֹ. וּשְׁלִיחַ צִבּוּר מַקְרֵא אוֹתוֹ מִלָּה מִלָּה כְּמוֹ שֶׁאָמַרְנוּ. הָיוּ שְׁנַיִם אוֹ יוֹתֵר אֵינָן מַתְחִילִין לְבָרֵךְ עַד שֶׁיִּקְרָא לָהֶם שְׁלִיחַ צִבּוּר וְאוֹמֵר לָהֶם כֹּהֲנִים וְהֵם עוֹנִין וְאוֹמְרִים <small>(במדבר ו כד)</small> ״יְבָרֶכְךָ״. וְהוּא מַקְרֵא אוֹתָן מִלָּה מִלָּה עַל הַסֵּדֶר שֶׁאָמַרְנוּ:",
      "כֵּיצַד בִּרְכַּת כֹּהֲנִים בַּמִּקְדָּשׁ. הַכֹּהֲנִים עוֹלִין לַדּוּכָן אַחַר שֶׁיַּשְׁלִימוּ הַכֹּהֲנִים עֲבוֹדַת תָּמִיד שֶׁל שַׁחַר. וּמַגְבִּיהִין יְדֵיהֶם לְמַעְלָה עַל גַּבֵּי רָאשֵׁיהֶן וְאֶצְבְּעוֹתֵיהֶן פְּשׁוּטוֹת. חוּץ מִכֹּהֵן גָּדוֹל שֶׁאֵין מַגְבִּיהַּ יָדָיו לְמַעְלָה מִן הַצִּיץ. וְאֶחָד מַקְרֵא אוֹתָן מִלָּה מִלָּה כְּדֶרֶךְ שֶׁעוֹשִׂין בַּגְּבוּלִין עַד שֶׁיַּשְׁלִימוּ שְׁלֹשָׁה הַפְּסוּקִים. וְאֵין הָעָם עוֹנִין אַחַר כָּל פָּסוּק אֶלָּא עוֹשִׂין אוֹתָהּ בַּמִּקְדָּשׁ בְּרָכָה אַחַת. וּכְשֶׁיַּשְׁלִימוּ כָּל הָעָם עוֹנִים בָּרוּךְ יְיָ׳‎ אֱלֹהִים אֱלֹהֵי יִשְׂרָאֵל מִן הָעוֹלָם וְעַד הָעוֹלָם:",
      "וְאוֹמֵר אֶת הַשֵּׁם כִּכְתָבוֹ וְהוּא הַשֵּׁם הַנֶּהְגֶּה מִיּוּ״ד הֵ״א וָא״ו הֵ״א. וְזֶה הוּא הַשֵּׁם הַמְפֹרָשׁ הָאָמוּר בְּכָל מָקוֹם. וּבַמְּדִינָה אוֹמְרִים אוֹתוֹ בְּכִנּוּיוֹ וְהוּא בְּאָלֶ״ף דָּלֶ״ת. שֶׁאֵין מַזְכִּירִין אֶת הַשֵּׁם כִּכְתָבוֹ אֶלָּא בַּמִּקְדָּשׁ בִּלְבַד. וּמִשֶּׁמֵּת שִׁמְעוֹן הַצַּדִּיק פָּסְקוּ הַכֹּהֲנִים מִלְּבָרֵךְ בַּשֵּׁם הַמְפֹרָשׁ אֲפִלּוּ בַּמִּקְדָּשׁ כְּדֵי שֶׁלֹּא יִלְמֹד אוֹתוֹ אָדָם שֶׁאֵינוֹ חָשׁוּב וְשֶׁאֵינוֹ הָגוּן. וְלֹא הָיוּ חֲכָמִים הָרִאשׁוֹנִים מְלַמְּדִין שֵׁם זֶה לְתַלְמִידֵיהֶם וּבְנֵיהֶם הַהֲגוּנִים אֶלָּא פַּעַם אַחַת לְשֶׁבַע שָׁנִים. כָּל זֶה גְּדֻלָּה לִשְׁמוֹ הַנִּכְבָּד וְהַנּוֹרָא:",
      "אֵין בִּרְכַּת כֹּהֲנִים נֶאֱמֶרֶת בְּכָל מָקוֹם אֶלָּא בִּלְשׁוֹן הַקֹּדֶשׁ שֶׁנֶּאֱמַר <small>(במדבר ו כג)</small> ״כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל״. כָּךְ לָמְדוּ מִפִּי הַשְּׁמוּעָה מִמּשֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם כֹּה תְּבָרְכוּ בַּעֲמִידָה. כֹּה תְּבָרְכוּ בִּנְשִׂיאַת כַּפַּיִם. כֹּה תְּבָרְכוּ בִּלְשׁוֹן הַקֹּדֶשׁ. כֹּה תְּבָרְכוּ פָּנִים כְּנֶגֶד פָּנִים. כֹּה תְּבָרְכוּ בְּקוֹל רָם. כֹּה תְּבָרְכוּ בְּשֵׁם הַמְפֹרָשׁ. וְהוּא שֶׁיִּהְיֶה בַּמִּקְדָּשׁ כְּמוֹ שֶׁאָמַרְנוּ: ",
      "אֵין הַכֹּהֲנִים רַשָּׁאִין בְּכָל מָקוֹם לְהוֹסִיף בְּרָכָה עַל שְׁלֹשֶׁת הַפְּסוּקִים כְּגוֹן <small>(דברים א יא)</small> ״יְיָ׳‎ אֱלֹהֵי אֲבוֹתֵיכֶם יוֹסֵף עֲלֵיכֶם כָּכֶם אֶלֶף פְּעָמִים״ וְכַיּוֹצֵא בָּהּ לֹא בְּקוֹל רָם וְלֹא בְּלַחַשׁ שֶׁנֶּאֱמַר <small>(דברים ד ב)</small> ״לֹא תּוֹסִיפוּ עַל הַדָּבָר״. בְּשָׁעָה שֶׁכָּל כֹּהֵן עוֹלֶה לַדּוּכָן כְּשֶׁהוּא עוֹקֵר רַגְלָיו לַעֲלוֹת אוֹמֵר יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ שֶׁתִּהְיֶה בְּרָכָה זוֹ שֶׁצִּוִּיתָנוּ לְבָרֵךְ אֶת עַמְּךָ יִשְׂרָאֵל בְּרָכָה שְׁלֵמָה וְאַל יְהִי בָּהּ מִכְשׁוֹל וְעָוֹן מֵעַתָּה וְעַד עוֹלָם. וְקֹדֶם שֶׁיַּחֲזִיר פָּנָיו לְבָרֵךְ אֶת הָעָם מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בִּקְדֻשָּׁתוֹ שֶׁל אַהֲרֹן וְצִוָּנוּ לְבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה. וְאַחַר כָּךְ מַחֲזִיר פָּנָיו לַצִּבּוּר וּמַתְחִיל לְבָרְכָם. וּכְשֶׁמַּחֲזִיר פָּנָיו מִן הַצִּבּוּר אַחַר שֶׁמַּשְׁלִים אוֹמֵר עָשִׂינוּ מַה שֶּׁגָּזַרְתָּ עָלֵינוּ עֲשֵׂה עִמָּנוּ מַה שֶּׁהִבְטַחְתָּנוּ <small>(דברים כו טו)</small> ״הַשְׁקִיפָה מִמְּעוֹן קָדְשְׁךָ מִן הַשָּׁמַיִם וּבָרֵךְ אֶת עַמְּךָ אֶת יִשְׂרָאֵל״:",
      "כְּשֶׁמַּחְזִירִין הַכֹּהֲנִים אֶת פְּנֵיהֶם לַצִּבּוּר לְבָרְכָם וּכְשֶׁמַּחְזִירִין פְּנֵיהֶם מִן הַצִּבּוּר אַחַר שֶׁמְּבָרְכִין לֹא יַחֲזִירוּ אֶלָּא עַל דֶּרֶךְ יָמִין בְּכָל מָקוֹם. וְכֵן כָּל פִּנּוֹת שֶׁיִּהְיֶה אָדָם פּוֹנֶה לֹא יִהְיוּ אֶלָּא עַל דֶּרֶךְ יָמִין:",
      "בַּמִּקְדָּשׁ מְבָרְכִין בִּרְכַּת כֹּהֲנִים פַּעַם אַחַת בְּיוֹם אַחַר תָּמִיד שֶׁל שַׁחַר. בָּאִין וְעוֹמְדִין עַל מַעֲלוֹת הָאוּלָם וּמְבָרְכִין כְּדֶרֶךְ שֶׁאָמַרְנוּ. אֲבָל בַּמְּדִינָה מְבָרְכִין אוֹתָהּ אַחַר כָּל תְּפִלָּה חוּץ מִמִּנְחָה כְּמוֹ שֶׁאָמַרְנוּ. בְּכָל מָקוֹם מִשְׁתַּדְּלִין שֶׁיִּהְיֶה הַמַּקְרֵא אוֹתָן יִשְׂרָאֵל שֶׁנֶּאֱמַר <small>(במדבר ו כג)</small> ״אָמוֹר לָהֶם״ מִכְּלָל שֶׁאֵין הַמַּקְרֵא מֵהֶם:"
    ],
    [
      "שִׁשָּׁה דְּבָרִים מוֹנְעִין נְשִׂיאַת כַּפַּיִם. הַלָּשׁוֹן. וְהַמּוּמִין. וִהָעֲבֵרָה. וְהַשָּׁנִים. וְהַיַּיִן. וְטֻמְאַת הַיָּדַיִם. הַלָּשׁוֹן כֵּיצַד. הָעִלְּגִים שֶׁאֵין מוֹצִיאִין אֶת הָאוֹתִיּוֹת כְּתִקּוּנָן כְּגוֹן שֶׁקּוֹרִין לַאֲלֵפִי״ן עַיְנִי״ן וּלְעַיְנִי״ן אֲלֵפִי״ן אוֹ לְשִׁבּלֶת סִבּלֶת וְכַיּוֹצֵא בָּהֶן אֵין נוֹשְׂאִין אֶת כַּפֵּיהֶן. וְכֵן כְּבֵדֵי פֶּה וּכְבֵדֵי לָשׁוֹן שֶׁאֵין דִּבְרֵיהֶם נִכָּרִים לַכּל אֵין נוֹשְׂאִין אֶת כַּפֵּיהֶן:",
      "הַמּוּמִין כֵּיצַד. כֹּהֵן שֶׁיֵּשׁ מוּמִין בְּפָנָיו אוֹ בְּיָדָיו אוֹ בְּרַגְלָיו כְּגוֹן שֶׁהָיוּ אֶצְבְּעוֹתָיו עֲקֻמּוֹת אוֹ עֲקֻּשּׁוֹת אוֹ שֶׁהָיוּ יָדָיו בּוֹהֲקָנִיּוֹת לֹא יִשָּׂא אֶת כַּפָּיו לְפִי שֶׁהָעָם מִסְתַּכְּלִין בּוֹ. מִי שֶׁהָיָה רִירוֹ יוֹרֵד עַל זְקָנוֹ בְּשָׁעָה שֶׁהוּא מְדַבֵּר וְכֵן הַסּוּמָא בְּאַחַת מֵעֵינָיו לֹא יִשָּׂא אֶת כַּפָּיו. וְאִם הָיָה דַּשׁ בְּעִירוֹ וְהַכּל הָיוּ רְגִילִים בְּזֶה הַסּוּמָא בְּאַחַת מֵעֵינָיו אוֹ בְּזֶה שֶׁרִירוֹ זָב מֻתָּר לְפִי שֶׁאֵין מִסְתַּכְּלִין בּוֹ. וְכֵן מִי שֶׁהָיוּ יָדָיו צְבוּעוֹת אִסְטִיס וּפוּאָה לֹא יִשָּׂא אֶת כַּפָּיו. וְאִם רֹב אַנְשֵׁי הָעִיר מְלַאכְתָּן בְּכָךְ מֻתָּר לְפִי שֶׁאֵין מִסְתַּכְּלִין בּוֹ:",
      "הָעֲבֵרָה כֵּיצַד. כֹּהֵן שֶׁהָרַג אֶת הַנֶּפֶשׁ אַף עַל פִּי שֶׁעָשָׂה תְּשׁוּבָה לֹא יִשָּׂא אֶת כַּפָּיו שֶׁנֶּאֱמַר <small>(ישעיה א טו)</small> ״יְדֵיכֶם דָּמִים מָלֵאוּ״ וּכְתִיב <small>(ישעיה א טו)</small> ״וּבְפָרִשְׂכֶם כַּפֵּיכֶם״ וְגוֹ׳‎. וְכֹהֵן שֶׁעָבַד כּוֹכָבִים בֵּין בְּאֹנֶס בֵּין בִּשְׁגָגָה אַף עַל פִּי שֶׁעָשָׂה תְּשׁוּבָה אֵינוֹ נוֹשֵׂא אֶת כַּפָּיו לְעוֹלָם שֶׁנֶּאֱמַר <small>(מלכים ב כג ט)</small> ״אַךְ לֹא יַעֲלוּ כֹּהֲנֵי הַבָּמוֹת״ וְגוֹ׳‎. וּבְרָכָה כַּעֲבוֹדָה הִיא שֶׁנֶּאֱמַר <small>(דברים י ח)</small> ״לְשָׁרְתוֹ וּלְבָרֵךְ בִּשְׁמוֹ״. וְכֵן כֹּהֵן שֶׁהֵמִיר לְעַכּוּ״ם אַף עַל פִּי שֶׁחָזַר בּוֹ אֵינוֹ נוֹשֵׂא אֶת כַּפָּיו לְעוֹלָם. וּשְׁאָר הָעֲבֵרוֹת אֵין מוֹנְעִין:",
      "הַשָּׁנִים כֵּיצַד. כֹּהֵן נַעַר לֹא יִשָּׂא אֶת כַּפָּיו עַד שֶׁיִּתְמַלֵּא זְקָנוֹ. וְהַיַּיִן כֵּיצַד. מִי שֶׁשָּׁתָה רְבִיעִית יַיִן בְּבַת אַחַת אֵינוֹ נוֹשֵׂא אֶת כַּפָּיו עַד שֶׁיָּסִיר אֶת יֵינוֹ מֵעָלָיו לְפִי שֶׁהֻקְּשָׁה בְּרָכָה לַעֲבוֹדָה. שָׁתָה רְבִיעִית יַיִן בִּשְׁתֵּי פְּעָמִים אוֹ שֶׁנָּתַן לְתוֹכוֹ מְעַט מַיִם מֻתָּר. וְאִם שָׁתָה יוֹתֵר מֵרְבִיעִית אַף עַל פִּי שֶׁהָיָה מָזוּג אַף עַל פִּי שֶׁשְּׁתָאוֹ בְּכַמָּה פְּעָמִים לֹא יִשָּׂא אֶת כַּפָּיו עַד שֶׁיָּסִיר אֶת יֵינוֹ מֵעָלָיו. וְכַמָּה הִיא רְבִיעִית אֶצְבָּעִים עַל אֶצְבָּעִים בְּרוּם אֶצְבָּעִים וַחֲצִי אֶצְבַּע וְחֹמֶשׁ אֶצְבַּע כְּגוּדָל. וְזֶה הָאֶצְבַּע שֶׁמּוֹשְׁחִין בּוֹ בְּכָל הַתּוֹרָה כֻּלָּהּ הוּא הַגּוּדָל וְהוּא הַנִּקְרָא בֹּהֶן יָד:",
      "טֻמְאַת הַיָּדַיִם כֵּיצַד. כֹּהֵן שֶׁלֹּא נָטַל אֶת יָדָיו לֹא יִשָּׂא אֶת כַּפָּיו אֶלָּא נוֹטֵל אֶת יָדָיו עַד הַפֶּרֶק כְּדֶרֶךְ שֶׁמְּקַדְּשִׁין לַעֲבוֹדָה וְאַחַר כָּךְ מְבָרֵךְ שֶׁנֶּאֱמַר <small>(תהילים קלד ב)</small> ״שְׂאוּ יְדֵכֶם קֹדֶשׁ וּבָרַכוּ אֶת יְיָ׳‎״. וְהֶחָלָל אֵינוֹ נוֹשֵׂא אֶת כַּפָּיו לְפִי שֶׁאֵינוֹ בְּכִהוּנוֹ:",
      "כֹּהֵן שֶׁלֹּא הָיָה לוֹ דָּבָר מִכָּל אֵלּוּ הַדְּבָרִים הַמּוֹנְעִין נְשִׂיאַת כַּפַּיִם אַף עַל פִּי שֶׁאֵינוֹ חָכָם וְאֵינוֹ מְדַקְדֵּק בְּמִצְוֹת אוֹ שֶׁהָיוּ הַבְּרִיּוֹת מְרַנְּנִים אַחֲרָיו אוֹ שֶׁלֹּא הָיָה מַשָּׂאוֹ וּמַתָּנוֹ בְּצֶדֶק הֲרֵי זֶה נוֹשֵׂא אֶת כַּפָּיו וְאֵין מוֹנְעִין אוֹתוֹ לְפִי שֶׁזּוֹ מִצְוַת עֲשֵׂה עַל כָּל כֹּהֵן וְכֹהֵן שֶׁרָאוּי לִנְשִׂיאַת כַּפַּיִם וְאֵין אוֹמְרִים לְאָדָם רָשָׁע הוֹסֵף רֶשַׁע וְהִמָּנַע מִן הַמִּצְוֹת:",
      "וְאַל תִּתְמַהּ וְתֹאמַר וּמַה תּוֹעִיל בִּרְכַּת הֶדְיוֹט זֶה. שֶׁאֵין קִבּוּל הַבְּרָכָה תָּלוּי בַּכֹּהֲנִים אֶלָּא בְּהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנֶּאֱמַר <small>(במדבר ו כז)</small> ״וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרַכֶם״. הַכֹּהֲנִים עוֹשִׂים מִצְוָתָן שֶׁנִּצְטַוּוּ בָּהּ וְהַקָּדוֹשׁ בָּרוּךְ הוּא בְרַחֲמָיו מְבָרֵךְ אֶת יִשְׂרָאֵל כְּחֶפְצוֹ:",
      "עַם שֶׁהֵם אֲחוֹרֵי הַכֹּהֲנִים אֵינָם בִּכְלַל הַבְּרָכָה. וְהָעוֹמְדִים מִצִּדֵּיהֶן הֲרֵי הֵם בִּכְלַל הַבְּרָכָה. וְאִם הָיְתָה מְחִצָּה בֵּין הַכֹּהֲנִים וּבֵין הַמִּתְבָּרְכִים אֲפִלּוּ הִיא חוֹמָה שֶׁל בַּרְזֶל הוֹאִיל וּפְנֵיהֶם מוּל פְּנֵי הַכֹּהֲנִים הֲרֵי הֵם בִּכְלַל הַבְּרָכָה:",
      "נְשִׂיאַת כַּפַּיִם בַּעֲשָׂרָה וְכֹהֲנִים מִן הַמִּנְיָן. בֵּית הַכְּנֶסֶת שֶׁכֻּלָּן כֹּהֲנִים כֻּלָּם נוֹשְׂאִים אֶת כַּפֵּיהֶם. וּלְמִי הֵם מְבָרְכִים לְאַחֵיהֶם שֶׁבַּצָּפוֹן וְלַאֲחֵיהֶם שֶׁבַּדָּרוֹם. וּמִי עוֹנֶה אַחֲרֵיהֶם אָמֵן הַנָּשִׁים וְהַטַּף. וְאִם נִשְׁאֲרוּ שָׁם עֲשָׂרָה כֹּהֲנִים יוֹתֵר עַל אֵלּוּ שֶׁעָלוּ לַדּוּכָן הָעֲשָׂרָה עוֹנִין אָמֵן וְהַשְּׁאָר מְבָרְכִין:",
      "צִבּוּר שֶׁלֹּא הָיָה בָּהֶן כֹּהֵן אֶלָּא שְׁלִיחַ צִבּוּר לְבַדּוֹ לֹא יִשָּׂא אֶת כַּפָּיו. וְאִם הָיְתָה הַבְטָחָתוֹ שֶׁהוּא נוֹשֵׂא אֶת כַּפָּיו וְחוֹזֵר לִתְפִלָּתוֹ רַשַּׁאי. וְאִם אֵין לָהֶם כֹּהֵן כְּלָל כְּשֶׁיַּגִּיעַ שְׁלִיחַ צִבּוּר לְשִׂים שָׁלוֹם אוֹמֵר אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ בָּרְכֵנוּ בַּבְּרָכָה הַמְשֻׁלֶּשֶׁת בַּתּוֹרָה הַכְּתוּבָה עַל יְדֵי משֶׁה עַבְדְּךָ הָאֲמוּרָה מִפִּי אַהֲרֹן וּבָנָיו כֹּהֲנִים עַם קְדוֹשֶׁךָ כָּאָמוּר <small>(במדבר ו כד)</small> ״יְבָרֶכְךָ יְיָ׳‎ וְיִשְׁמְרֶךָ״ <small>(במדבר ו כה)</small> ״יָאֵר יְיָ׳‎ פָּנָיו אֵלֶיךָ וִיחֻנֶּךָּ״ <small>(במדבר ו כו)</small> ״יִשָּׂא יְיָ׳‎ פָּנָיו אֵלֶיךָ וְיָשֵׂם לְךָ שָׁלוֹם״ <small>(במדבר ו כז)</small> ״וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרַכֶם״. וְאֵין הָעָם עוֹנִין אָמֵן. וּמַתְחִיל וְאוֹמֵר שִׂים שָׁלוֹם: ",
      "כֹּהֵן שֶׁנָּשָׂא אֶת כַּפָּיו בְּבֵית הַכְּנֶסֶת וְהָלַךְ לְבֵית הַכְּנֶסֶת אַחֵר וּמָצָא צִבּוּר שֶׁמִּתְפַּלְּלִין וְלֹא הִגִּיעוּ לְבִרְכַּת כֹּהֲנִים נוֹשֵׂא יָדָיו לָהֶן וּמְבָרְכָן. וַאֲפִלּוּ כַּמָּה פְּעָמִים בְּיוֹם. כֹּהֵן שֶׁלֹּא עָקַר רַגְלָיו מִמְּקוֹמוֹ לַעֲלוֹת לַדּוּכָן בְּשָׁעָה שֶׁאָמַר שְׁלִיחַ צִבּוּר רְצֵה שׁוּב אֵינוֹ עוֹלֶה בְּאוֹתָהּ תְּפִלָּה. אֲבָל אִם עָקַר רַגְלָיו לַעֲלוֹת אַף עַל פִּי שֶׁלֹּא הִגִּיעַ לַדּוּכָן אֶלָּא אַחַר עֲבוֹדָה הֲרֵי זֶה עוֹלֶה וּמְבָרֵךְ:",
      "כָּל כֹּהֵן שֶׁאֵינוֹ עוֹלֶה לַדּוּכָן אַף עַל פִּי שֶׁבִּטֵּל מִצְוַת עֲשֵׂה אַחַת הֲרֵי זֶה כְּעוֹבֵר עַל שָׁלֹשׁ עֲשֵׂה שֶׁנֶּאֱמַר <small>(במדבר ו כג)</small> ״כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל״ <small>(במדבר ו כג)</small> ״אָמוֹר לָהֶם״ <small>(במדבר ו כז)</small> ״וְשָׂמוּ אֶת שְׁמִי״. וְכָל כֹּהֵן שֶׁאֵינוֹ מְבָרֵךְ אֵינוֹ מִתְבָּרֵךְ וְכָל כֹּהֵן הַמְבָרֵךְ מִתְבָּרֵךְ שֶׁנֶּאֱמַר <small>(בראשית יב ג)</small> ״וַאֲבָרַכָה מְבָרְכֶיךָ״:<br>סְלִיקוּ הִלְכוֹת תְּפִלָה בְּסִיַּעְתָּא דִּשְׁמַיָּא"
    ]
